int powmod(int a, int n) {
	if (n == 0) return 1;
	int sq = powmod(a, n / 2);
	sq = (sq * 1LL * sq) % mod;
	if (n % 2 == 0) return sq;
	return (sq * 1LL * a) % mod;
}

int newton(int a, int b) {
	if (b > a) return 0;
	int ans = (fac[a] * 1LL * ifac[b])%mod;
	return (ans * 1LL * ifac[a-b]) % mod;
}

