	for_(i,0,n+1) {
		if (a[i] == x) {
			if (L == -1) L = i;
			else R = n-i;
		}
	}

	Combination comb(n+2, mod);

	cout << n << endl;
	for_(k,2,n+2) {
		lint ans = comb.calc(n+1,k);
		modAdd(ans, -comb.calc(L+R, k-1), mod);
		cout << ans << endl;
	}
}

