constexpr long MOD = 1000000000 + 7;

long EXC[100009];

long exc(long a)
{
    return EXC[a];
}

long pw(long a, long p)
{
    if (p == 1)
        return a;

    if (p % 2 == 0) {
        long b = pw(a, p / 2);
        b *= b;
        b %= MOD;
        return b;
    }

    long b = pw(a, p - 1);
    b *= a;
    b %= MOD;
    return b;
}

long IEXC[100009];

long iexc(long a)
{
    return IEXC[a];
}

void init()
{
    EXC[0] = 1;
    IEXC[0] = 1;

    long v = 1;
    for (long i = 1; i < 100009; ++i) {
        v *= i;
        v %= MOD;
        EXC[i] = v;
        IEXC[i] = pw(v, MOD - 2);
    }
}

long comb(long a, long b)
{
    if (b > a)
        return 0;
    if (a - b < b)
        return comb(a, a - b);

    long p = exc(a);
    long q = iexc(a - b);
    long r = iexc(b);

    long v = p;
    v *= q;
    v %= MOD;
    v *= r;
    v %= MOD;
    // cerr << "COMB " << a << " " << b << " " << v << " (" << p << " " << q << " " << r << ")" << endl;
    return v;
}

int main()
{
