            break;
        }
        s.insert(x);
    }

    int l = -1;
    int r = -1;
    for (int i = 0; i < N; ++i) {
        if (a[i] == dupe) {
            if (l == -1)
                l = i;
            else
                r = i;
        }
    }

    assert(r != -1);

    int osz = l + (N - 1) - r;

    for (int k = 1; k <= N; ++k) {
        long p = comb(N, k);
        long q = comb(osz, k - 1);
        long v = (p + MOD - q) % MOD;
        cout << v << '\n';
    }

    return 0;
}

