const int Mod=1e9+7;
LL find(LL x)  
{  
    LL k=Mod-2,ans=1;  
    while(k)  
    {  
        if (k&1) 
            ans=ans*x%Mod;  
        x=x*x%Mod;  
        k>>=1;  
    }  
    return ans;  
} 
LL C(LL n, LL m)  
{  
    if(m > n) return 0;  
    LL ans = 1;  
    for(int i=1; i<=m; i++)  
    {  
        LL a = (n + i - m) % Mod;  
        LL b = i % Mod;  
        ans = ans * (a * find(b)% Mod) % Mod;  
    }  
    return ans;  
}  

LL Lucas(LL n, LL m)  
{  
    if(m == 0) return 1;  
    return C(n % Mod, m % Mod) * Lucas(n / Mod, m / Mod) % Mod;  
}  
