long long dp[100002][100002];

long long comp_dp(int n, int r) {
    for (int i=0; i<=n; ++i) {
        for (int j=0; j<=i; ++j) {
            if (i == 0 or i == j) dp[i][j] = 1;
            else dp[i][j] = dp[i-1][j] + dp[i-1][j-1];
        }
    }
    return dp[n][r];
}

