#define M 1000000007

typedef pair<long long int, long long int> P;

long long int extgcd(long long int a, long long int b, long long int& x, long long int& y) {
	long long int d = a;
	if (b != 0) {
		d = extgcd(b, a % b, y, x);
		y -= (a / b) * x;
	}
	else {
		x = 1; y = 0;
	}
	return d;
}

long long int mod_inverse(long long int a) {
	long long int x, y;
	extgcd(a, M, x, y);
	//cout << a << ' ' << M << endl;
	return (M + x % M) % M;
}

long long int ncr(long long int n, long long int r) {
	if (r == 0) {
		return 1;
	}
	if (n < r) {
		return 0;
	}
	r = min(r, n - r);
	long long int ans = 1;
	for (long long int i = 1; i <= r; i++) {
		ans *= (n - (i - 1));
		ans *= mod_inverse(i);
		ans %= M;
	}
	return ans;
}

