int main() {
	long long int N;
	cin >> N;
	if( N==1 ) {
		cout << 2 << endl;
		return 0;
	}
	vector<long long int>D( N + 1, -1 );
	pair<long long int, long long int>memo;
	for( long long int i = 0; i < N; i++ ) {
		long long int X;
		cin >> X;
		if( D[X - 1] != -1 ) {
			memo.first = D[X - 1];
