long long fastPow(long long base, long long e){
  long long foo = 1, bar = base;
  while(e){
    if(e & 1){
      foo = foo * bar % MOD;
    }
    bar = bar * bar % MOD;
    e >>= 1;
  }
  return foo;
}

long long cnm(int n, int m){
  return fac[n] * fastPow(fac[m] * fac[n - m] % MOD, MOD - 2) % MOD;
}

