#define M 1000000007

long long int ncr(long long int n, long long int r) {
	if (r == 0) {
		return 1;
	}
	if (n < r) {
		return 0;
	}
	r = min(r, n - r);
	long long int ans = 1;
	for (long long int i = 1; i <= r; i++) {
		ans *= (n - (i - 1));
		ans /= i;
		ans %= M;
	}
	return ans;
}

