#define ll long long
const ll mod = 1000000007;
ll powmod(ll x, ll n) {
	ll res = 1;
	while (n > 0) {
		if (n & 1) {
			res = (res*x) % mod;
		}
		x = (x*x) % mod;
		n >>= 1;
	}
	return res;
}

ll fact[100050];

void init() {
	fact[0] = 1;
	for (int i = 1;i < 10050;i++) {
		fact[i] = i *fact[i - 1];
		fact[i] %= mod;
	}
}

int main() {
