const ll MOD=1000000007;


pii extendedEuclid(ll a,ll b){
  bool swapped=false;
  if(a<b) {swap(a,b);swapped=true;}
  pii x={1,0},y={0,1};
  while(1){
    ll xv=a*x.first+b*x.second;
    ll yv=a*y.first+b*y.second;
    if(yv==0) {if(swapped) return {x.second,x.first}; else return x;}
    ll d=xv/yv;
    swap(x,y);
    y.first-=d*x.first;
    y.second-=d*x.second;
  }
}

ll inverse(ll a,ll mod) {
  return (mod+extendedEuclid(a,mod).first%mod)%mod;
}

ll combination(ll a,ll b,ll mod) {
  ll ret=1;
  for(ll i=0;i<b;i++) ret=ret*(a-i)%mod;
  for(ll i=1;i<=b;i++) ret=ret*inverse(i,mod)%mod;
  return ret;
}


