long long power(long long x, long long n){
    long long res = 1;
    x %= MOD;
    while(n > 0LL){
        if(n & 1LL){
            res *= x;
            res %= MOD;
        }
        x *= x;
        x %= MOD;
        n >>= 1;
    }
    return res;
}

long long moddiff(long long a, long long b){
    long long res = a - b;
    if(res < 0LL){
        long long t = (abs(res) - 1LL) / MOD + 1LL;
        res += MOD * t;
    }
    res %= MOD;
    return res;
}

lint comb(int n, int r){
    if(n < r){
        return 0LL;
    }
    return (((fact[n] * inv[r]) % MOD) * inv[n - r]) % MOD;
}

