#define DIV 1000000007

long long modpow(long long ori, long long po){
	long long res = 1;
	while(po > 0){
		if(po&1){
			res *= ori;
			res %= DIV;
		}
		ori *= ori;
		ori %= DIV;
		po >>= 1;
	}
	return res;
}

void pre(){
	memo[0] = 1;
	memo[1] = 1;
	for(long long i = 1; i < 100003; i++){
		memo[i+1] = memo[i] * (i+1);
		memo[i+1] %= DIV;
	}
}

long long comb(long long A, long long B){
	if(A < B){
		return 0;
	}
	long long ans = memo[B] * memo[A-B];
	ans = memo[A] * modpow(ans, DIV - 2);
	ans %= DIV;
	return ans;
}

long long cal(long long num){
	long long ff,ss;
	ff = comb(n + 1, num);
	ss = comb(n - pos, num-1);
	return (ff - ss + DIV)%DIV;
}

