对于一个数的贡献，我最好是区间的贡献，也就是1-n的贡献。

C(N-1,LEN)+[C(N-1,LEN-1)*2-C(N-DIS-1,LEN-1)]+C(N-1,LEN-2)
*/
const LL mod = 1e9+7;
const int N=1e5+10;
int a[N],id[N],v[N];
LL f[N];

LL cal(LL g,LL x)
{
    LL ans=1;
    while(g)
    {
        if(g&1) ans=ans*x%mod;
        x=x*x%mod;
        g>>=1;
    }
    return ans;
}
LL C(LL m,LL n)
{
    return f[n]*cal(mod-2,f[n-m])%mod*cal(mod-2,f[m])%mod;
}

void init()
{
    f[0]=1;
    for(LL i=1;i<=100000;i++)
        f[i]=f[i-1]*i%mod;
