void factorial(int N){
  f[0]=1;
  fi[0]=1;
  for(int i=1;i<=N;i++){
    f[i]=(f[i-1]*i)%INF;
    fi[i]=power(f[i],INF-2);
  }
}

long long C(int n,int r){
  if(r==0) return 1;
  else return (((f[n]*fi[r]) %INF) *fi[n-r] ) % INF;
}

