struct BIT
{
    std::vector<int> bit;

    BIT(int size) : bit(size, 0){ }

    void add(int k, int x) {
        while (k < bit.size()) {
            bit[k] += x;
            k += k &-k;
        }
    }
    int sum(int k) {
        int res = 0;
        while (k > 0) {
            res += bit[k];
            k -= k&-k;
        }
        return res;
    }
};

struct UnionFind {
    vector<int> data;

    UnionFind(int size) : data(size, -1) { }

    bool unionSet(int x, int y) {
        x = root(x); y = root(y);
        if (x != y)
        {
            if (data[y] < data[x]) swap(x, y);
            data[x] += data[y]; data[y] = x;
        }
        return x != y;
    }
    bool findSet(int x, int y) {
        return root(x) == root(y);
    }
    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }
    int size(int x) {
        return -data[root(x)];
    }
};


using namespace std;

const int MOD = 1000000007;

ll exp_mod(ll a) {
    ll res = 1;
    ll b = MOD-2;
    while (b > 0) {
        if (b&1)
            res = (res * a)%MOD;
        a = (a * a)%MOD;
        b >>= 1;
    }
    return res;
}

ll memo1[10000000];


void extgcd( ll a, ll b, ll* x, ll* y, ll* d )
{
    ll u, v, q, tmp;

    *x = 1; *y = 0; u = 0; v = 1;
    while ( b > 0 ) {
        q = a / b;
        tmp = u; u = *x - q * u; *x = tmp;
        tmp = v; v = *y - q * v; *y = tmp;
        tmp = b; b = a - q * b; a = tmp;
    }
    *d = a;
}

ll mod_inverse(ll a, ll m)
{
    ll x,y,d;
    extgcd(a, m, &x, &y, &d);
    return (m + x % m) % m;
}

void build(ll n, ll* m)
{
    ll res = 1;
    for (int i=1; i<=n; ++i)
    {
        res = (res * i )%MOD;
        m[i] = res;
    }
}

ll mod_fact(int n, ll& e, const ll fact[])
{
    e = 0;
    if(n == 0)
    {
        return 1;
    }
    ll rest = mod_fact(n/MOD, e, fact);
    e += n / MOD;
    if(n / MOD % 2 != 0)
    {
        return rest * (MOD - fact[n % MOD]) % MOD;
    }
    return rest * fact[n % MOD] % MOD;
}

ll mod_comb(int n, int k, const ll fact[])
{
    if(n < 0 || k < 0|| n < k)
    {
        return 0;
    }
    ll e1,e2,e3;
    ll a1 = mod_fact(n, e1, fact);
    ll a2 = mod_fact(k, e2, fact);
    ll a3 = mod_fact(n-k, e3, fact);
    if(e1 > e2 + e3)
    {
        return 0;
    }
    ll r = a1 * mod_inverse(a2 * a3 % MOD, MOD) % MOD;
    return r;
}


