struct umod{
    ll number;
    umod(): number(0LL){}
    umod(ll _number){ _number %= mod; if(_number < 0) _number += mod; number = _number;}
    umod& operator += (umod that){ number += that.number; if(number >= mod) number -= mod;return *this;}
    umod& operator -= (umod that){ number += mod - that.number; if(number >= mod) number -= mod;return *this;};
    umod& operator *= (umod that){ number = number*that.number%mod; return *this;}
    umod& operator /= (umod that){ return *this *= that.inverse();}
    umod operator + (umod that) const { return umod(*this) += that;}
    umod operator - (umod that) const { return umod(*this) -= that;}
    umod operator * (umod that) const { return umod(*this) *= that;}
    umod operator / (umod that) const { return umod(*this) /= that;}
    bool operator < (umod that) const { return number < that.number;}
    bool operator > (umod that) const { return number > that.number;}
    bool operator <= (umod that) const { return number <= that.number;}
    bool operator >= (umod that) const { return number >= that.number;}
    bool operator == (umod that) const { return number == that.number;}
    bool operator != (umod that) const { return number != that.number;}
    umod inverse() const {
        ll a = number, b = mod, u = 1, v = 0;
        while(b){
            ll t = a/b;
            a -= t*b; swap(a, b);
            u -= t*v; swap(u, v);
        }
        if(u < 0) u += mod;
        return u;
    }
};
