            // printf("-- %lld\n", cnt.number);
            ans += cnt;
        }
        if(e >= 2){
            big add = fat[n-1]/(fat[n-1-(e - 1)]*fat[e-1]);
            big dec = 0;
            if(n - 1 - (posB - posA - 1) >= e-1)
                dec = fat[n - posB + posA]/(fat[(n - posB + posA)-(e-1)]*fat[e-1]);
            add -= dec;
            ans += add;
        }
        printf("%lld\n", ans.number);
    }
    printf("1\n");
    return 0;
}

