long long mod_inverse(long long x) {
	long  long ret = 1; long long n = mod - 2;
	while (n) {
		if (n & 1)ret = ret * x % mod;
		x = x * x % mod; n >>= 1;
	}
	return ret;
}

ll fact[100100], inv_fact[100100];

ll comb(ll n, ll r) {
    if(n < r || r < 0) return 0;
    ll ret = fact[n] * inv_fact[n - r] % mod * inv_fact[r] % mod;
    return ret;
}

