ll mod = 1000000000+7;

ll sol(ll tar_, ll kei_){
    ll s;
    if(kei_ == 0){return 1;}
    if(kei_ == 1){return tar_ % mod;}
    s = sol(tar_, kei_ / 2);
    if(kei_ % 2 == 0){
        return (s*s)%mod;
    }else{
        return (tar_*s%mod*s)%mod; 
    }
}


