int ipow(int a, int b) {
	int r = 1, w = a;
	while (b) {
		if (b & 1) r = 1ll * r * w % p;
		w = 1ll * w * w % p;
		b >>= 1;
	}
	return r;
}

int jc[N], njc[N], shown[N], n;

int C(int a, int b) {
	if (b > a) return 0;
	return 1ll * jc[a] * njc[b] % p * njc[a - b] % p;
}

