const int mod = 1e9 + 7;
int fact[100001], re_fact[100001];

int p(int a, int b)
{
	if (b == 0) 
		return 1;
	int tmp = p(a, b / 2);
	if (b%2 == 0) return (1LL * tmp * tmp)%mod;
	return ((1LL * tmp * tmp)%mod * a)%mod;
}

int comb(int k, int n)
{
	if (k < 0 || k > n) return 0;
	int tmp = ((1LL * fact[n] * re_fact[k])%mod * re_fact[n - k])%mod;
	return tmp;
}

int n;
int a[100001], pos[100001];    
int L, R;

int32_t main(int argc, char** argv)
{
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	fact[0] = 1;
	for (int i=1;i<=100000;i++) fact[i] = (1LL * fact[i-1] * i)%mod;
	re_fact[100000] = p(fact[100000], mod - 2);
	for (int i=100000;i>=1;i--) re_fact[i-1] = (1LL* re_fact[i] * i)%mod;

	cin >> n;
	n++;
	for (int i=1;i<=n;i++)
	{
		cin >> a[i];
		if (pos[a[i]])
