			L = pos[a[i]] - 1;
			R = n - i;
		}
		pos[a[i]] = i;
	}	
	cout << n - 1 << '\n';
	for (int k=2;k<=n;k++)
	{
		int res = comb(k, n);
		res = ((res - comb(k - 1, L + R))%mod + mod)%mod;
		cout << res << '\n';
	}	
}

