long gcd(long a, long b)
{
    if (b > a)
        swap(a, b);
    if (b == 0)
        return a;
    if (b == 1)
        return 1;
    return gcd(b, a % b);
}

long COMB[50001][

long comb(long a, long b)
{
    if (b > a)
        return 0;
    if (a - b < b)
        return comb(a, a - b);

    long x = 1;

    vector<long> cs;
    cs.push_back(1);
    for (long i = 2; i <= b; ++i) {
        if (cs.back() >= 1000000000) {
            cs.push_back(1);
        }
        cs.back() *= i;
    }

    for (long i = 0; i < b; ++i) {
        long d = a - i;
        for (long& c : cs) {
            long g = gcd(d, c);
            // cerr << "    " << i << " " << d << " " << g << endl;
            d /= g;
            c /= g;
        }
        x *= d;
        x %= MOD;
    }
    // assert(c == 1);

    // cerr << "GCD " << a << ' ' << b << ' ' << x << endl;
    return x;
}

