		l <<= 1;
	revv[0] = 0;
	half = (l >> 1);
	for(int i = 1 ; i < l ; ++ i)
		revv[i] = ((revv[i >> 1] >> 1) | ((i & 1) ? half : 0));
	for(int i = half ; i < l ; ++ i)
		wu1[i] = Complex(cos(2 * pi * (i ^ half) / l) , sin(2 * pi * (i ^ half) / l));
	for(int i = half - 1 ; i >= 0 ; -- i)
		wu1[i] = wu1[i << 1];
	for(int i = 0 ; i < l ; ++ i)
		wu2[i] = wu1[i].conj();
	Complex().fft(a , wu1);
	Complex().fft(b , wu1);
	for(int i = 0 ; i < l ; ++ i)
		c[i] = a[i] * b[i];
	Complex().ifft(c , wu2);
}
int power(int x , int times){
	if(!times)
		return 1;
	int tmp = power(x , times / 2);
	tmp = 1ll * tmp * tmp % mod;
	if(times % 2 == 0)
		return tmp;
	return 1ll * tmp * x % mod;
}
int getrev(int x){
	return power(x , mod - 2);
}
void get(int end , int *t){
	t[0] = 1;
	for(int i = 1 ; i <= end + 1 ; ++ i)
		t[i] = 1ll * t[i - 1] * (end + 1 - i) % mod * rev[i] % mod;
}
