ll INF = 1000000007;

int main() {
	ll n, a;
	vector<ll> v;
	set<ll> s;
	ll d = 0;
	ll e = 0;
	ll x = 0;

	cin >> n;

	REP(i, n + 1) {
		cin >> a;
		v.push_back(a);
		if (!s.count(a)) {
			s.insert(a);
		}
		else {
			d = i;
			x = a;
		}
	}

	REP(i, n + 1) {
		if (v[i] == x) {
			e = i;
			break;
		}
	}

	REP(i, n + 1) {
		ll ans = 0;

		REP(j, n + 1 - i) {
			ans += combi(n - j, i) % INF;
			ans = ans % INF;
		}

		if (n - d >= i) {
			ans -= combi(n - d, i) % INF;
			ans = ans % INF;
		}

		if (e > 0) {
			if (e + n - d >= i) {
				for (int j = 1; j <= e; j++) {
					if (i - j >= 0) {
						ans -= combi(e, j) * combi(n - d, i - j) % INF;
						ans = ans % INF;
					}
				}
			}
		}

		cout << ans << endl;
	}
}

ll combi(ll n, ll r)
{
	ll i;
	ll p = 1;

	if (n == 0 || r == 0) {
		return 1;
	}

	for(i = 1; i <= r; i++) {
		p = p * (n - i + 1) / i;
	}
	return p;
}

