void init(int n) {
	fact.resize(n);
	fact[0] = 1;
	for (int i = 1; i < n; i++) {
		fact[i] = i * fact[i - 1] % mod;
	}
	inv.resize(n);
	inv[n - 1] = f(fact[n-1],mod-2,mod); //modinv(fact[n - 1]);
	for (int i = n - 2; i >= 0; i--) {
		inv[i] = (i + 1) * inv[i + 1] % mod;
	}
}

