vector < int > pos[maxn];

int sa[1 << 18] , sb[1 << 18] , sc[1 << 18];

int C( int n , int m ){
	if( n < m )
		return 0;
	if( n == 0 && m == 0 )
		return 1;
	return mul( fac[n] , power_mod( mul( fac[m] , fac[n - m] ) , mod - 2 ) );
}

