		int x = read();
		pos[x].emplace_back( i );
	}
	for(int i = 1 ; i <= n ; ++ i)
		if( pos[i].size() == 2 ){
			int x = pos[i][0] - 1;
			int y = n + 1 - pos[i][1];
			for(int j = 0 ; j <= x ; ++ j)
				sa[j] = power_mod( mul( fac[j] , fac[x - j] ) , mod - 2 );
			for(int j = 0 ; j <= y ; ++ j)
				sb[j] = power_mod( mul( fac[j] , fac[y - j] ) , mod - 2 );
            int z = 1;
            while( z < x + y + 1 ) z <<= 1;
            Poly::Mul( sa , sb , sc , z );
			base = mul( fac[x] , fac[y] );
			break;
		}
	for(int i = 0 ; i <= n ; ++ i)
		b[i] = mul( sc[i] , base );
	printf( "%d\n" , n );
	n ++ ;
	for(int i = 2 ; i <= n ; ++ i){
		int ans = C( n - 2 , i );
		upd( ans , C( n - 2 , i - 2 ) );
		upd( ans , mul( 2 , C( n - 2 , i - 1 ) ) );
		upd( ans , mod - b[i - 1] );
		printf( "%d\n" , ans );
	}
	return 0;
}

