void calcnCr() {
    nCr0[0] = 1;
    REPCLS(i, N+1 - 2) {
        nCr0[i] = nCr0[i - 1];
        nCr0[i] *= (N+1-2)-(i-1); nCr0[i] %= m;
        nCr0[i] *= invMod(i, m); nCr0[i] %= m;
        DOUT(nCr0[i]);
    }
    nCr1[0] = 1;
    REPCLS(i, N+1 - 2 - cntInTwin) {
        nCr1[i] = nCr1[i - 1];
        nCr1[i] *= (N+1-2 - cntInTwin)-(i-1); nCr1[i] %= m;
        nCr1[i] *= invMod(i, m); nCr1[i] %= m;
        DOUT(nCr1[i]);
    }
}

