namespace solution{
	ll C(ll a,ll b){
		if(b>a||a<0||b<0)return 0;
		return fac[a]*inv[b]%mod*inv[a-b]%mod;
	}
	void Prepare(){
		fac[0]=1;inv[1]=1;inv[0]=1;
		up(i,1,LIM)fac[i]=fac[i-1]*i%mod;
		up(i,2,LIM)inv[i]=(mod-mod/i)*inv[mod%i]%mod;
		up(i,1,LIM)(inv[i]*=inv[i-1])%=mod;
		scanf("%lld",&N);
