        long d = a - i;
        for (long& c : cs) {
            long g = gcd(d, c);
            // cerr << "    " << i << " " << d << " " << g << endl;
            d /= g;
            c /= g;
        }
        x *= d;
        x %= MOD;
    }
    // assert(c == 1);

    // cerr << "GCD " << a << ' ' << b << ' ' << x << endl;
    COMB[a][b] = x;
    return x;
}

