ll fact(ll n) {
	if(n == 0) return fact_[n] = 1;
	if(n == 1) return fact_[n] = 1;
	if(fact_[n] != 0) return fact_[n];
	return fact_[n] = (n * fact(n-1)) % MOD;
}

//aのb乗
ll powMod(ll a, ll b) {
	ll res = 1;
	while(b > 0) {
		if(b & 1) res = res * a % MOD;
		if(res==0) res = MOD;
		a = a * a % MOD;
		if(a==0) a = MOD;
		b >>= 1;
	}
	return res;
}

ll comb(ll a, ll b){
	if(a == 0 || b == 0) return 1;
	return (((fact(a)*powMod(fact(b),MOD-2))%MOD)*powMod(fact(a-b),MOD-2))%MOD;
}

