void solve(long long n, std::vector<long long> a) {
    vector<int> seen(n + 1, -1);
    int dup;
    for(int i = 0; i <= n; i++) {
        if(seen[a[i]] >= 0) {
            dup = i - seen[a[i]];
        }
        seen[a[i]] = i;
    }
    for(int k = 1; k <= n + 1; k++) {
        cout << C(n + 1, k) - C(n - dup, k - 1) << endl;
    }
}
