int mod_pow(int x, int n, int mod = MODU) {
	ll res = 1;
	while (n > 0) {
		if (n & 1) res = res * x %mod;
		x = (ll)x * x%mod;
		n >>= 1;
	}
	return res;
}
int divmod(int a, int b, int m = MODU) { // a/b(mod m)
								  // a/b (mod m)
								  // a*b^-1
								  // b^-1 * b = 1
								  // b^(m-1) = 1 
								  // b^(m-2) * b = 1
								  // b^-1 = b^(m-2)

								  // a/b = a * b^(m-2)

	return (a * 1LL * mod_pow(b, m - 2, m)) % m;
}

