ll power(ll a, ll b) {
	if (b == 0) return 1;
	if (b == 1) return a;
	if (b % 2 == 0)
		return power((a * a) % inf, b / 2) % inf;
	return ((power((a * a) % inf, b / 2) % inf) * a) % inf;
}

ll choose(ll x, ll y) {
	if (y > x) return 0;
	ll inv = power((fact[y] * fact[x - y]) % inf, inf - 2);
	//cout<<fact[x]<<" "<<inv<<"HSDGAVJDS"<<endl;
	return (fact[x] * inv) % inf;
}

