}

ll fact[100002], invFact[100002];

void fillFact(int n){
    fact[0] = 1LL;
    for(int i=1; i<=n+1; i++){
        fact[i] = (i*fact[i-1])%MOD;
    }
}

void fillInvFact(int n){
    invFact[0] = 1LL;
    for(int i=1; i<= n+1; i++){
        invFact[i] = (pow(i, MOD-2)*invFact[i-1])%MOD;
    }
}

ll C(int n, int m){
    if(n<m) return 0;
    ll tmp = fact[n];
    tmp = (tmp*invFact[m])%MOD;
    tmp = (tmp*invFact[n-m])%MOD;
    return tmp;
}


