void init() {
     inv[0] = fac[1] = inv[1] = 1;
     for (int i = 2; i < MAXN; i++) {
         LL tmp = (-(MOD / i) * inv[MOD % i]) % MOD;
         tmp += (tmp / MOD + 1) * MOD;
         inv[i] = tmp;
     }
     for (int i = 2; i < MAXN; i++) inv[i] = (inv[i - 1] * inv[i]) % MOD;
     for (int i = 2; i < MAXN; i++) fac[i] = (fac[i - 1] * i) % MOD;
}

LL C(int n, int m) {
   if (!m || !n) return 1;
   LL ans = fac[n];
   ans = (fac[n] * inv[n - m]) % MOD;
   return (ans * inv[m]) % MOD;
}

