#define MD 1000000007
using namespace std;
typedef long long LL;
LL pwr(LL a,int x){
	if (x==1) return a;
	LL tmp=pwr(a,x>>1);
	tmp*=tmp;
	tmp%=MD;
	if (x&1){
		tmp*=a;
		tmp%=MD;
	}
	return tmp;
}
inline LL c(int a,int b){
	if (a>b) return -1;
	if (b-a<a) a=b-a;
	if (a==0) return 1;
	LL res=1;
	int j=b;
	for (int i=a;i;i--,j--){
		res*=j;
		res%=MD;
		res*=pwr(i,MD-2);
		res%=MD;
	}
	return res;
}
