const int MOD = 1000000007;

ll exp_mod(ll a) {
    ll res = 1;
    ll b = MOD-2;
    while (b > 0) {
        if (b&1)
            res = (res * a)%MOD;
        a = (a * a)%MOD;
        b >>= 1;
    }
    return res;
}

ll memo1[100];
