ll mod = 1e9+7;

ll pow(ll n, ll k, ll mod) {
    if (k == 0) return 1;
    else if (k % 2 == 1) {
        return n * pow(n, k - 1, mod) % mod;
    } else {
        ll t = pow(n, k / 2, mod);
        return t * t % mod;
    }
}

void init(ll n, ll mod) {
    fact[0] = 1;
    inverse[0] = 1;
    ll now = 1;
    for(int i = 1; i <= n; i++) {
        now = now * i % mod;
        fact[i] = now;
        inverse[i] = pow(now, mod - 2, mod);
    }
}

int comb(ll n, ll k, ll mod) {
    if (n < 0 || k < 0 || k > n) {
        cout << "yabai:" << n << ", " << k << endl;
        return 0; 
    }
    return (fact[n] * inverse[k]) % mod * inverse[n - k] % mod;
}

