ll qk(ll a,ll b,ll c)
{
    ll ans=1;
    a%=mm;
    while(b)
    {
        if(b&1){
            ans=ans*a%c;
            b--;
        }
        a=a*a%c;
        b>>=1;
    }
    return ans;
}
ll jc(ll n,ll m)
{
    if(m>n)return 0;
    ll ans=1;
    for(int i=1;i<=m;++i)
    {
        ll a=(n+i-m)%mm;
        ll b=i%mm;
        ans=ans*(a*qk(b,mm-2,mm)%mm)%mm;
    }
    return ans;
}
ll lucas(ll n,ll m)
{
    if(m==0) return 1;
    return jc(n%mm,m%mm)*lucas(n/mm,m/mm)%mm;
}
