using int64 = long long;
const int64 MOD = 1000000007;
int64 powmod(int64 a, int64 p) {
	int64 value = 1;
	for(int64 mul = a; p > 0; p >>= 1, mul = (mul * mul) % MOD) {
		if(p & 1) value = (value * mul) % MOD;
	}
	return value;
}

int64 invmod(int64 x) {
	return powmod(x, MOD - 2);
}

struct Factorial {
	int64 *val;
	int64 *inv;
};

Factorial SetFact(int N) {
	N++;
	Factorial fact;
	fact.val = new int64[N];
	fact.inv = new int64[N];
	fact.val[0] = 1;
	for(int i = 1; i < N; i++) {
		fact.val[i] = int64(fact.val[i - 1] * i) % MOD;
	}
	fact.inv[N - 1] = powmod(fact.val[N - 1], MOD - 2);
	for(int i = N - 1; i > 0; i--) {
		fact.inv[i - 1] = int64(fact.inv[i] * i) % MOD;
	}
	return fact;
}

int64 Combination(int n, int m, Factorial *f) {
	return (((f->val[n] * f->inv[m]) % MOD) * f->inv[n - m]) % MOD;
}

