ll bin_pow(ll a, ll n)
{
    if (!n) return 1;
    if (n & 1) return a * bin_pow(a, n - 1) % M;
    ll b = bin_pow(a, n >> 1);
    return b * b % M;
}

ll inv(ll a)
{
    return bin_pow(a, M - 2);
}

void init_cnk(ll * cnk, ll n)
{
    cnk[0] = 1;
    for (ll k = 1; k <= n; ++k)
        cnk[k] = (cnk[k - 1] * (n - k + 1) % M) * inv(k) % M;
}

