struct ModRing {
   int mod, x;
   // constructor
   ModRing(int mod_n) : mod(mod_n), x(0) {}
   ModRing(int a, int mod_n) : mod(mod_n) { x = ((a % mod) + mod) % mod; }

   // methods
   ModRing& operator=(int a) {
      return *this = ModRing(a, mod);
   }
   ModRing operator-() const {
      return ModRing((-x + mod) % mod, mod);
   }
   ModRing& operator+=(const ModRing& a) {
      (x += a.x) %= mod;
      return *this;
   }
   ModRing& operator-=(const ModRing& a) {
      return *this += -a;
   }
   ModRing& operator*=(const ModRing& a) {
      (x *= a.x) %= mod;
      return *this;
   }
   const ModRing operator+(const ModRing& a) const {
      return ModRing(x, mod) += a;
   }
   const ModRing operator-(const ModRing& a) const {
      return ModRing(x, mod) -= a;
   }
   const ModRing operator*(const ModRing& a) const {
      return ModRing(x, mod) *= a;
   }
   ModRing& operator+=(int a) {
      return *this += ModRing(a, mod);
   }
   ModRing& operator-=(int a) {
      return *this -= ModRing(a, mod);
   }
   ModRing& operator*=(int a) {
      return *this *= ModRing(a, mod);
   }
   const ModRing operator+(int a) const {
      return ModRing(x, mod) += a;
   }
   const ModRing operator-(int a) const {
      return ModRing(x, mod) -= a;
   }
   const ModRing operator*(int a) const {
      return ModRing(x, mod) *= a;
   }
   const ModRing power(int n) const {
      ModRing tmp(x, mod), res(1, mod);
      while (n > 0) {
         if ((n & 1) == 1) res *= tmp;
         tmp *= tmp;
         n >>= 1;
      }
      return res;
   }
};
