struct Mod_comb
{
    const ll mod_;
    const int n_;
    std::vector<ll> fac;
    std::vector<ll> rev;

    Mod_comb() : Mod_comb(1e6+10, 1e9+7)
    {
    }

    ll qpow(ll a, ll b)
    {
        ll ret=1;
        while(b)
        {
            if(b&1)ret=(ret*a)%mod_;
            b>>=1;
            a=(a*a)%mod_;
        }
        return ret;
    }

    Mod_comb(int n, ll m) : mod_(m), n_(n), fac(n), rev(n)
    {
        fac.resize(n_);
        rev.resize(n_);
        fac[0] = 1;
        for(int i=1;i<n_;++i)
        {
            fac[i]=(fac[i-1]*i)%mod_;
        }
        rev[n_-1]=qpow(fac[n_-1],mod_-2);
        for(int i=n_-2;i>=0;--i)
        {
            rev[i]=(rev[i+1]*(i+1))%mod_;
        }
    }

    ll C(int n,int m)
    {
        if(m>n)
        {
           return 0;
        }
        return (((fac[n]*rev[m])%mod_)*rev[n-m])%mod_;
    }
};


