ll extgcd(ll a, ll b, ll &x, ll &y){
  ll d = a;
  if(b!=0){
    d = extgcd(b,a%b,y,x);
    y -= (a/b)*x;
  }else{
    x = 1; y = 0;
  }
  return d;
}

ll mod_inverse(ll a, ll m){
  ll x, y;
  extgcd(a, m, x, y);
  return (m+x%m)%m;
}

void solve(int N, int lhs, int rhs){
  ll a = N, ax = a;
  ll b = 1, bx = b;
  ll s = lhs + N-1-rhs, sx = s;
  ll t = 0, tx = t;

  REP(i,1,N+1){
    ll res1 = 0, res2 = 0;
    res1 = a * mod_inverse(b, MOD);
    res1 %= MOD;
    res2 = s * mod_inverse(t, MOD);
    res2 %= MOD;
    if(t==0) res2 = 1;

    //cout << s << " " << t << " " ;
    //cout << res1 << " " << res2 << " ";
    cout << (res1 - res2 + MOD)%MOD << endl;

    ax--;
    bx++;
    if(t!=0) sx--;
    tx++;
    a *= ax; a %= MOD;
    b *= bx; b %= MOD;
    if(t!=0) s *= sx; s %= MOD;
    if(t==0) t = 1;
    t *= tx; t %= MOD;
  }
}

