int rev( int x ){
    int pwr[40];
    pwr[0] = x;
    for ( int i = 1; i <= 30; i++ ){
        pwr[i] = ( pwr[i-1] * 1ll * pwr[i-1] ) % mod;
    }
    int v = mod - 2, res = 1;
    for ( int i = 30; i >= 0; i-- ){
        int bit = ( v >> i ) & 1;
        if ( bit ){
            res = ( res * 1ll * pwr[i] ) % mod;
        }
    }
    return res;
}

int getC( int n, int k ){
    if ( n < k ){
        return 0;
    }
    int res = ( fact[n] * 1ll * rev( fact[k] ) ) % mod;
    return ( res * 1ll * rev( fact[n-k] ) ) % mod;
}


