            d = i - a[b];
            break;
        }
    }
    for(i = 1; i < N - d + 1; ++i){
        cout << binommod(N + 1, i) - binommod(N - d - 1, i - 1) << endl;
    }
    for(; i <= N + 1; ++i){
        cout << binommod(N + 1, i) << endl;
    }
    return 0;
}

