long long inv_mod(long long a) {
	//aの逆元を求める
	//a * x = 1 (mod MOD)
	//a * x - 1 = q * MOD
	//a * x - q * MOD = 1
	int b, x, u, q, tmp;

	b = MOD; x = 1; u = 0;
	while (b > 0) {
		q = a / b;
		tmp = u; u = x - q * u; x = tmp;
		tmp = b; b = a - q * b; a = tmp;
	}

	return (x < 0) ? MOD + x : x;
}

