ll pm(ll a, ll b) {
	if (b == 0) return 1LL;
	if (b == 1) return a;
	ll r = pm((a * a) % MOD, b/2);
	if (b&1) r = (r * a) % MOD;
	return r;
}

vi fac, faci;
void cfac(int n) {
	fac.push_back(1LL);
	faci.push_back(1LL);
	while ((int)fac.size() <= n) {
		fac.push_back(fac.back() * ll(fac.size()) % MOD);
		faci.push_back(pm(fac.back(), MOD - 2));
	}
}
ll nCk(int n, int k) {
	if (n < k) return 0LL;
	ll r = fac[n];
	r = (r * faci[k]) % MOD;
	r = (r * faci[n - k]) % MOD;
	return r;
}

