ll LP(ll x,ll y){
    if(y==0)return 1;
    if(y%2==0)return LP(x,y/2)*LP(x,y/2)%MOD;
    else return LP(x,y-1)*x%MOD;
}
ll MC(ll x,ll y){
    if(y==0)return 1;
    if(x<y)return 0;
    ll n=1,r=1,k=1;
    EREP(i,x)n=(i*n)%MOD;
    EREP(i,y)r=(i*r)%MOD;
    EREP(i,x-y)k=(i*k)%MOD;
    return (n*(LP(r,MOD-2)*LP(k,MOD-2)%MOD))%MOD;
}

