    }

    int l, r;
    for(int i=0; i<n; i++) {
        if(pos[i].size() == 2) {
            l = min(pos[i][0], pos[i][1]);
            r = n - max(pos[i][0], pos[i][1]);
        }
    }

    COMinit();
    for(int k=1; k<=n+1; k++) {
        cout << COM(n+1, k) - COM(l+r, k-1) << endl;
    }
    return 0;
}

