static inline long long modinv(long long n){
    long long ret = 1, a = 1000000005;
    n %= 1000000007;
    while(a){
        if(a % 2){
            ret = ret * n % 1000000007;
        }
        n = n * n % 1000000007;
        a /= 2;
    }
    return ret;
}

long long binommod(long long n, long long k){
    if(n <= 0 || k <= 0)return 1;
    if(k > n)return 0;
    long long ret = 1;
    for(int j = 1; j <= k; ++j, --n){
        ret = ((ret * n) % 1000000007 * modinv(j)) % 1000000007;
    }
    return ret;
}

