long long mypow(long long a, long long b) {
  if (b == 0) {
	  return 1LL;
	} else if (b % 2 == 1) {
	  return (a * mypow(a, b - 1)) % mod;
	}
  long long c = mypow(a, b / 2);
  return c * c % mod;
}

long long inv(long long a) {
  return mypow(a, mod - 2);
}

