int powMOD(int x, int m) {
	int p = 1;
	while (m) {
		if (m&1) p = ((LL)p*x)%MOD;
		x = ((LL)x*x)%MOD;
		m >>= 1;
	}
	return p;
}

class CombN {
private:
	int N;
	int* res;
	int* temp;
public:
	CombN(int N) {
		this->N = N;
		this->res = new int[N+1];
		this->temp = new int[N+1];

		this->temp[N] = N;
		for (int i = N-1; i >= 1; --i) 
			this->temp[i] = ((LL)i*this->temp[i+1])%MOD;
		this->res[0] = 1;
		for (int i = 1; i <= N; ++i)
			this->res[i] = ((LL)powMOD(fact[i], MOD-2)*this->temp[N-i+1])%MOD;
	}

	int comb(int k) {
		if (k < 0 || k > N) return 0;
		return this->res[k];
	}

	~CombN() {
		delete[] this->res;
		delete[] this->temp;
	}
};

