//aCbを求める
ll combination(ll a,ll b)
{
	ll child,mother;
	if(a<b)
		return 0;

	child = kai[a];
	mother = kai[a-b]*kai[b];
	mother %= MOD;
	mother = inverse(mother);
	child *= mother;
	child %=MOD;
	return child;
}

