inline long long LogExp(long long a,long long b)
{
    long long rez=1LL;
    long long x=a;
    while(b)
    {
        if(b&1)
        {
            rez=(rez*x)%MOD;
           // while(rez>=MOD) rez-=MOD;
            b--;
        }
            else
        {
            b>>=1LL;
            x=(x*x)%MOD;

        }
    }
    return rez;
}
inline long long C(long long n,long long k)
{
    long long comb;
    long long nf,kf,xf;
    nf=fact[n];
    kf=fact[k];
    xf=fact[n-k];
    comb=nf;
    comb=(comb*LogExp(kf,MOD-2));
    while(comb>=MOD) comb-=MOD;
    comb=(comb*LogExp(xf,MOD-2));
    while(comb>=MOD) comb-=MOD;
    return comb;
}

