int loadvec(vector<int>& v, int N=-1) {
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    // assert(i <= N);
    return i;
}


void prepare_comb(vector<ll>& ar, int n) {
    ar.resize(n+1);
    ar[0] = 1LL;
    for (ll i=1; i<=n; i++) {
        ar[i] = DIV(MUL(ar[i-1], n-i+1), i);
    }
    // cout << "prepare_comb(" << n << ") -> " << ar << endl;
}

void solve(vector<int>& a) {
    int n = a.size() - 1;
    int dub = -1;
    int first, second;
    vector<int> loc(n, -1);
    rep(i, n+1) {
        int a_i = a[i]-1;
        if (loc[a_i] != -1) {
            dub = a_i;
            first = loc[a_i];
            second = i;
        } else {
            loc[a_i] = i;
        }
    }
    int w1 = first-0, w2 = second-(first+1), w3 = (n+1)-(second+1);

    vector<ll> C;
    prepare_comb(C, w1+w3);

#ifdef DEBUG
    printf("N=%d\n", n);
    cout << a << endl;
    cout << loc << endl;
    printf("doubled: %d (at %d and %d)\n", 1+dub, first, second);
    printf("|%d|%d|%d|\n", w1, w2, w3);
#endif

    ll v = 1;
    for (int k=1; k<=n+1; ++k) {
        v = DIV(MUL(v, (n+1)-k+1), k);
        ll x = v;
        if (k-1 <= w1+w3) {
            // printf(" // k=%d; %lld - (%lld=wC%d)\n", k, x, C[k-1], k-1);
            x = SUB(x, C[k-1]);
        }
        if (k == 1) {
            printf("%d\n", n);
            continue;
        }
        printf("%lld\n", x);
    }
}

