  	if(f==0 && v[i] == dn) f = i;
    else if(s == 0 && v[i] == dn){s = i; break;}
  }
  int use = f + (n - s);
  for(int i=1;i<=n+1;i++){
  	 cout << (C(n+1,i) - C(use, i-1)) % MOD << endl;
  }
  return 0;
}

