ll mod_pow(ll x, ll n) {
	ll res = 1;
	while (n > 0) {
		if (n & 1) res = res * x % MOD;
		x = x * x % MOD;
		n >>= 1;
	}
	return res % MOD;
}

ll comb(ll n, ll k) {
	if (n < k) return 0;
	ll res = fact[n] % MOD;
	res = res * mod_pow(fact[k], MOD-2) % MOD;
	res = res * mod_pow(fact[n-k], MOD-2) % MOD;
	return res % MOD;
}

