template<typename T> T extgcd(T a, T b, T& x, T& y){
	for(T u = y = 1, v = x = 0; a;){
		T q = b / a;
		swap(x -= q * u, u), swap(y -= q * v, v), swap(b -= q * a, a);
	}
	return b;

}
template<typename T> T mod_inv(T a, T m){
	T x, y;
	extgcd(a, m, x, y);
	return (m + x % m) % m;
}

int mod_pow(int a, int n, int mod){
	int ret = 1;
	int p = a % mod;
	while(n){
		if(n & 1) ret = (ll)ret * p % mod;
		p = (ll)p * p % mod;
		n >>= 1;
	}
	return ret;
}

template<int mod, int primitive_root>
class NTT {
public:
	int get_mod() const { return mod; }
	void _ntt(vector<int>& a, int sign) {
		const int n = len(a);
		const int g = 3; //g is primitive root of mod
		int h = (int)mod_pow(g, (mod - 1) / n, mod); // h^n = 1
		if (sign == -1) h = (int)mod_inv(h, mod); //h = h^-1 % mod
		int i = 0;
		for (int j = 1; j < n - 1; ++j) {
			for (int k = n >> 1; k >(i ^= k); k >>= 1);
			if (j < i) swap(a[i], a[j]);
		}
		for (int m = 1; m < n; m *= 2) {
			const int m2 = 2 * m;
			const int base = mod_pow(h, n / m2, mod);
			int w = 1;
			rep(x, m) {
				for (int s = x; s < n; s += m2) {
					int u = a[s];
					int d = (ll)a[s + m] * w % mod;
					a[s] = u + d;
					if(a[s] >= mod) a[s] -= mod;
					a[s + m] = u - d;
					if(a[s + m] < 0) a[s + m] += mod;
				}
				w = (ll)w * base % mod;
			}
		}
		for (auto& x : a) if (x < 0) x += mod;
	}
	void ntt(vector<int>& input) {
		_ntt(input, 1);
	}
	void intt(vector<int>& input) {
		_ntt(input, -1);
		const int n_inv = mod_inv(len(input), mod);
		for (auto& x : input) x = (ll)x * n_inv % mod;
	}

	void convolution(const vector<int>& a, const vector<int>& b, vector<int>& _a, vector<int>& _b){
		int ntt_size = 1;
		while (ntt_size < len(a) + len(b)) ntt_size *= 2;
		_a = a, _b = b;
		_a.resize(ntt_size); _b.resize(ntt_size);
		ntt(_a);
		ntt(_b);
		rep(i, ntt_size){
            _a[i] = (ll)_a[i] * _b[i] % mod;
		}
		intt(_a);
	}
};

ll garner(vector<P> mr, int mod){
	mr.emplace_back(mod, 0);

	vector<ll> coffs(len(mr), 1);
	vector<ll> constants(len(mr), 0);
	rep(i, len(mr) - 1){
		// coffs[i] * v + constants[i] == mr[i].second (mod mr[i].first) を解く
		ll v = (mr[i].second - constants[i]) * mod_inv<ll>(coffs[i], mr[i].first) % mr[i].first;
		if (v < 0) v += mr[i].first;

		for (int j = i + 1; j < len(mr); j++) {
			(constants[j] += coffs[j] * v) %= mr[j].first;
			(coffs[j] *= mr[i].first) %= mr[j].first;
		}
	}

	return constants[len(mr) - 1];
}

typedef NTT<167772161, 3> NTT_1;
typedef NTT<469762049, 3> NTT_2;
typedef NTT<1224736769, 3> NTT_3;

inline void fast_int32mod_convolution(const vector<int>& a, const vector<int>& b, vector<int>& res){
	NTT_1 ntt1; NTT_2 ntt2; NTT_3 ntt3;
    vector<int> x,_x,y,_y,z,_z;
	ntt1.convolution(a, b, x, _x);
	ntt2.convolution(a, b, y, _y);
	ntt3.convolution(a, b, z, _z);
	const int m1 = ntt1.get_mod(), m2 = ntt2.get_mod(), m3 = ntt3.get_mod();
	const int m1_inv_m2 = mod_inv<ll>(m1, m2);
	const int m12_inv_m3 = mod_inv<ll>((ll)m1 * m2 % m3, m3);
	const int m12_mod = (ll)m1 * m2 % MOD;
	res.resize(len(x));
	rep(i, len(x)){
		int v1 = (ll)(y[i] - x[i]) *  m1_inv_m2 % m2;
		if (v1 < 0) v1 += m2;
		int v2 = (z[i] - (x[i] + (ll)m1 * v1) % m3) * m12_inv_m3 % m3;
		if (v2 < 0) v2 += m3;
		int constants3 = (x[i] + (ll)m1 * v1 + m12_mod * v2) % MOD;
		if (constants3 < 0) constants3 += MOD;
		res[i] = constants3;
	}
}

