ll modpow(ll a, ll n)
{
    if(n <= 0)
        return 1;

    ll rv = modpow(a, n / 2);
    rv = (rv * rv) % mod;

    if(n % 2)
        rv = (rv * a) % mod;

    return rv;        
}

void initialize(ll n)
{
    fact.resize(n + 1, 1);
    invfact.resize(n + 1, 1);

    for(ll i = 2; i <= n; i++)
        fact[i] = (fact[i - 1] * i) % mod;

    for(ll i = 2; i <= n; i++)
        invfact[i] = modpow(fact[i], mod - 2);    
}

ll ncr(ll n, ll r)
{
    if(n < 0)
        return 0;
    if(r < 0) 
        return 0;
    if(r > n)
        return 0;

    ll ans = (fact[n] * invfact[r]) % mod;
    ans = (ans * invfact[n - r]) % mod;
    return ans;           
}

int main()
{
