ll power(ll x, ll y)
{
	if(y == 0) return 1;
	ll temp = power(x, y/2);
	temp *= temp, temp %= mod;
	if(y%2) temp *= x, temp %= mod;
	return temp;
}
void pre()
{
	fac[0] = 1;
	for(int i=1; i<N; i++) fac[i] = fac[i-1]*i, fac[i]%= mod;
}
void operate(int n)
{
	C[0] = 1;
	ll cur = 1;
	for(ll i=1; i<=n; i++)
	{
		cur *= (n-i+1), cur %= mod;
		C[i] = (cur * power(fac[i], mod-2))%mod;
	}
}
