ll F[N], Finv[N], inv[N];//仓鼠学姐的模板

void init() {
	inv[1] = 1;
	for(int i = 2; i < N; i ++) {
		inv[i] = (MOD - MOD / i) * 1ll * inv[MOD % i] % MOD;
	}
	F[0] = Finv[0] = 1;
	for(int i = 1; i < N; i ++) {
		F[i] = F[i-1] * 1ll * i % MOD;
		Finv[i] = Finv[i-1] * 1ll * inv[i] % MOD;
	}
}

ll C(ll n, ll m) {
	if(m < 0 || m > n) return 0;
	return F[n] * 1ll * Finv[n - m] % MOD * Finv[m] % MOD;
}

