Long bigmod(Long x, Long pw) {
   Long ret = 1;
   while(pw > 0) {
      if(pw & 1) ret = ret * x % MOD;
      x = x * x % MOD;
      pw >>= 1;
   }
   return ret;
}

Long nCr(int n, int r) {
   if(r > n || r < 0) return 0;
   return fact[n] * bigmod(fact[n-r] * fact[r] % MOD, MOD-2) % MOD;
