#define N 1000000007

using namespace std;

long long comb(long long n, long long k){
  long long res = 1;
  long long denom = 1;
  if (n<k||k<0) {
    return(0);
  }
  if (n==k||k==0) {
    return(1);
  }
  for (int i=0;i<k;i++) {
    res *= n - i;
  }
  for (int i=1;i<=k;i++) {
    denom *= i;
  }

  return(res/denom);
}

long long all_comb(long long n){
  long long sum = 0;
  long long res = n;
  long long denom = 1;
  for (int i=1;i<=n;i++) {
    sum += res/denom;
    res *= n-i;
    denom *= i+1;
  }
  return(sum);
}

long long comb_update(long long x, long long n, long long i) {
  if (n<i||i<0)
    return(0);
  if (n==i||i==0)
    return(1);
  if (x > 0) {
    return(x * (n-i+1) / (i));
  } else {
    return((n-i+1) / (i));
  }
}

int main(){
  long long n, k, l;
  long long a[100010] = {};
  cin >> n;
  for (int i=1;i<=n;i++) {
    int x;
    cin >> x;
    if (a[x] != 0) {
      k = a[x];
      l = i-1;
      break;
    }
    a[x] = i;
  }
  cout << n << endl;
  long long r1 = n-1;
  long long r2 = 1;
  long long r3 = 1;
  long long r4 = 0;
  for (long long i=2;i<=n+1;i++) {
    r1 = comb_update(r1, n-1, i) % N;
    r2 = comb_update(r2, n-1, i-1) % N;
    r3 = comb_update(r3, n-l+k-1, i-1) % N;
    r4 = comb_update(r4, n-1, i-2) % N;
    long long sum = ((r1 % N) + ((2 * (r2 - r3)) % N) + (r3 % N) + (r4 % N)) % N;
    if (sum < 0) {
      sum += N;
    }
    cout << sum << endl;
  }
  return(0);
}

