ll mod = pow(10LL, 9LL) + 7LL;
ll p_list[100005];

ll combi(ll a, ll b)
{
        ll ret;

        ret = p_list[a];
        ret *= mod_inv(p_list[b], mod);
        ret %= mod;
        ret *= mod_inv(p_list[a-b], mod);
        ret %= mod;
        return ret;
}

ll f0(ll len0, ll len1, ll len2, ll k)
{
        if (len0 + len1 + len2 < k) return 0LL;
        return combi(len0 + len1 + len2, k);
}

ll f1(ll len0, ll len1, ll len2, ll k)
{
        if (k == 1LL) return 1LL;
        if (k == 2LL) return (len0 + len1) + (len1 + len2);

        // +1 28 2

        ll c0 = 0LL;
        if (len0 >= k-1LL) c0 = combi(len0, k-1LL);

        ll c1 = 0LL;
        if (len1 >= k-1LL) c1 = combi(len1, k-1LL);

        ll c2 = 0LL;
        if (len2 >= k-1LL) c2 = combi(len2, k-1LL);

        ll c01 = 0LL;
        if (len0 + len1 >= k-1LL) c01 = combi(len0 + len1, k-1LL);

        ll c12 = 0LL;
        if (len1 + len2 >= k-1LL) c12 = combi(len1 + len2, k-1LL);

        ll c02 = 0LL;
        if (len0 + len2 >= k-1LL) c02 = combi(len0 + len2, k-1LL);

        ll c012 = 0LL;
        if (len0 + len1 + len2 >= k-1LL) c012 = combi(len0 + len1 + len2, k-1LL);

        ll ret = 0LL;

        ret += c12;
        ret %= mod;

        ret += c01;
        ret %= mod;

        ll tmp0 = c012 - c0 - c12;
        while (tmp0 < 0LL) tmp0 += mod;
        ret += tmp0;
        ret %= mod;

        ll tmp1 = c012 - c2 - c01;
        while (tmp1 < 0LL) tmp1 += mod;
        ret += tmp1;
        ret %= mod;

        ret -= (c02 - c0 - c2);
        while (ret < 0LL) ret += mod;

        return ret;
}

ll f2(ll len0, ll len1, ll len2, ll k)
{
        if (k < 2LL) return 0LL;
        if (k == 2LL) return 1LL;
        return combi(len0 + len1 + len2, k-2LL);
}

