ll mod_pow(ll x, ll n, ll mod) {
    ll a = 1LL;
    while (n) {
        if (n%2) a = ((a%mod)*(x%mod))%mod;
        x = ((x%mod)*(x%mod))%mod;
        n /= 2LL;
    }
    return a;
}

ll mod_inverse(ll a, ll m) {
    return mod_pow(a, m-2, m);
}

ll ncr(int n, int r) {
    if (n < r) return 0;
    return fact[n] * (rfact[r] * rfact[n-r] % mod) % mod;
}

