inline ll take_mod(ll a){
    return (a % mod + mod) % mod;
}

inline ll add(ll a, ll b){
    return take_mod(a+b);
}

inline ll sub(ll a, ll b){
    return take_mod(a-b);
}


inline ll mul(ll a, ll b){
    return take_mod(a * b);
}

inline ll pow(ll x, ll n){
    ll res = 1LL;
    while(n > 0){
        if(n & 1) res = mul(res, x);
        x = mul(x, x);
        n >>= 1;
    }
    return res;
}

ll mod_inv(ll x){
    return pow(x, mod-2);
}

// nは上限
void make_fact(ll n){
    fact[0] = 1;
    ll res = 1;
    for(int i = 1; i <= n; i++){
        fact[i] = res;
        res = mul(res, i+1);
    }
}

// nは上限
void make_invfact(ll n){
    invfact[0] = 1;
    invfact[n] = mod_inv(fact[n]);
    for(int i = n-1; i >= 1; i--){
        invfact[i] = mul(invfact[i + 1], i + 1);
    }
}

ll perm(ll n, ll k){
    return mul(mul(fact[n], invfact[n-k]), invfact[k]);
}


ll comb(ll n, ll k){
    return mul(mul(fact[n], invfact[n-k]), invfact[k]);
}

typedef complex<double> P;

const P I(0, 1);

const double pi = 4.0*atan(1.0);

void *fft(P f[], int n, int sign){
    if (n==1){
        return f;
    }

    P *f0;
    P *f1;
    f0 = new P[n/2];
    f1 = new P[n/2];
    for(int i = 0; i < n/2; i++){
        f0[i] = f[2*i+0];  //f0(x)を求めた
        f1[i] = f[2*i+1];  //f1(x)を求めた
    }
    fft(f0, n/2, sign);
    fft(f1, n/2, sign);
    double theta = sign*2*pi/n;

    for(int i = 0; i < n; i++){
        P pow_zeta = exp(i*theta*I);
        f[i] = f0[i % (n/2)] + pow_zeta * f1[i%(n/2)];
    }
    free(f0);
    free(f1);
}

int n;
ll a[100100];
int check[100100];
P perm_left[100100];
P perm_right[100100];

int main(){
    cin >> n;
    fill(check, check+n, 0);
    ll duplicate = -1;
    for(int i = 0; i < n; i++){
        cin >> a[i];
        if(check[a[i]] == 0){
            check[a[i]] = 1;
        }
        else{
            duplicate = a[i];
        }
    }

    ll f = -1, s = -1;
    for(int i = 0; i < n; i++){
        if(a[i] == duplicate && f == -1){
            f = i;
        }
        else if(a[i] == duplicate){
            s = n-i;
        }
    }

    make_fact(n+10);
    make_invfact(n+10);


    for(int i = 0; i < n; i++){
        perm_left[i] = P(0.0, 0.0);
        perm_right[i] = P(0.0, 0.0);
    }

    for(int l = 0; l <= f; l++){
        perm_left[l] = P((double)perm(f, l), 0.0);
    }
    for(int l = 0; l <= s; l++){
        perm_right[l] = P((double)perm(s, l), 0.0);
    }

    fft(perm_left, n, 1);
    fft(perm_right, n, 1);
    for(int i = 0; i < n; i++){
        perm_left[i] *= perm_right[i];
    }
    fft(perm_left, n, -1);

    for(int k = 1; k <= n+1; k++){
        ll whole = perm(n+1, k);
        if(k == 1){
            cout << whole - 1 << endl;
        }
        else {
            cout << whole - (ll) (perm_left[k - 1].real() / n + 0.5) << endl;
        }
    }
    return 0;

}

