int qexp(int b, int p) {
	if (p == 0) return 1;
	else if (p == 1) return b % MOD;
	else if (p % 2 == 0) {
		long long a = qexp(b, p/2);
		a *= a;
		a %= MOD;
		return a;
	} else {
		long long a = qexp(b, p/2);
		a *= a;
		a %= MOD;
		a *= b;
		a %= MOD;
		return a;
	}
}

int modinv(int x) {
	return qexp(x, MOD - 2);
}

int choose(int n, int k) {
	if (k < 0 || k > n) return 0;
	long long ans = fac[n];
	ans *= modinv(fac[k]);
	ans %= MOD;
	ans *= modinv(fac[n-k]);
	ans %= MOD;
	return ans;
}

