    int a = A[i];
    if (P[a] == -1) P[a] = i;
    else d = a, dui = i;
  }

  //out(n, A, d, dui);

  int p = P[d];
  int q = dui;

  //out(n, p, q);

  int a = p;
  int b = q - p - 1;
