ll fact[111111], ifact[111111];

ll mod_pow(ll a, ll b, ll m) {
  if (b == 0) return 1;
  ll c = mod_pow(a*a%m, b/2, m);
  if (b%2 == 1) c = (c*a) % mod;
  return c;
}

ll C(ll n, ll r) {
  if (r > n) return 0;
  if (r > n/2) r = n - r;
  return fact[n] * ifact[n-r] % mod * ifact[r] % mod;
}

