class Math
{
    public: bool is_square(ll n)
    {
        ll x = round(sqrt(n));
        return x * x == n;
    }

    public: ll gcd(ll a, ll b)
    {
        while (a > 0)
        {
            ll c = a;
            a = b % a;
            b = c;
        }
        return b;
    }

    public: ll gcd_ex(ll a, ll b, ll &x, ll &y) // a * x + b * y = gcd(a, b)
    {
        if (a == 0)
        {
            x = 0; y = 1;
            return b;
        }
        ll x1, y1;
        ll d = gcd_ex(b % a, a, x1, y1);
        x = y1 - (b / a) * x1;
        y = x1;
        return d;
    }

    public: ll rev_mod(ll a, ll mod)
    {
        ll x, y;
        gcd_ex(a, mod, x, y);
        return (x % mod + mod) % mod;
    }

    public: ll fact(ll n, ll mod)
    {
        ll res = 1;
        for (ll i = 1; i <= n; i++)
            res = (res * i) % mod;
        return res;
    }

    public: ll fact_mod(ll n, ll mod)
    {
        ll res = 1;
        while (n > 1) {
            res = (res * ((n / mod) % 2 ? mod - 1 : 1)) % mod;
            for (int i = 2; i <= n % mod; i++)
                res = (res * i) % mod;
            n /= mod;
        }
        return res % mod;
    }

    public: vector<ll> get_fact(ll n, ll mod)
    {
        vector<ll> fact(n + 1, 1);
        rep(i, 1, n + 1)
            fact[i] = (fact[i - 1] * i) % mod;
        return fact;
    }

    public: ll A(ll n, ll k, ll mod)
    {
        ll res = fact(n, mod);
        res = (res * rev_mod(fact(n - k, mod), mod)) % mod;
        return res;
    }

    public: ll A(ll n, ll k, ll mod, vector<ll> &fact)
    {
        ll res = fact[n];
        res = (res * rev_mod(fact[n - k], mod)) % mod;
        return res;
    }

    public: ll C(ll n, ll k, ll mod)
    {
        ll res = fact(n, mod);
        res = (res * rev_mod(fact(k, mod), mod)) % mod;
        res = (res * rev_mod(fact(n - k, mod), mod)) % mod;
        return res;
    }

    public: ll C(ll n, ll k, ll mod, vector<ll> &fact)
    {
        ll res = fact[n];
        res = (res * rev_mod(fact[k], mod)) % mod;
        res = (res * rev_mod(fact[n - k], mod)) % mod;
        return res;
    }

    public: ll C_(ll n, ll k, ll mod) //C'(n, k) = C(n + k - 1, k - 1) - divide n elements into k groups
    {
        return C(n + k - 1, k - 1, mod);
    }

    public: ll C_(ll n, ll k, ll mod, vector<ll> &fact) //C'(n, k) = C(n + k - 1, k - 1) - divide n elements into k groups
    {
        return C(n + k - 1, k - 1, mod, fact);
    }

    public: ll Catalan(ll n, ll mod)
    {
        return C(n * 2, n, mod) * rev_mod(n + 1, mod) % mod;
    }

    public: ll Catalan(ll n, ll mod, vector<ll> &fact)
    {
        return C(n * 2, n, mod, fact) * rev_mod(n + 1, mod) % mod;
    }

    private: ll get_t(ll n)
    {
        while (n % 2 == 0)
            n /= 2;
        return n;
    }

    private: ll get_s(ll n)
    {
        ll s = 0;
        while (n % 2 == 0)
        {
            n /= 2;
            s++;
        }
        return s;
    }

    public: ll log_2(ll n)
    {
        ll cnt = 1, curr = 0;
        while (cnt < n)
        {
            cnt <<= 1;
            curr++;
        }
        return curr;
    }

    public: ll min_pow_2(ll n)
    {
        ll cnt = 1, curr = 0;
        while (cnt < n)
        {
            cnt <<= 1;
            curr++;
        }
        return cnt;
    }

    public: ll bin_mult(ll a, ll n, ll mod)
    {
        ll res = 0;
        while (n) {
            if (n & 1)
                res = (res + a) % mod;
            a = (a + a) % mod;
            n >>= 1;
        }
        return res;
    }

    public: ll bin_pow(ll a, ll n, ll mod)
    {
        ll res = 1;
        while (n) {
            if (n & 1)
                res = (res * a) % mod;
            a = (a * a) % mod;
            n >>= 1;
        }
        return res;
    }

    public: ll bin_pow_ll(ll a, ll n, ll mod)
    {
        ll res = 1;
        while (n) {
            if (n & 1)
                res = bin_mult(res, a, mod) % mod;
            a = bin_mult(a, a, mod) % mod;
            n >>= 1;
        }
        return res;
    }

    public: bool miller_rabin(ll n)
    {
        srand(time(0));
        if (n == 2 || n == 3)
            return true;
        if (n == 1 || n % 2 == 0)
            return false;
        ll k = log_2(n);
        ll t = get_t(n - 1);
        ll s = get_s(n - 1);
        for (ll i = 0; i < k; i++)
        {
            ll a = rand() % (n - 3) + 2;
            ll x = bin_pow_ll(a, t, n);
            if (x == 1 || x == n - 1)
                continue;
            bool b = false;
            for (ll j = 0; j < s - 1; j++)
            {
                x = bin_mult(x, x, n);
                if (x == 1)
                    return false;
                if (x == n - 1)
                {
                    b = true;
                    break;
                }
            }
            if (!b)
                return false;
        }
        return true;
    }

    public: bool isprime(ll n)
    {
        if (n == 1)
            return false;
        for (ll i = 2; i * i <= n; i++)
            if (n % i == 0)
                return false;
        return true;
    }

    public: vector<ll> getprimes(ll n)
    {
        vector<bool> e(n + 1, true);
        vector<ll> primes;
        e[0] = false;
        e[1] = false;
        for (ll i = 2; i <= n; i++)
            if (e[i])
            {
                primes.push_back(i);
                for (ll j = i + i; j <= n; j += i)
                    e[j] = false;
            }
        return primes;
    }

    public: vector<bool> Eratosthenes(ll n)
    {
        vector<bool> e(n + 1, true);
        e[0] = false;
        e[1] = false;
        for (ll i = 2; i <= n; i++)
            if (e[i])
                for (ll j = i + i; j <= n; j += i)
                    e[j] = false;
        return e;
    }

    public: vector<ll> Eratosthenes_n(ll n)
    {
        vector<ll> lp(n + 1, 0);
        vector<ll> pr;
        for (ll i = 2; i <= n; i++)
        {
            if (lp[i] == 0)
            {
                lp[i] = i;
                pr.push_back(i);
            }
            for (ll j = 0; j < pr.size() && pr[j] <= lp[i] && i * pr[j] <= n; j++)
                lp[i * pr[j]] = pr[j];
        }
        return lp;
    }

    public: vector<pair<ll, ll> > Factorization(ll n)
    {
        vector<pair<ll, ll> > f;
        for (ll i = 2; i * i <= n; i++)
            if (n % i == 0)
            {
                f.push_back({i, 0});
                while (n % i == 0)
                {
                    f[sz(f) - 1].se++;
                    n /= i;
                }
            }
        if (n > 1)
            f.push_back({n, 1});
        return f;
    }

    public: vector<pair<ll, ll> > Factorization(ll n, vector<ll> &lp)
    {
        vector<pair<ll, ll> > f;
        while (n > 1)
        {
            if (sz(f) > 0 && f[sz(f) - 1].fi == lp[n])
                f[sz(f) - 1].se++;
            else
                f.push_back({lp[n], 1});
            n /= lp[n];
        }
        return f;
    }

    public: ll cntdivisors2(ll n)
    {
        ll cnt = 0;
        for (ll i = 1; i * i <= n; i++)
            if (n % i == 0)
            {
                if (i * i != n)
                    cnt += 2;
                else
                    cnt++;
            }
        return cnt;
    }

    public: ll cntdivisors3(ll n)
    {
        ll p = 1;
        while (p * p * p < n)
            p++;
        vector<ll> primes = getprimes(p);
        ll cnt = 1;
        for (ll i = 0; i < primes.size(); i++)
        {
            ll curr = 0;
            while (n % primes[i] == 0)
            {
                n /= primes[i];
                curr++;
            }
            cnt *= (curr + 1);
        }
        if (n == 1)
            cnt *= 1;
        else if (miller_rabin(n))
            cnt *= 2;
        else if (is_square(n))
            cnt *= 3;
        else
            cnt *= 4;
        return cnt;
    }

    public: ll ETF(ll n) //Euler Totient Function
    {
        ll res = n;
        vector<pair<ll, ll> > f = Factorization(n);
        for (auto p : f)
            res -= res / p.fi;
        return res;
    }

    public: ll ETF(ll n, vector<ll> &lp) //Euler Totient Function
    {
        ll res = n;
        vector<pair<ll, ll> > f = Factorization(n, lp);
        for (auto p : f)
            res -= res / p.fi;
        return res;
    }
};

