ll inverse(ll a)
{
	ll b = MOD;
	ll u=1;
	ll v=0;
	while(b)
	{
		ll t=a/b;
		swap(a -= t*b, b);
		swap(u -= t*v, v);
	}
	return (u%MOD + MOD)%MOD;
}

