ll extgcd(ll a, ll b, ll &x, ll&y){
    ll d = a;
    if(b != 0){
        d=extgcd(b,a%b,y,x);
        y -= (a/b)*x;
    }
    else{x=1;y=0;}
    return d;
}

ll inv(ll  a){
    ll m= MOD;
    long long x,y ;
    extgcd(a,m,x,y);
    return (m+x%m)%m;
}

void pre(ll n){
    nck[0] = 1;
    nck[1] = n;
    for(ll i=2 ; i <= n; i++){
        nck[i] = ((nck[i-1] * (n-i+1))%MOD * inverse[i]+MOD)%MOD;
    }
}

void preout(ll n){
    outck[0] = 1;
    outck[1] = n;
    for(ll i=2 ; i <= n; i++){
        outck[i] = ((outck[i-1] * (n-i+1))%MOD * inverse[i]+MOD)%MOD;
    }
}

