lld pow(lld a,lld b, lld p)  // a^b mod pを求める
{
	if (b == 0)
	{
		return 1;
	}else if (b % 2 == 0)
	{
		lld d = pow(a,b/2,p);  //a^b = a^(2k) = (a^k)^2  k = b / 2
		return ((d%mod) * d) % mod;
	}else
	{
		return ((a%mod) * pow(a,b-1,p) % mod)%mod;
	}
}

