	// }
}

lld comb(lld n,lld k)  //n_C_k
{
	if (n < k)
	{
		return 0;
	}
	return ((fact[n]%mod) * (pow(fact[k],mod-2,mod) % mod ) %mod) * (pow(fact[n-k],mod-2,mod)% mod) % mod;
}


