ll modpow(int x, int y) {
	ll ans = 1, val = x;
	while (y) {
		if (y & 1) ans = (ans * val) % MOD;
		val = (val * val) % MOD;
		y >>= 1;
	}
	return ans % MOD;
}

ll bin(int n, int r) {
