    }
    ifac[MN - 1] = fac[MN - 1].inv();
    for (int i = MN - 2; i >= 0; i--) {
        ifac[i] = ifac[i + 1] * Mint(i + 1);
    }
}

Mint C(int x, int y) {
    if (x < y) return Mint(0);
    return fac[x] * ifac[y] * ifac[x - y];
}

