void getrevfact()
{
	for(int i = 0; i <= n + 1; i++){
		long long int tmp[31];
		tmp[0] = fact[i];
		for(int j = 1; j < 31; j++){
			tmp[j] = (tmp[j - 1] * tmp[j - 1]) % mod;
		}
		int now = mod - 2;
		revfact[i] = 1;
		for(int j = 30; j >= 0; j--){
