        while(k > 0){
            if(k & 1){
                rfact[i] *= a;
                rfact[i] %= MOD;
            }
            a *= a;
            a %= MOD;
            k  >>= 1;
        }
    }

    cout << n << endl; //k=1
    if(n > 1) cout << (n * (n+1) / 2 - d1 - (n-d2)) % MOD << endl; //k=2;
    if(n > 2)
        reppp(i, 3, n){
            int ans = comb((ll)n+1, (ll)i);
            if(d1 + (n - d2) >= i-1){
                int dup = 0;
                reppp(j, max(0, i-1-(n-d2)), d1){
                    dup += (comb((ll)d1, (ll)j) * comb((ll)(n-d2), (ll)(i-1-j))) % MOD;
                }
                ans -= dup % MOD;
            }
            cout << ans << endl;
        }
    cout << 1 << endl; //k=n+1;
}

