i64 mod = 1000000007;

i64 pow_mod(i64 x, i32 r) {
    if (x < 0) x += mod;
    x %= mod;

    if (r <= 1) {
        return x;
    }
    auto t = r / 2;
    auto s = pow_mod(x, t);

    auto a = (s * s) % mod;
    if (r % 2 == 0) {
        return a;
    } else {
        return (a * x) % mod;
    }
};


int body(int &argc, char **argv) {
    using namespace debug;
    auto n = read<i32>();
    auto as = read<i32>(n + 1);
    FORE(a, as) { a -= 1; }

    i32 d1 = -1;
    i32 d2 = -1;

    V<i32> num(n, 0);
    REP (i, n + 1) {
        num[as[i]] += 1;
    }
    auto x = distance(num.begin(), max_element(num.begin(), num.end()));

    REP (i, n + 1) {
        if (as[i] == x) {
            if (d1 == -1) {
                d1 = i;
            } else {
                d2 = i;
            }
        }
    }

    auto fact = V<i64>(n + 2); // fact[i] = i!
    auto fact_inv = V<i64>(n + 2); // fact_inv[i] = (i!)^{^1}
    fact[0] = 1;
    FOR(i, 1, n + 2) {
        fact[i] = fact[i-1] * i;
        if (fact[i] < 0) fact[i] += mod;
        fact[i] %= mod;
    }
    REP(i, n + 2) {
        fact_inv[i] = pow_mod(fact[i], 1000000005);
    }

    auto comb_mod = [&](i64 n, i64 r) -> i64 {
        if (n < r) {
            return 0;
        }

        auto a = fact[n];
        auto b = fact_inv[r];
        auto c = fact_inv[n - r];
        i64 x = a * b;
        x %= mod;
        x *= c;
        x %= mod;

        return x;
    };

    FOR (k, 1, n + 2) {
        auto max = comb_mod(n + 1, k);

        REP (x, min(k, d1 + 1)) {
            // <x個> d1 or d2 <k-x-1個>
            // (d1 C x) * ((n-d2) C (k-x-1)
            auto minus = comb_mod(d1, x) * comb_mod(n - d2, k - x - 1);
            max -= minus;
        }

        if (max < 0) { max += mod; }
        max %= mod;

        cout << max << endl;
    }

    return 0;
}

