ll p2(int x)
{
    if (x == 0)
        return 1;
    if (x == 1)
        return 2;

    ll t = p2(x/ 2);
    if (x & 1)
        return (t * t * 2) % mod;
    else
        return (t * t) % mod;
}

ll precomp[maxn];
ll f(int x) {
    return precomp[x];
}

ll pow(ll b, ll e) {
    if (e == 0)
        return 1;
    if (e == 1) return b;

    ll t = pow(b, e / 2);
    t = t * t;
    t %= mod;
    if (e & 1)
        return (t * b) % mod;
    else
        return t;
}

ll inv(ll x)
{
    return pow(x, mod - 2);
}

ll comb(ll n, ll k) {
    ll a = f(n);
    ll b = f(n - k) * f(k);
    b %= mod;

    return (a * inv(b)) % mod;
}

