const int MOD = 1e9 + 7;
int n,x, len, arr[100010];
ll dp[100010]; 

ll modpow(int x, int y) {
	ll ans = 1, val = x;
	while (y) {
		if (y & 1) ans = (ans * val) % MOD;
		val = (val * val) % MOD;
		y >>= 1;
	}
	return ans % MOD;
}

ll bin(int n, int r) {
	if (r > n) return 0;
	if (n == r || r == 0) return 1;
	return (dp[n] * ((modpow(dp[r],MOD- 2) * modpow(dp[n - r], MOD - 2)) % MOD)) % MOD;
}

int main() {
    ios_base::sync_with_stdio(false); cin.tie(0);
    //freopen("test.txt", "r", stdin);
