    	if (arr[x]) len = i - arr[x];
    	arr[x] = i;
    }
    dp[1] = 1ll;
    FOR(i,2,n + 2) dp[i] = (dp[i - 1] * (ll) i) % MOD;
    FOR(i,1,n+2) {
    	ll cur = bin(n + 1, i);
    	ll mi = bin(n - len,i - 1);
    	cout << cur - mi << endl;
    }		
}

