const int N_MAX = 100005;

ll inv[N_MAX],fac[N_MAX],finv[N_MAX];
void make(){
    fac[0]=fac[1]=1;
    finv[0]=finv[1]=1;
    inv[1]=1;
    for(int i=2;i<N_MAX;i++){
        inv[i]=mod-inv[mod%i]*(mod/i)%mod;
        fac[i]=fac[i-1]*(ll) i%mod;
        finv[i]=finv[i-1]*inv[i]%mod;
    }
}

ll Combination(ll C, ll D){
    if(C<D || D<0) return 0;
    return fac[C]*(finv[D]*finv[C-D]%mod)%mod;
}

int main(){
    make();
    int n;
    cin >> n;
    int a[n+1];
    REP(i, n+1) cin >> a[i];
    int hash[n+1];
    memset(hash, -1, sizeof(hash));
    int s, t;
    REP(i, n+1){
        if(hash[a[i]]==-1) hash[a[i]] = i;
        else{
            s = hash[a[i]];
            t = i;
        }
    }
    cout << s << " " << t << endl;
    int A = s;
    int B = t-s-1;
    int C = n-t;
    cout << n << endl;
    if(n==2){
        if(a[1]==1){
            cout << 3 << endl;
        }else{
            cout << 2 << endl;
        }
        cout << 1 << endl;
    }else{
        for(int k=2;k<=n+1;k++){
                ll res = 0;
                res += Combination(n-1, k);
                res += Combination(n-1, k-2);
                res += 2*(Combination(A+B+C, k-1)-Combination(A+C, k-1));
                res += Combination(A+C, k-1);
                cout << (res%mod+mod)%mod << endl;
            }
    }
    return 0;
}

