const int MOD=1000000007;
void extgcd(int a,int b,int *x,int *y) {
	if(a<b) {
		extgcd(b,a,y,x);
	} else {
		if(b==0) {
			*x=1;
			*y=0;
		} else {
			int xk,yk;
			extgcd(b,a%b,&xk,&yk);
			*x=yk;
			*y=xk-(a/b)*yk;
		}
	}
}
int inv(int vl) {
	int xk,yk;
	extgcd(vl,MOD,&xk,&yk);
	if(xk<0) xk+=MOD;
	return xk;
}
