V<V<i64>> xs;

i64 comb_mod(i64 n, i64 r) {
    if (n < r) {
        return 0;
    }
    if (n == 0) {
        return 1;
    }
    if (r == 0) {
        return 1;
    }

    auto t = xs[n][r];
    if (t >= 0) {
        return t;
    }

    auto t1 = xs[n - 1][r - 1];
    auto t2 = xs[n - 1][r];

    if (t1 < 0) {
        t1 = comb_mod(n-1, r-1);
    }
    if (t2 < 0) {
        t2 = comb_mod(n-1, r);
    }

    auto x = t1 + t2;
    x %= mod;

    xs[n][r] = x;
    return x;
}


