            }
        }
    }

    FOR (k, 1, n + 2) {
        auto max = comb_mod(n + 1, k);

        REP (x, min(k, d1 + 1)) {
            // <x個> d1 or d2 <k-x-1個>
            // (d1 C x) * ((n-d2) C (k-x-1)
            auto minus = comb_mod(d1, x) * comb_mod(n - d2, k - x - 1);
            max -= minus;
        }

        if (max < 0) { max += mod; }
        max %= mod;

        cout << max << endl;
    }

    return 0;
}

