ll factorial(int n,int M){
  ll ret=1;
  if(n<=1) return 1;

  for(int i=1;i<=n;i++){
    ret = (ret*i)%M;
  }

  return ret;
}

ll power(int k,int n,int M){
  if(n==0) return 1;
  if(n==1) return (ll)k;

  ll ret = power(k,n/2,M);

  ret=(ret*ret)%M;

  if(n%2==1)
    ret=(ret*k)%M;

  return ret;
}

void fac_init(int n){
  fac[0] = 1;
  for(int i=1;i<=n;i++) fac[i] = (fac[i-1] * i)%mod;
  inv[n] = power(fac[n],mod-2,mod);
  for(int i=n;i>0;i--) inv[i-1] = (inv[i] * i)%mod;
}

