/*Combination*/
int C(int n,int m,int M){
  if(n<m) return 0;
  if(m==0 || n==m) return 1;

  ll chi = fac[n];
  ll mot = (inv[m] * inv[n-m])%M;

  ll ret = (chi*mot)%M;

  return (int)ret;
}

