ll cpow (ll b, int e)
{
    if (e == 0) return 1;
    ll v = cpow (b, e / 2);
    v = (v * v) % MOD;
    if (e % 2) v = (v * b) % MOD;
    return v;
}

ll ch (int n, int k)
{
    if (n < k) return 0;
    if (n < 0) return 0;
    if (k < 0) return 0;
    ll v = (fac[n] * finv[k]) % MOD;
    v = (v * finv[n-k]) % MOD;
    return v;
}

int main()
{
