#define si(n) scanf("%d",&n)
#define MAX 100005
#define MOD 1000000007
#define ll long long

map<int,int>mp;
int arr[MAX],n,pos,val;
int fact[MAX];

void go()
{
    fact[0]=1;
    for(int i=1;i<MAX;i++){
        fact[i]=((ll)fact[i-1]*i)%MOD;
    }
}

int bigmod(long long a,long long p)
{
    long long ret = 1;
    while(p) {
        if(p & 1) ret = ret * a % MOD;
        a = a * a % MOD;
        p >>= 1;
    }
    return ret;
}

int main()
{
    //freopen("input.txt","r",stdin);
    int i,j;
    si(n);
    for(i=1;i<=n+1;i++){
        si(arr[i]);
        if(mp[arr[i]]){
            pos=i;
            val=arr[i];
        }
        else mp[arr[i]]=i;
    }
    go();

    printf("%d\n",n);
    for(i=2;i<=n;i++){
        int tot=mp[val]-1+(n+1-pos);
        ll a=fact[n+1];
        ll b=((ll)fact[i]*fact[n+1-i])%MOD;
        int ans=(a*bigmod(b,MOD-2))%MOD;
        if(tot<i-1){
            printf("%d\n",ans);
            continue;
        }
        a=fact[tot];
        b=((ll)fact[i-1]*fact[tot-(i-1)])%MOD;

        tot=(a*bigmod(b,MOD-2))%MOD;
        //cout<<ans<<' '<<tot<<endl;
        printf("%d\n",ans-tot);
    }
    printf("%d\n",1);



}

