ll powLL(ll a, ll n){
    ll res = 1;
    while(n>0){
        if(n&1){
            res *= a;
            res %= mod;
        }
        a = a*a;
        a %= mod;
        n >>= 1;
    }
    return res;
}

ll Combination(ll C, ll D){
    if(C==0 || C<D) return 0;
    return (((fact[C] * powLL(fact[D], mod-2))%mod)*powLL(fact[C-D], mod-2))%mod;
}

