  public:
    void PrecomputeFactorials(int n) {
        fac.resize(n+1);
        inv_fac.resize(n+1);

        fac[0] = 1;
        for (int i = 1; i <= n; ++i) {
            fac[i] = fac[i-1] * i;
        }

        inv_fac[n] = fac[n].Inv();
        for (int i = n-1; i >= 0; --i) {
