#include <bits/stdc++.h>

using namespace std;

const long long mod = 1e9 + 7;
const int N = 100005;

long long bigmod(long long n, long long r){
	if(r == 0) return 1LL;
	if(r % 2 == 0){
		long long ret = bigmod(n, r / 2);
		return (ret * ret) % mod;
	}
	return (n * bigmod(n, r - 1)) % mod;
}

long long F[N], I[N];

void init(){
	F[0] = 1;
	for(long long i = 1; i < N; ++i){
		F[i] = (F[i-1] * i) % mod;
	}
	for(int i = 0; i < N; ++i){
		I[i] = bigmod(F[i], mod - 2);
	}
}

long long nCr(int n, int k){
	if(k > n) return 0;
	return (((F[n] * I[k]) % mod) * I[n - k]) % mod;
}

int n, a[N], v, p1, p2;
int cnt[N];

int main(){
	init();
	scanf("%d", &n);
	++n;
	for(int i = 1; i <= n; ++i){
		scanf("%d", &a[i]);
		cnt[a[i]]++;
	}
	p1 = n + 1;
	p2 = 0;
	for(int i = 1; i <= n; ++i){
		if(cnt[i] == 2){
			for(int j = 1; j <= n; ++j){
				if(a[j] == i){
					p1 = min(p1, j);
					p2 = max(p2, j);
				}
			}
		}
	}
	for(int i = 1; i <= n; ++i){
		long long ans = 0;
		ans += nCr(n - 2, i);
		ans += nCr(n - 2, i - 2);
		ans += 2LL * nCr(n - 2, i - 1);
		ans -= nCr(p1 - 1 + n - p2, i - 1);
		ans %= mod;
		ans += mod;
		ans %= mod;
		printf("%lld\n", ans);
	}
	return 0;
}

