	return a * b / gcd(a, b);
}
// a x + b y = gcd(a, b)
Int extgcd(Int a, Int b, Int &x, Int &y) {
	Int g = a;
	x = 1;
	y = 0;
	if (b != 0)
		g = extgcd(b, a % b, y, x), y -= (a / b) * x;
	return g;
}
Int invMod(Int a, Int m) {
	Int x, y;
	if (extgcd(a, m, x, y) == 1)
		return (x + m) % m;
	else
		return 0; // unsolvable
}

Int memo[100010];
Int modFuct(Int a, Int m) {
	if (a == 0) {
		return 1;
	}
	if (memo[a] > 0) {
		return memo[a];
	}
	return memo[a] = modFuct(a - 1, m) * a % m;
}

Int C(Int n, Int r, Int m) {
	if (n < 2 * r)
		return C(n, n - r, m);
	Int res = 1;
	for (int i = 0; i < r; i++) {
		res = res * (n - i) % m;
	}
	res = res * invMod(modFuct(r, m), m) % m;
	return res;
}

