#define MAX 100001
#define INF 1000000007

using namespace std;

long long f[MAX],fi[MAX];

long long power(int a,int b){
  long long ans=1;
  long long p=a;
  while(b>0){
    if(b%2==0){
      p=(p*p) % INF;
      b=b/2;
    }else{
      ans=(ans*p) % INF;
      b--;
    }
  }
  return ans;
}

void factorial(int N){
  f[0]=1;
  fi[0]=1;
  for(int i=1;i<=N;i++){
    f[i]=(f[i-1]*i)%INF;
    fi[i]=power(f[i],INF-2);
  }
}

long long C(int n,int r){
  return (((f[n]*fi[r]) %INF) *fi[n-r] ) % INF;
}

