#define MAX_N 100005

ll fact[MAX_N];             // N!
ll fact_inv[MAX_N];         // N!の逆元

// O(log n)でx^n(modを法とする)
ll mod_pow(ll x,ll n,ll mod){
    ll res=1;
    while(n){
        if(n&1) res = (res*x)%mod;
        x = (x*x)%mod;
        n>>=1;
    }
    return res;
}

// O(log mod)で x^-1 を計算(法をmodとする)
ll invp(ll x,ll mod){
    return mod_pow(x,mod-2,mod);
}

// 法をmodとして組み合わせ nCrを計算(O(1))
ll nCr(ll n,ll r,ll md=mod){
    if(n<r) return 0;
    ll ret = fact[n];
    ret = (ret * fact_inv[r]) % md;
    ret = (ret * fact_inv[n-r]) % md;
    return ret;
}

// 初期化 O(MAX_N * log(mod)) くらいかなぁ
void init(){
    fact[0]=1;
    for(int i=1;i<MAX_N;i++) fact[i]=(fact[i-1]*i)%mod;
    for(int i=0;i<MAX_N;i++) fact_inv[i]=invp(fact[i],mod);
}

