const long long MOD = 1000000000 + 7;

int exp_mod(long long a, long long b, int m, map<long long, int> &expMod) {
    if(expMod.find(a) != expMod.end()){
        return expMod[a];
    }
	long long res = 1;
	while (b > 0) {
		if (b&1)
			res = (res * a)%m;
		a = (a * a)%m;
		b >>= 1;
	}
	expMod[a] = (int)res;
	return expMod[a];
}

int fact_mod(int n, int m, vector<int> &factMod) {
    if(factMod[n] > 0) return factMod[n];
	long long res = 1;
	for (int i=n; i>0; --i)
		res = (res * i)%m;
	factMod[n] = res;
	return (int)res;
}

int comb_mod(int n, int r, vector<int> &factMod, map<long long, int> &expMod) {
    if(r>n)return 0;
	long long res = 1;
	for (int i=0; i<r; ++i)
		res = (res * (n - i) )%MOD;
	return ( res * exp_mod(fact_mod(r, MOD, factMod), MOD-2, MOD, expMod) ) % MOD;
}

