const ll K = 1E9 + 7.1;
ll extended_euclid(ll a, ll b, ll &x, ll &y) {
	ll xx = y = 0;
	ll yy = x = 1;
	while (b) {
		ll q = a / b;
		ll t = b; b = a%b; a = t;
		t = xx; xx = x - q*xx; x = t;
		t = yy; yy = y - q*yy; y = t;
	}
	return a;
}

ll mod_inverse(ll a, ll n) {
	ll x, y;
	ll g = extended_euclid(a, n, x, y);
	if (g > 1) return -1;
	return (x + n) % n;
}
ll perm_mod(ll n, ll k, const ll m)
{
    assert(m > 0);
    if (k > n) return 0;
    ll ret = 1;
    while (k--)
    {
        ret = (ret * (n--) % m) % m;
    }
    return ret;
}
