long long kiss(long long xx, int yy)
{
	if (yy == 0)
	{
		return 1LL;
	}
	else if (yy == 1)
	{
		return (xx % (long long)(MODULO));
	}
	else
	{
		long long Ans = kiss((xx*xx) % (long long)MODULO, yy >> 1);
		if (yy & 1)
		{
			Ans *= xx;
		}
		Ans %= (long long)MODULO;
		return Ans;
	}
}

int main()
{
	fact[0] = fact[1] = 1;
	for (int i = 2;i < N - 7;i++)
