		tmp *= fc--;
		tmp %= (long long)MODULO;
		tmp *= inv[k];
		tmp %= (long long)MODULO;
		r1 = (int)tmp;
		tmp = (long long)r2;
		if (k - 1 > alpha + beta)
		{
			tmp = 0;
		}
		else
		{
			tmp *= ft--;
			tmp %= (long long)MODULO;
			tmp *= inv[k - 1];
			tmp %= (long long)MODULO;
