typedef long long LL;

const int MaxN = 2e5, Pt = 1e9 + 7;
int n;
LL fac[MaxN + 5];
LL cnt[MaxN + 5];
LL a[MaxN + 5];
LL l, r;

LL qwr(LL x, LL y)
{
	LL res = 1;
	while (y != 0) {
		if (y & 1) res = (res * x) % Pt;
		y >>= 1LL;
		x = (x * x) % Pt;
	}
	return res;
}

LL C(LL n, LL m)
{
	if (m > n) return 0;
	if (m == 0) return 1;
	return ((fac[n] * qwr(fac[n - m], Pt - 2)) % Pt) * qwr(fac[m], Pt - 2) % Pt;
}

void Init()
{
	memset(cnt, 0, sizeof(cnt));
	LL t;
	for (int i = 1; i <= n + 1; i++) {
		scanf("%lld", &a[i]);
		cnt[a[i]]++;
		if (cnt[a[i]] == 2) t = a[i];
	}
	l = -1; r = -1;
	for (int i = 1; i <= n + 1; i++) {
		if (a[i] == t && l == -1) l = i;
		else if (a[i] == t) r = i;
	}
}

void Solve()
{
	LL sum = l - 1 + n + 1 - r;
	//printf("%lld\n", sum);
	if (n + 1 >= 1) printf("%lld\n", (LL)n);
	if (n + 1 >= 2) printf("%lld\n", ((C(n + 1, 2) - sum) % Pt + Pt) % Pt);
	if (n + 1 >= 3) {
		for (LL k = 3; k <= n + 1; k++) {
			//LL ans = ((C(n + 1, k) + C(n + 1 - r, k - 1)) % Pt + C(l - 1, k - 1)) % Pt;
			LL ans = C(n + 1, k);
			ans = ((ans - C(sum, k - 1)) % Pt + Pt) % Pt;
			printf("%lld\n", ans);
		}
	}
}

int main()
{
	fac[0] = 1;
	for (int i = 1; i <= 2e5; i++) fac[i] = (fac[i - 1] * (LL)i) % Pt;
	while (~scanf("%d", &n)) {
		Init();
		Solve();
	}
	return 0;
}

