    }
    vector<int> seen(n + 1, -1);
    for (int i = 0; i < n + 1; i ++) {
        int a;
        scanf("%d", &a);
        if (seen[a] >= 0) {
            pos1 = seen[a];
            pos2 = i;
        }
        seen[a] = i;
    }
    int N = n + 1;
    int len_I = pos1;
    int len_III = N - pos2 - 1;
    for (int k = 1; k <= N; k ++) {
        ll sum;
        int l_min = max(k - 1 - len_III, 0);
        int l_max = min(len_I, k - 1);
        if (l_min <= l_max) {
            sum = combination(len_I + len_III, k - 1);
        } else {
            sum = 0;
        }
        sum = (combination(N, k) - sum + MOD) % MOD;
        printf("%lld\n", sum);
    }
}

