int prime = 1000000007;
long long fac[100002];

void calc_fac(){
    fac[0] = 1;
    for(int i = 1; i < 100002; i++){
        fac[i] = fac[i-1] * i % prime;
    }
}

long long pow(long long a, long long n){
    if(n==1){return a%prime;}
    long long half_pow = pow(a, n/2);
    if(n%2){
        return half_pow * half_pow % prime *a %prime;
    }else{
        return half_pow * half_pow % prime;
    }
}

long long inv(long long a){
    return pow(a, prime-2);
}

long long c(int n, int k){
    return fac[n]*inv(fac[k]) %prime *inv(fac[n-k])%prime;
}

