        ll divisor;
    public:
        combination_modulo(ll div,ll max_n):divisor(div),factorial_mod(vector<ll>(max_n+1))
        {
            factorial_mod[0]=1;
            for(ll i=1;i<=max_n;++i)factorial_mod[i]=factorial_mod[i-1]*i%divisor;
        }
        ll operator()(ll n,ll r)
        {
            if(n<r)return 0;
            ll numerator=factorial_mod[n];
            ll denominator=factorial_mod[r]*factorial_mod[n-r]%divisor;
            ll index=divisor-2,power=1;
