const long mod = 1000000007;

struct Solver {
   Solver() { fprintf(stderr, "--------Solver begin--------\n"); }
   ~Solver() { fprintf(stderr, "--------Solver end--------\n"); }
   long modpow(long x, long n) {
      if( n == 0 ) return 1;
      long t = modpow(x, n / 2);
      long y = (t * t) % mod;
      return n % 2 == 1 ? (y * x) % mod : y;
   }
   long factMemo[112345];
   long factMemo2[112345];
   long nCr(long n, long r) {
      if( r < 0 ) return 0;
      if( n < 0 ) return 0;
      if( n < r ) return 0;
      if( n == 0 or r == 0 ) return 1;
      return ((factMemo[n] * factMemo2[r]) % mod * factMemo2[n-r]) % mod;
   }
   void initFactMemo() {
      factMemo[0] = factMemo2[0] = 1;
      for(long i = 1; i < 112345; ++i) {
         factMemo[i] = (factMemo[i-1] * i) % mod;
         factMemo2[i] = modpow(factMemo[i], mod - 2);
      }
   }
   void solve() {
      initFactMemo();
      long n; scan(n);
      n += 1;
      LI xs(n); for(long &x : xs) scan(x);
      LI ys(n, -1);
      long d = -1;
      for(long i = 0; i < n; ++i) {
