         long t0 = nCr(n-2, k);
         long t1 = (2 * nCr(n-2, k-1) + mod - nCr(n-2-d, k-1)) % mod;
         long t2 = nCr(n-2, k-2);
         long res = (t0 + t1 + t2) % mod;
         // dumplll(t0, t1, t2);
         printf("%ld\n", res);
      }
   }
};

