int modInv(int x)
{
    int k = MOD - 2;
    int ans = 1;
    while (k > 0)
    {
        if (k & 1)
        {
            ans = (int) (((long long) ans * x) % MOD);
        }
        x = (int) (((long long) x * x) % MOD);
        k >>= 1;
    }
    return ans;
}

int choose(int a, int b)
{
    if (b > a)
        return 0;
    int ans = (int) (((long long) fac[a] * facInv[b]) % MOD);
    ans = (int) (((long long) ans * facInv[a - b]) % MOD);
    return ans;
}

