// nPr
template <typename T>
T nPr(T n, T r, T mod = std::numeric_limits<T>::max()){
    if(n < r){return 0;}
    return fact[n] * inv[r] % mod;
}

// nCk
template <typename T>
T nCk(T n, T k, T mod = std::numeric_limits<T>::max()){
    if(n < 0 || k < 0){return 0;}
    if(n < k){return 0;}
    return fact[n] * inv[k] % mod * inv[n-k] % mod;
}

template <typename T>
T nHk(T n, T k, T mod = std::numeric_limits<T>::max()){
    if(n == 0 && k == 0){return 1;}
    return nCk(n+k-1, k);
}

