Int pow(Int n, Int p){
  if(p == 0)return 1;
  Int res = pow(n,p/2);
  res *= res;res %= MOD;
  if(p%2)res *= n;
  return res % MOD;
}

Int inv(Int x){
  return pow(x, MOD-2);
}

Int init(){
  fact[0] = 1;
  for(int i = 1;i < 216000;i++)fact[i] = fact[i-1]*i % MOD;
}

Int nCk(Int n, Int k){
  if(k < 0 || k > n)return 0;
  Int res = fact[n];
  res *= inv(fact[n-k]);res %= MOD;
  res *= inv(fact[k]);res %= MOD;
  return res;
}

Int solve(Int x){
  Int res = nCk(n+1, x) - nCk(c, x-1);res %= MOD;
  if(res < 0)res += MOD;
