const int N = 1e5 + 5, mod = 1e9 + 7;
int bt[N];

ll fact[N], ifact[N];

ll mod_inverse(ll a, ll b)
{
    ll ret = 1ll;
    for(;b ; b >>= 1)
    {
        if(b&1) ret = (ret * a) % mod;
        a = (a * a) % mod;
    }
    return ret % mod;
}



void calc()
{
    fact[0] = fact[1] = 1;

    ifact[0] = 1;
    ifact[1] = 1;

    for(int i = 2; i < N; i++)
    {
        fact[i] = (fact[i - 1] * i) % mod;
        ifact[i] = (ifact[i - 1] * mod_inverse(i, mod - 2) ) % mod;
    }
}


ll nCr(int n, int r)
{
    if(r > n) return 0;
    return (1ll * fact[n] * (( ifact[r] * ifact[n - r] ) % mod) ) % mod;
}





