    rreps(i, max) finv[i - 1] = finv[i] * i;
  }
  mint com(int a, int b) {
    if (a < 0) return 0;
    if (b < 0 || b > a) return 0;
    return fac[a] * finv[a - b] * finv[b];
  }
  mint hom(int a, int b) {
    return com(a + b - 1, b);
  }
};

