      ans = 0;
  }else{
      ans = (fac[n]*finv[r])%P;
      ans = (ans*finv[n-r])%P;
      ans = (ans+P)%P;
  }
  return ans;
}

void make(){
    fac[0]=fac[1]=1;
    finv[0]=finv[1]=1;
    inv[1]=1;
    for(int i=2;i<N_MAX;i++){
        inv[i]=P-inv[P%i]*(P/i)%P;
        fac[i]=fac[i-1]*(long) i%P;
        finv[i]=finv[i-1]*inv[i]%P;
    }
}

