//累乗を計算
ll calc(ll a, ll b){
	if(b == 0){
		return 1;
	}else if(b == 1){
		return a;
	}else if(b % 2 == 0){
		ll c = calc(a, b / 2);
		return (c * c) % mod;
	}else{
		return (a * calc(a, b - 1)) % mod;
	}
}

