			u[i] *= (n + 2 - j);
			u[i] %= mod;
			u[i] *= calc(j, mod - 2);
			u[i] %= mod;
		}
		if(i <= a + b){
			ll k = a + b;
			for(ll j = 2; j <= i; j++){
				k *= (a + b - j + 1);
				k %= mod;
				k *= calc(j, mod - 2);
				k %= mod;
			}
