  {
    if (c[a[i]] == 2) {
      l = i - 1;
      break;
    }
  }
  REP(i,1,n+1)
  {
    ll ans = nCr(n + 1, i) - nCr(l + r, i - 1);
    cout << ans % MOD << endl;
