int quickPow(int x, int n) {
    if (n == 0) {
        return 1;
    }

    int t = quickPow(x, n / 2);
    (t *= t) %= mod;

    if (n % 2 == 0) {
        return t;
    }
    return (t * x) % mod;
}

int fact[SIZ];

void precalc() {
    fact[0] = 1;
    for (int i = 1; i < SIZ; i++) {
        fact[i] = (fact[i - 1] * i) % mod;
    }
}

int choose(int n, int k) {
    if (n < k) {
        return 0;
    }

    return ((fact[n] * quickPow((fact[n - k] * fact[k]) % mod, mod - 2)) % mod);
}

