ll mod = 1e9+7;

ll pow(int n, int k, int mod) {
    if (k == 0) return 1;
    else if (k % 2 == 1) {
        return n * pow(n, k - 1, mod) % mod;
    } else {
        ll t = pow(n, k / 2, mod);
        return t * t % mod;
    }
}

void init(int n, int mod) {
    fact[0] = 1;
    inverse[0] = 1;
    ll now = 1;
    for(int i = 1; i <= n; i++) {
        now = now * i % mod;
        fact[i] = now;
        inverse[i] = pow(now, mod - 2, mod);
    }
}

int comb(int n, int k, int mod) {
    if (n < 0 || k < 0 || k > n) return 0; 
    return (fact[n] * inverse[k]) % mod * inverse[n - k] % mod;
}

