constexpr auto P = 1'000'000'007;

int combination(int m, int n) {
  if (m < n)
    return 0;
  if (m == n)
    return 1;
  if (m - n < n)
    return combination(m, m - n);
  int64_t r = 1;
  for (int i = 1; i <= n; i++) {
    r *= (m - i + 1);
    if (r % i == 0) {
      r /= i;
    } else {
      decltype(r) rn = P, rn1 = i, an = 0, bn = 1, cn = 1, dn = -rn / rn1;
      while (rn1 != 1) {
        assert(rn1 > 0);
        assert(rn > rn1);
        auto rn2 = rn % rn1;
        assert(rn2 == cn * P + dn * i);
        decltype(r) kn1 = rn1 / rn2;
        std::tie(an, bn, cn, dn) =
            std::make_tuple(cn, dn, an - kn1 * cn, bn - kn1 * dn);
        std::tie(rn, rn1) = std::make_tuple(rn1, rn2);
				assert(rn1 == an * P + bn * i);
      }
      assert((bn * i) % P == 1 || (bn*i) % P == 1-P);
      r *= bn;
      while (r < 0)
        r += P;
    }
    r %= P;
  }

  return r;
}

int main(void) {
  int N;
  std::cin >> N;
  if (N == 1) {
    std::cout << 1 << std::endl;
    return 0;
