  std::cout << N << std::endl; // 1

  for (int i = 2; i < N + 1; i++) {
    int ans = combination(N + 1, i) //
              - combination(N - M, i - 1);
    while (ans < 0)
      ans += P;
    std::cout << ans << std::endl;
  }
  std::cout << 1 << std::endl; // N+1
  return 0;
}

