    int x;cin>>x;
    if(ctr[--x]==-1)ctr[x]=i;
    else{
      a=ctr[x];
      b=i-a-1;
      c=n-i;
      break;
    }
  }
  rep(i,1,n+2){
    ll ans=0;
    ans+=COM(a+b+c,i);ans%=mod;
    ans+=COM(a+b+c,i-2);ans%=mod;
    ans+=COM(a+b+c,i-1);ans%=mod;
    ans+=COM(a+b+c,i-1);ans%=mod;
    ans-=COM(a+c,i-1);ans%=mod;
    cout<<ans<<endl;
  }
}

