// return n! mod p
int fact(int n, int p = INT_MAX){
    static vector<int> memo(1, 1);
    if ((int) memo.size() <= n) {
        int l = memo.size();
        memo.resize(n+1);
        for(int i = l; i <= n; i++) memo[i] = (ll) memo[i-1] * i % p;
    }
    return memo[n];
}

//solve ax+by=gcd(a, b)
//return gcd(a, b)
int gcd(int a, int b, int* px = NULL, int* py = NULL){
    if(py == NULL){
        if(b == 0) return a;
        return gcd(b, a % b);
    }
    int d = a;
    if( b != 0){
        d = gcd(b, a % b, py, px);
        *py -= (a / b) * *px;
    }else{
        *px = 1; *py = 0;
    }
    return d;
}

// return a^(-1) mod m
int modInverse(int a, int m = MOD){
    int x, y;
    gcd(a, m, &x, &y);
    return (m + x % m) % m;
}

// return a mod p (when n!=a*p^e), o(log_p n)
int modFact(int n, int& e, int p = MOD){
    e = 0;
    if(n == 0) return 1;

    int res = modFact(n / p, e, p);
    e += n / p;

    if((n / p % 2 != 0)) return (ll) res * (p - fact(n % p, p)) % p;
    return (ll) res * fact(n % p, p) % p;
}

// return nPk mod p
int perm(int n, int k, int p = MOD){
    if(n < 0 or k < 0 or n < k) return 0;
    int e1, e2;
    int a1 = modFact(n, e1, p), a2 = modFact(n - k, e2, p);
    return (ll) a1 * modInverse(a2, p) % p;
}

// return nCk mod p, o(log_p n)
int comb(int n, int k, int p = MOD){
    if(n < 0 or k < 0 or n < k) return 0;
    int e1, e2, e3;
    int a1 = modFact(n, e1, p), a2 = modFact(k, e2, p), a3 = modFact(n - k, e3, p);
    if(e1 > e2 + e3) return 0;
    return (ll) a1 * modInverse((ll)a2 * a3 % p, p) % p;
}

// return nHk mod p
int hcomb(int n, int k, int p = MOD){
    if(n < 0 or k < 0) return 0;
    if(n == 0 and k == 0) return 1;
    return comb(n + k - 1, k, p);
}

