	f = s = -1;
	for (long long int i = 0; i < n + 1; i++) {
		if (a[i] == p) {
			f = i;
			break;
		}
	}

	for (long long int i = n; i >= 0; i--) {
		if (a[i] == p) {
			s = i;
			break;
		}
	}

	int ff, mm, ee;
	ff = f;
	ee = n - s;
	mm = n + 1 - 2 - ff - ee;

	cout << n << endl;

	for (long long int i = 1; i < n + 1; i++) {
		long long int ans = 0;
		ans += ncr(ff + ee + mm, i + 1); //2つとも含まない
		//cout << ncr(ff + ee + mm, i + 1) << ' ' << ncr(ff + ee + mm, i - 1) << ' ' << ncr(ff + ee + mm, i) << ' ' << ncr(ff + ee, i) << endl;
		ans %= M;
		ans += ncr(ff + ee + mm, i - 1); //2つとも含む
		ans %= M;
		ans += ncr(ff + ee + mm, i) + ncr(ff + ee + mm, i) - ncr(ff + ee, i); //1つのみ含む
		ans %= M;
		cout << ans << endl;
	}

	return 0;
}

