ll inv(ll x, ll n) {
  ll sum = 1;
  while (n > 0) {
    if ((n & 1L) == 1L) {
      sum = (sum * x) % MOD;
    }
    x = (x * x) % MOD;
    n = n >> 1L;
  }
  return sum;
}

void factorial() {
  invn = inv(n, MOD - 2);
  fact[0] = 1;
  REP(k,1,n+1)
  {
    fact[k] = (fact[k - 1] * k) % MOD;
  }
  ifact[0] = 1;
  REP(k,1,n+1)
  {
    ifact[k] = (ifact[k - 1] * iv[k]) % MOD;
  }
}

ll nCr(ll n, ll r) {
  if (n < r || r < 0 || n < 0) {
    return 0;
  }
  if (r > n / 2) {
    r = n - r;
  }
  return (((fact[n] * ifact[n - r]) % MOD) * ifact[r]) % MOD;
}

ll adjust(ll N) {
  //左にl個、 右にr個、最低1つ、合わせてN個取る組み合わせ
  if (N == 0) {
    return 1;
  }
  ll L = 0;
  ll R = N - L;
  ll ret = 0;
  while (R >= 0) {
    if (L > l || R > r) {
      L++;
      R = N - L;
      continue;
    }
    ret += (nCr(l, L) * nCr(r, R)) % MOD;
//    dbp3(ret, L, R);
    L++;
    R = N - L;
  }
  return ret;
}

