ll fact[MAX_N];
ll fact_inv[MAX_N];
bool isExist[MAX_N];

ll combination(int n, int r) {
    assert(n <= N+1);
    assert(r <= n);
    ll ret = (fact[n] * fact_inv[n - r]) % MOD;
    ret = (ret * fact_inv[r]) % MOD;
    return ret;
}
ll mod_pow(ll x, ll n, ll mod) {
    ll res = 1;
    while ( n > 0) {
        if (n & 1) { res = res * x % mod; } // 最下位ビットが立っているときに x^(2^i) を掛ける
        x = x * x % mod;                    // x を順次 2 乗していく
        n >>= 1;
    }
    return res;
}

