        fact[i] = fact[i-1] * i;
        fact[i] %= MOD;
    }
    fact_inv[N+1] = mod_pow(fact[N+1], MOD-2, MOD);
    assert((fact[N+1] * fact_inv[N+1] % MOD) == 1);
    for(int i = N; i >= 0; --i) {
        fact_inv[i] = (fact_inv[i + 1] * (i + 1)) % MOD;
