LL  qwr(LL x, LL y)
{
	LL res = 1;
	while(y > 0)
	{
		if(y & 1) res = (res * x) % MOD;
		x = (x * x) % MOD;
		y = y >> 1;
	}
	return res % MOD;
}
LL C(LL n, LL m)
{
	if(n < 0 || m < 0) return 0;
	if(n < m) return 0;
	return (((fact[n] * rev[m]) % MOD) * rev[n - m]) % MOD;
}

int main()
{
