ll MOD = 1000000007;

ll modPow(ll x, ll y)
{
    ll r=1, a=x;
    while (y > 0) {
        if ( (y&1)==1 ) {
            r = (r * a) % MOD;
        }
        a = (a * a) % MOD;
        y /= 2;
    }

    return r;
}
// Modular multiplicative inverse through Fermat's little theorem:
// 繝輔ぉ繝ｫ繝槭・縺ｮ蟆丞ｮ夂炊繧医ｊ, a^-1 竕｡ a^(p-2) (mod p) 縺ｨ縺・≧縺ｮ繧剃ｽｿ縺・ｉ縺励＞
// 縺溘□縺励｝縺檎ｴ謨ｰ縺ｮ譎ゅ＠縺区・繧顔ｫ九◆縺ｪ縺・ll modInverse(ll x)
{
    return modPow(x, MOD-2);
}

// Modular division x / y, find modular multiplicative inverse of y
// and multiply by x.
ll modDivision(ll p, ll q)
{
    return (p * modInverse(q)) % MOD;
}

// Binomial coifficient C(n,k) in O(k) time.
ll n_choose_k(ll n, int k)
{
    if (k > n) {
        return 0;
    }
    ll p = 1, q = 1;
    for (int i=1; i<=k; i++) {
        q = ( q * i) % MOD;
        p = ( p * (n - i + 1) ) % MOD;
    }
    return modDivision( p, q);
}

