long long D = 1000000007;
long long f[100010], u[100010];
long long res = 0;
int have[100010];

long long pw2(long long x, long long aa)
{
	long long y = 1;
	while(aa>0){
		if(aa % 2 == 1){
			y *= x;
			y %= D;
		}
		aa /= 2;
		x *= x;
		x %= D;
	}
	return y;
}

void pre()
{
	int i;
	f[0] = f[1] = 1;
	for(i=2; i<=n; i++){
		f[i] = f[i-1] * i;
		f[i] %= D;
	}
	u[0] = u[1] = 1;
	for(i=2; i<=n; i++){
		u[i] = pw2(f[i], D-2);
	}
}

long long calcC(long long nn, long long mm)
{
	if(nn < mm)
		return 0;
	if(nn == mm)
		return 1;
	long long r = f[nn];
	r *= u[mm];
	r %= D;
	r *= u[nn-mm];
	r %= D;
	return r;
}

void solve()
{
	pre();
	int i;
	int vv, ll=-1, rr=-1;
	for(i=0; i<n+1; i++){
