    ll res = binpow(deg >> 1, x);
    return res * res % base;
}

ll cnk(int n, int k) {
    if (k > n) return 0;
    return fact[n] * binpow(base - 2, fact[n - k] * fact[k] % base) % base;
}

int main() {
