template<typename T>
T combim(T n, T r, T mod = 1000000007ll) {
    T p = 1;
    for (; 0<r; r--)
        p = (((p*(n - r + 1)) % mod)*powm(r, mod - 2, mod)) % mod;
    return p;
}



