int lgpow(int a, int b, const int& MOD) {
    int sol = 1;

    while (b) {
        if (b & 1) {
            sol = (sol * 1LL * a) % MOD;
        }

        a = (a * 1LL * a) % MOD;
        b >>= 1;
    }

    return sol;
}

int invMod(int x, int MOD) {
    return lgpow(x, MOD - 2, MOD);
}

long long C(int n, int k, int MOD, int f[]) {
    return (((f[n] * 1LL * invMod(f[n - k], MOD)) % MOD) * 1LL * invMod(f[k], MOD));
}

