template<ull max_n, ull m>
class nCr_mod_m
{
public:
	nCr_mod_m() {
		fac[0] = fac[1] = 1;
		for (int i = 2; i <= max_n; i++)
			fac[i] = fac[i - 1] * i % m;
		inv[1] = 1;
		for (int i = 2; i <= max_n; i++)
			inv[i] = m - inv[m % i] * (m / i) % m;
		finv[0] = finv[1] = 1;
		for (int i = 2; i <= max_n; i++)
			finv[i] = finv[i - 1] * inv[i] % m;
	}

	ull C(ull n, ull r) {
		if (n < r)
			return 0;
		return fac[n] * (finv[r] * finv[n - r] % m) % m;
	}
private:
	ull fac[max_n + 1], inv[max_n + 1], finv[max_n + 1];
};
int main() {
	int n, a[100010], doubled, pos1, pos2;
	bool have[100010] = { false };
	nCr_mod_m<100010, 1000000007> nCr;
