  ll L = 0;
  ll R = N - L;
  ll ret = 0;
  while (R >= 0) {
    if (L > l || R > r) {
      L++;
      R = N - L;
      continue;
    }
    ret += (nCr(l, L) * nCr(r, R)) % MOD;
//    dbp3(ret, L, R);
    L++;
    R = N - L;
  }
  return ret;
}

