class Complex{
public:
	D re , im;
	Complex (){}
	Complex (D _r , D _i) : re(_r) , im(_i) {}
	Complex operator+ (Complex u){
		return Complex(re + u.re , im + u.im);
	}
	Complex operator* (Complex b){
		return Complex(re * b.re - im * b.im , re * b.im + im * b.re);
	}
	Complex operator* (D p){
		return Complex(re * p , im * p);
	}
	Complex operator- (Complex u){
		return Complex(re - u.re , im - u.im);
	}
	Complex operator/ (D p){
		return Complex(re / p , im / p);
	}
	Complex conj(){
		return Complex(re , -im);
	}
	void fft(Complex *b , Complex *wu){
		fft_core(b , wu);
	}
	void ifft(Complex *b , Complex *wu){
		fft_core(b , wu);

		for(int i = 0 ; i < l ; ++ i)
			b[i] = b[i] / l;
	}
	void get_rev(Complex *b){
		for(int i = 0 ; i < l ; ++ i)
			if(revv[i] > i)
				swap(b[i] , b[revv[i]]);
	}
	void fft_core(Complex *b , Complex *wu){
		get_rev(b);
		for(int k = 1 ; k < l ; k <<= 1)
			for(int i = 0 ; i < l ; i += (k << 1))
				for(int j = 0 ; j < k ; ++ j){
					Complex tmp1 = b[i + j] , tmp2 = b[i + j + k] * wu[k + j];
					b[i + j] = tmp1 + tmp2;
					b[i + j + k] = tmp1 - tmp2;
		}
	}
};

Complex wu1[MAXN] , wu2[MAXN];
