void compute_factorials(int maxn)
{
    fact[0] = fact[1] = 1;
    fact_inv[0] = fact_inv[1] = 1;
    for (long long i=2; i<=maxn; i++){
        fact[i] = (i*fact[i-1]) %MOD;
        fact_inv[i] = ((-(MOD/i) * fact_inv[MOD%i] % MOD) + MOD) % MOD;
    }
    for (long long i=2; i<=maxn; i++){
        fact_inv[i] = fact_inv[i-1] * fact_inv[i] % MOD;
        #ifdef DEBUG
        assert((fact[i]*fact_inv[i])%MOD == 1);
        #endif
    }
}

long long C(int n, int r)
{
    if (n < 0 || r < 0 || r > n)
        return 0;
    long long P = (fact[n]*fact_inv[r]) %MOD;
    return (P*fact_inv[n-r]) %MOD;
}

