		fac[i]=(long long)fac[i-1]*i%P;
	fac_inv[n]=1;
	for(int i=P-2,tmp=fac[n];i;i>>=1,tmp=(long long)tmp*tmp%P){
		if(i&1) fac_inv[n]=(long long)fac_inv[n]*tmp%P;
	}
	for(int i=n-1;i>=0;--i)
		fac_inv[i]=(long long)fac_inv[i+1]*(i+1)%P;
}

inline int C(int m,int n){
	return (long long)fac[m]*fac_inv[n]%P*fac_inv[m-n]%P;
