lint gcd(lint a, lint b) {
  if (b == 0) return a;
  return gcd(b, a % b);
}

lint lcm(lint a, lint b) {
  return a / gcd(a, b) * b;
}

// 拡張されたユークリッドの互除法
lint extgcd(lint a, lint b, lint& x, lint& y) {
  lint d = a;
  if (b != 0) {
    d = extgcd(b, a % b, y, x);
    y -= (a / b) * x;
  } else {
    x = 1; y = 0;
  }
  return d;
}

bool is_prime(lint n) {
  if (n < 2) return false;
  for (lint i = 2; i * i <= n; ++i) {
    if (n % i == 0) return false;
  }
  return true;
}

// nの約数 重複なし、sorted
vector<lint> divisor(lint n) {
  vector<lint> res;
  deque<lint> d;

  lint i = sqrt(n);
  if (i * i == n) {
    d.push_back(i);
    i--;
  }
  for (; i > 0; --i) {
    if (n % i == 0){
      d.push_front(i);
      d.push_back(n / i);
    }
  }

  res.insert(res.begin(), d.begin(), d.end());
  return res;
}


// 2 * 2 * 3 * 5 * 5 * 5 = {2:2, 3:1,5:3} みたいな map を返す
map<int, int> prime_factor(lint n) {
  map<int, int> res;
  for (int i = 2; i * i <= n; ++i) {
    while (n % i == 0) {
      ++res[i];
      n /= i;
    }
  }

  if (n != 1) res[n] = 1;
  return res;
}

const int MAX_N = 2020202;
