// 素数の全列挙 n以下の素数の個数が返る
int sieve(int n) {
  prime.clear();
  memset(memo, true, sizeof(memo));
  memo[0] = memo[1] = false;

  for (int i = 2; i <= n; ++i) {
    if (memo[i]) {
      prime.push_back(i);
      for (int j = 2 * i; j <= n; j += i) {
        memo[j] = false;
      }
    }
  }

  return prime.size();
}

const lint MAX_LEN = 1000000;
const lint MAX_SQRT_B = 1000000;
bool memo_alint[MAX_LEN];         //i means i + a
bool memo_smalint[MAX_SQRT_B];

// [a, b)の素数の個数をカウント
lint count_prime(lint a, lint b) {
  for (int i = 0; (lint)i * i < b; i++) memo_smalint[i] = true;
  for (int i = 0; i < b - a; i++)     memo_alint[i] = true;

  for (int i = 2; (lint)i * i < b; i++) {
    if (memo_smalint[i]) {
      for (int j = 2; (lint)j * j < b; j += i) memo_smalint[j] = false;
      for (lint j = max(2LL, (a + i - 1) / i) * i; j < b; j += i) memo_alint[j - a] = false;
    }
  }

  lint ret = 0;
  for (lint i = a; i < b; i++) {
    if (memo_alint[i]) ret++;
  }
  return ret;
}

// k項目までのフィボナッチ数列　{a_0 : 0, a_1 : 1, a_2 : 1, ... }
lint Fib[101010];
int calcFib(int k) {
  Fib[0] = 0;
  Fib[1] = Fib[2] = 1;
  for (int i = 3; i <= k; ++i) {
    Fib[i] = Fib[i - 1] + Fib[i - 2];
    // Fib[i] %= mod;
  }

  return Fib[k];
}

lint mod_pow(lint a, lint x, int p = 1e9 + 7) {
  lint ret = 1;
  for (lint i  = 1ll << 60; i; i >>= 1) {
    ret *= ret;
    ret %= p;
    if (x & i) { ret *= a; ret %= p; }
  }

  return ret;
}

lint inv(lint n, int p = 1e9 + 7) {
  return mod_pow(n, p - 2);
}

vector<lint> fact(1, 1);
lint Fact(lint n, int p = 1e9 + 7) {
  if (n == 0) return 1;
  if (fact.size() <= n) {
    fact.push_back(Fact(n - 1) * n % p);
  }
  return fact[n];
}

// nCk のmod
lint mod_Combination(lint n, lint k, int p = 1e9 + 7) {
  if (n < k || n < 0 || k < 0) return 0;
  return Fact(n, p) * inv(Fact(k, p), p) % p * inv(Fact(n - k, p), p) % p;
}

