ll bp(ll x, ll e) {
  ll y = 1;
  for(; e; e >>= 1) {
    if(e&1) y = y * x % M;
    x = x * x % M;
  }
  return y;
}

ll ncr(int n, int r) {
  if(n < r)
    return 0;
  return f[n] * bp(f[n-r] * f[r] % M, M-2) % M;
}

