long long int pow(long long int n, long long int k, long long int mod) {
	if (k == 0) return 1;
	else if (k % 2 == 1) {
		return pow(n, k - 1, mod) * n % mod;
	} else {
		long long t = pow(n, k / 2, mod);
		return t * t % mod;
	}
}

void init(long long int n) {
	long long int now = 1;
	fact[0] = 1;
	inverse[0] = 1;
	for(long long int i = 1; i <= n; i++) {
		now *= i;
		now %= mod;
		fact[i] = now;
		inverse[i] = pow(fact[i], mod - 2, mod);
	}
}

long long int comb(long long int n, long long int k) {
	if (n < k) return 0;
	if (n == k) return 1;
	if (k <= 0) return 1;
	if (n == 0) return 1;
	return (((((long long)fact[n]) * inverse[k]) % mod) * inverse[n - k]) % mod;
	/*
	return n * comb(n - 1, k - 1) / k;
	*/
}

