const int MAX_N = 2000001;

ll fact[MAX_N];
ll revfact[MAX_N];

void setFact(int N){
  fact[0] = 1;
  for(int i = 1; i < N; ++i){
    fact[i] = fact[i-1]*i;
    fact[i] %= mod;
  }
  revfact[N-1] = powmod(fact[N-1],mod-2);//逆元を求める
  for(int i = N-2;i >= 0;--i){
    revfact[i] = revfact[i+1] * (i+1);
    revfact[i] %= mod;//互いに素
  }
}

ll getC(int a, int b){
  return (fact[a] * revfact[b] % mod) * revfact[a-b] % mod;
}
