    for (int i = 2; i <= s; ++i)
    {
        if (n % i == 0)
        {
            return 0;
        }
    }
    return 1;
}

vector<P> prime_division(int n)
{
    vector<P> ret;
    int s = sqrt(n) + 1;
    int c = 0;
    for (int i = 2; i <= s; ++i)
    {
        if (n % i == 0)
        {
            c = 0;
            do
            {
                ++c;
                n /= i;
            } while (n % i == 0);
            ret.push_back(P(i, c));
        }
    }
    return ret;
}

vector<ll> facts;
vector<ll> finvs;
void combi_prepare(ll n, ll mod)
{
    facts = vector<ll>(n + 1);
    finvs = vector<ll>(n + 1);
    vector<ll> invs(n + 1);
    facts[0] = facts[1] = 1;
    finvs[0] = finvs[1] = 1;
    invs[1] = 1;
    for (ll i = 2; i < n + 1; ++i)
    {
        facts[i] = facts[i - 1] * i % mod;
        invs[i] = mod - invs[mod % i] * (mod / i) % mod;
        finvs[i] = finvs[i - 1] * invs[i] % mod;
    }
}
ll combi(ll n, ll r)
{
    if (n < r)
        return 0;
    if (n < 0 || r < 0)
        return 0;
    return facts[n] * (finvs[r] * finvs[n - r] % MOD) % MOD;
}

