constexpr int mod = 1000000007;

// modをとった和を返す
inline
int modPlus(int a, int b){return (a + b) % mod;}

// modをとった差を返す
inline
int modMinus(int a, int b){return (mod + a - b) % mod;}

// modをとった積を返す
inline
int modMultiple(int a, int b){return (static_cast<long long>(a) * b) % mod;}

// 階乗数n!を最初に計算して、呼ばれた時に返す
class Factorial {
    std::vector<int> table;
public:
    Factorial(int max) : table(max) // max:テーブルのサイズ
    {
        if (max == 0) return;
        table[0] = 1;
        for (int i = 1; i < max; ++i){
            table[i] = modMultiple(table[i - 1], i + 1);
        }
    }

    int operator () (int n)
    {
        if (n < 0) return 0;
        if (n == 0) return 1;
        return table[n - 1];
    }
};

// 階上数n!の逆数（逆元）を最初に計算して、呼ばれた時に返す
class FactorialInverse {
    std::vector<int> table;
    Factorial& fact;
public:
    FactorialInverse(int max, Factorial fact) : table(max), fact(fact) // max:テーブルのサイズ
    {
        if (max == 0) return;
        int digit  = 0;
        {
            int temp = mod - 2;
            while (temp > 0){
                temp >>= 1;
                ++digit;
            }
        }
        int origin = fact(max);
        std::vector<int> powerorigin2(digit);
        powerorigin2[0] = origin;
        for (int i = 1; i < digit; ++i){
            powerorigin2[i] = modMultiple(powerorigin2[i - 1], powerorigin2[i - 1]);
        }
        {
            int table_max = 1;
            int temp = mod - 2;
            for (int i = 0; temp > 0; ++i, temp >>= 1){
                if (!(temp & 1)) continue;
                table_max = modMultiple(table_max, powerorigin2[i]);
            }
            table[max - 1] = table_max; // origin^(mod - 2)
        }
        for (int i = max - 2; i >= 0; --i){
            table[i] = modMultiple(table[i + 1], i + 2);
        }
    }

    int operator () (int n)
    {
        if (n < 0) return 0;
        if (n == 0) return 1;
        return table[n - 1];
    }
};

