        constexpr inline modint operator[] (size_t i) const { return f[i]; }
    };
    template<size_t N> struct InvFact {
        i64 inv[N+1];
        i64 f[N+1];
        constexpr inline InvFact() : inv{0, 1}, f{1, 1} {
            for (int i = 2; i < N; ++i) {
                inv[i] = (MOD - MOD/i) * inv[MOD % i] % MOD;
                f[i] = f[i-1] * inv[i] % MOD;
            }
        }
        constexpr inline modint operator[] (size_t i) const { return f[i]; }
    };
