LL quickmod(LL a,LL b)
{
    LL ans=1;
    while(b)
    {
        if(b&1)
        {
            ans=(ans*a)%MOD;
            b--;
        }
        b/=2;
        a=((a%MOD)*(a%MOD))%MOD;
    }
    return ans;
}
LL C(LL a, LL b)
{
