	for (register ll i = 2; i < MAXN; i++)
	{
		fa[i] = fa[i - 1] * i % mod;
		inv[i] = (mod - mod / i) * inv[mod % i] % mod;
	}
	inv[0] = 1;
	for (register int i = 1; i < MAXN; i++)
		(inv[i] *= inv[i - 1]) %= mod;
}

ll C(ll n, ll k)
{
	ll ans = 0;
	if (k > n)
		return ans;
	ans = ((fa[n] * inv[k] % mod) * inv[n - k]) % mod;
	return ans;
}
