ll extgcd(ll a, ll b, ll& x, ll& y) {
  ll g = a; x = 1; y = 0;
  if(b != 0) {
    g = extgcd(b, a % b, y, x);
    y -= (a / b) * x;
  }
  return g;
}

ll invMod(ll a, ll m) {
  ll x, y;
  if(extgcd(a, m, x, y) == 1) return (x + m) % m;
  else return 0;
}

struct comb{
  vector<ll> fct;
  vector<ll> inv;
  comb(int N){
    fct.assign(N + 1, 1);
    inv.assign(N + 1, 1);

    REP(i, N) fct[i + 1] = fct[i] * (i + 1) % MOD;
    REP(i, N) inv[i + 1] = invMod(fct[i + 1], MOD);
  }
  ll get(int n, int k) {
    if((k > n) || (k < 0)) return 0;
    ll ret = (fct[n] * inv[n - k] % MOD) * inv[k] % MOD;
    return ret;
  }
};

