ll nCk(ll n, ll k)
{
	if (k > n) return 0;
	if (k * 2 > n) k = n - k;
	if (k == 0) return 1;

	ll result = n;
	for (int i = 2; i <= k; ++i) {
		result = (result*(n - i + 1)) % mod;
		result = (result*pow_mod(i, mod - 2)) % mod;
	}
	return result;
}


