template <typename T>
T power(T x, T n, T mod)
{
    T ans = 1;
    while (n > 0)
    {
        if (n & 1)
            ans = ans * x % mod;
        x = x * x % mod;
        n >>= 1;
    }
    return ans;
}

void cPrecal(int n)
{
    factorial = facInv = vector<lint>(n + 1, 1);
    for (int i = 1; i <= n; i++)
    {
        factorial[i] = factorial[i - 1] * i % MOD;
        facInv[i] = power(factorial[i], MOD - 2, MOD);
    }
}
lint nCr(int n, int r)
{
    if (n < r || r < 0)
        return 0;
    else
        return (factorial[n] * facInv[r] % MOD) * facInv[n - r] % MOD;
}


