    // (i) no targets + more
    FOR(k, 1, N) {
        ans[k] += cache_N1[k];
        ans[k] %= MOD;
    }
    // (ii) two targets + 0 or more
    FOR(k, 2, N+2) {
        ans[k] += cache_N1[k-2];
        ans[k] %= MOD;
    }
    // (iii) one target only
    ans[1] += 1;
    // (iv) one target + more
    FOR(k, 1, N) {
        if (k > (N-1 - left - right)) {
            ans[k + 1] += 2 * cache_N1[k];
