            // }

            auto tmp2 = cache_N1[k];
            ans[k + 1] += 2 * (tmp2 - tmp1 + MOD);
            ans[k + 1] %= MOD;
        }
    }

    FOR(i, 1, N+2) cout << ans[i] << endl;


