long long int modpow (long long int a, ll mo)
{
	ll res = 1;
	ll j=mo-2;
	while (j > 0)
		if (j & 1) {
			res = (res * a) % mo;
			--j;
		}
		else {
			a = (a * a) % mo;
			j >>= 1;
		}
	return res %mo;
}
