    map<int,int> ck;
    ii dbl(-1,-1);
    rep(i,N+1) {
        if (found(ck,a[i])) {
            dbl = ii(ck[a[i]], i); break;
        }
        ck[a[i]] = i;
    }
    int w = N+1, alpha = dbl.first, beta = w-dbl.second-1, ab = alpha + beta;
