    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    int a[n+1];
    map <int, int> mp;
    int key;
    for (int i = 0; i <= n; i++) {
        cin >> a[i];
        mp[a[i]]++;
        if (mp[a[i]] == 2) key = a[i];
    }

    int interval_count = 0;
    bool flag = false;
    for (int i = 0; i <= n; i++) {
        if (flag) {
            if (a[i] == key) break;
            interval_count++;
        } else {
            if (a[i] == key) flag = true;
        }
    }

    inv[1]=fac[1]=fiv[1]=inv[0]=fac[0]=fiv[0]=1;
    for (ll i = 2; i <= n; i++) {
        fac[i] = fac[i-1] * i % M; // n!
        inv[i] = inv[M%i] * (M-M/i) % M; // n^-1
        fiv[i] = fiv[i-1] * inv[i] % M; // (n!)^-1
    }

    for (int k = 1; k <= n+1; k++) {
        ll ans = 0;
        ans += combination(n-1, k-2);
        ans += combination(n-1, k);
        ans += 2 * combination(n-1, k-1);
        ans += M - combination(n-1-interval_count, k-1);
        cout << ans % M << "\n";
    }

    return 0;
}

