			ll d = ((fact.at(l) * fact_inv.at(t)) % mod *fact_inv.at(l - t)) % mod;
			d *= ((fact.at(r) * fact_inv.at(k - 1 - t)) % mod * fact_inv.at(r - k + 1 + t)) % mod;
			d %= mod;
			ans = (ans + mod - d) % mod;
		}
		cout << ans << endl;
	}
	cout << 1 << endl;

	return 0;
}

