}

//aのb乗
ll powMod(ll a, ll b) {
	ll res = 1;
	while(b > 0) {
		if(b & 1) res = res * a % MOD;
		if(res==0) res = MOD;
		a = a * a % MOD;
		if(a==0) a = MOD;
		b >>= 1;
	}
	return res;
}

ll comb(ll a, ll b){
	if(a == 0 || b == 0) return 1;
	return (((fact(a)*powMod(fact(b),MOD-2))%MOD)*powMod(fact(a-b),MOD-2))%MOD;
}

int main() {
	ll N;
	cin >> N;
	vector<ll> A(N+1);
	map<ll,ll> mp;
	for(int i=0;i<=N;i++) {
		cin >> A[i];
		mp[A[i]]++;
	}
	ll two = 0;
	for(auto m : mp) {
		if(m.second == 2)
			two = m.first;
	}
	ll posA[2], j = 0;
	for(ll i=0;i<=N;i++) {
		if(A[i] == two) {
			posA[j] = i;
			j++;
		}
	}
	ll L = posA[0], M = posA[1] - posA[0] - 1, R = N - posA[1];
	// L: 1個目のAより左の個数, M: 1個目と2個目のAの間の個数, R: 2個目のAより右の個数
	// {N-1}C{K} + ({L+M+R}C{K-1} + {M+R}C{K-1} - {R}C{K-1})
	for(ll k=1;k<=N+1;k++) {
		ll ans = 0;
		if(N-1 >= k) ans += comb(N-1, k);
		ans %= MOD;
		if(ans < 0) ans += MOD;
	   	if(L+M+1+R >= k-1) ans += comb(L+M+1+R, k-1);
		ans %= MOD;
		if(ans < 0) ans += MOD;
	    if(M+R >= k-1) ans += comb(M+R, k-1);
		ans %= MOD;
		if(ans < 0) ans += MOD;
		if(R >= k-1) ans -= comb(R, k-1);
		ans %= MOD;
		if(ans < 0) ans += MOD;
		cout << ans << endl;
	}
}

