constexpr long MOD = 1000000000 + 7;

long egcd(long a, long b)
{
    long r0 = a;
    long s0 = 1;
    long t0 = 0;
    long r1 = b;
    long s1 = 0;
    long t1 = 1;

    while (r1 != 0) {
        long q = r0 % r1;

        long r2 = r0 - q * r1;
        long s2 = s0 - q * s1;
        long t2 = t0 - q * t1;

        r0 = r1;
        s0 = s1;
        t0 = t1;
        r1 = r2;
        s1 = s2;
        t1 = t2;
    }

    long t = t1;
    while (t < 0)
        t += MOD;
    return t % MOD;
}

long divv(long a, long b)
{
    a *= egcd(MOD, b);
    a %= MOD;
    return a;
}

long EXC[50001];

long exc(long a)
{
    if (EXC[a] != 0)
        return EXC[a];

    long x = 1;
    for (long i = 2; i < a; ++i) {
        x *= i;
        x %= MOD;
    }
    EXC[a] = x;
    return x;
}

long comb(long a, long b)
{
    if (b > a)
        return 0;
    if (a - b < b)
        return comb(a, a - b);

    long p = exc(a);
    long q = exc(a - b);
    long r = exc(b);

    return divv(divv(p, q), r);
}

