	while (y) {
		if (y & 1) ans = (ans * val) % MOD;
		val = (val * val) % MOD;
		y >>= 1;
	}
	return ans % MOD;
}

ll bin(int n, int r) {
	if (n == r || r == 0) return 1;
	if (r > n) return 0;
	return (dp[n] * ((modpow(dp[r],MOD- 2) * modpow(dp[n - r], MOD - 2)) % MOD)) % MOD;
}

