int powi(int a, int b, int mod){
    long long res = 1;
    long long x, y;
    y = 1;
    x = a % mod;
    while (y <= b){
        if ((b&y) == y){
            res *= x;
            res %= mod;
        }
        x *= x;
        y *= 2;
        x %= mod;
    }
    return res;
}

/*
* mod가 소수이고, div가 mod의 배수가 아니어야 함
*/
int get_mod_inverse(int div, int mod) {
    return powi(div, mod - 2, mod);
}

int cache[100005];
int factorial(int num)
{
    if(num <= 1)
        return 1;
    if(cache[num])
        return cache[num];
    return cache[num] = ((ll)factorial(num - 1) * num) % MOD;
}

