long long calc(int a, int p) {
	int p2 = p - 2;
	long long ret = 1;
	long long pows = a;
	for (int i = 0; i < 31; i++) {
		if ((p2 >> i) & 1) {
			ret = ret * pows % p;
		}
		pows = pows * pows % p;
	}
	return ret;
}

vector<long long> make_combs(int n) {
	vector<long long> comb(n + 1, 1);

	for (int k = 1; k <= n; k++) {
		comb[k] = comb[k - 1] * (n + 1 - k) % mod * calc(k, mod) % mod;
	}

	return comb;
}

