    Mod_comb(int n, long long m) : mod_(m), n_(n), fac(n), rev(n)
    {
        fac.resize(n_+1);
        rev.resize(n_+1);
        fac[0] = 1;
        for(int i=1;i<=n_;++i)
        {
            fac[i]=(fac[i-1]*i)%mod_;
        }
        rev[n_]=qpow(fac[n_],mod_-2);
        for(int i=n_-1;i>=0;--i)
        {
            rev[i]=(rev[i+1]*(i+1))%mod_;
        }
    }

    long long C(int n,int m)
    {
        if(m>n)
        {
            return 0;
        }
        return (((fac[n]*rev[m])%mod_)*rev[n-m])%mod_;
    }
};

