int perm(int n, int r) {
	if (n < 0 || r < 0 || n < r) return 0;
	return kai[n] * modinv(kai[n - r], MOD) % MOD;
}

int comb(int n, int r) {
	if (n < 0 || r < 0 || n < r) return 0;
	return perm(n, r) * modinv(kai[r], MOD) % MOD;
}

