struct Combination{
    const int MAX = 500050;
    vector<mint> fact;
    Combination(){
        fact.resize(MAX);
        for(int i = 0;i < MAX;i++){
            if(i == 0)fact[i] = (mint)1;
            else fact[i] = fact[i-1]*(mint)i;
        }
    }
    mint comb(int n,int r){
        if(n<0||r<0||n<r)return 0;
        else return fact[n]*fact[r].inv()*fact[n-r].inv();
    }
};


