int n,a[maxn],been[maxn],x1,x2;
ll ans[maxn],inv[maxn],fact[maxn];

ll pw(int a,int n) {
    if (n==0) return 1ll;
    if (n==1) return a;
    ll tmp = pw(a,n/2);
    tmp = (tmp*tmp)%base;
    if (n%2==0) return tmp;
    return (tmp*a)%base;
}

ll C(int k,int n) {
    //cout<<fact[n]<<endl;
    return fact[n]*inv[k]%base*inv[n-k]%base;
}

int main() {
