// Extended Euclidean algorithm
int xGCD(int a, int b, ll &x, ll &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }

    ll x1, y1, gcd = xGCD(b, a % b, x1, y1);
    x = y1;
    y = x1 - (long long)(a / b) * y1;
    return gcd;
}


// multiply a and b modulo MOD
int modmult(int a, int b) {
    return ((long long)a * b) % MOD;
}

