	b = p2 - p1 - 1;
	c = n - (a + b + 2);

	ans[1] = n - 1;

	fact[0] = 1;
	invfact[0] = 1;
	FORN (i, 1, 2 * n + 1) {
		fact[i] = (1LL * fact[i - 1] * i) % MOD;
		invfact[i] = pkt(fact[i], MOD - 2);
	}

	FORN (i, 2, n) {
		ans[i] = C(n, i);
		add(ans[i], -C(a + c, i - 1));
	}

	FORN (i, 1, n) {
		cout << ans[i] << "\n";
	}
}

