int pw(int a, int b) {
	int res = 1;
	for (int i = 0; (1LL << i) <= b; ++i) {
		if (b & (1LL << i)) res = 1LL * res * a % md;
		a = 1LL * a * a % md;
	}
	return res;
}

int nCk(int n, int k) {
	if (n < 0 || k < 0 || n < k) return 0;
	return 1LL * f[n] * (1LL * pw(f[k], md - 2) * pw(f[n - k], md - 2) % md) % md;
}

