    if (a[ai] >= 0) {
      a1 = a[ai];
      a2 = i;
      break;
    }
    a[ai] = i;
  }
  for (u64 i = 1; i <= n+1; ++i) {
    u64 up = comb.comb(n+1, i);
    u64 dn = comb.comb(n-(a2-a1), i-1);
    if (up>dn) {
      cout << (up-dn)%(1000000007) << endl;
    }
    else {
      cout << (up+1000000007-dn)%(1000000007) << endl;
    }
  }
