ll inv(ll x, ll n) {
  ll sum = 1;
  while (n > 0) {
    if ((n & 1L) == 1L) {
      sum = (sum * x) % MOD;
    }
    x = (x * x) % MOD;
    n = n >> 1L;
  }
  return sum;
}

