	combi C(100001);

	vector<pair<int, int>>b(n + 1);
	rep(i, n + 1)b[i] = make_pair(a[i], i);
	sort(ALL(b));
	int d1, d2;
	rep(i, n)if (b[i].first == b[i + 1].first) {
		d1 = b[i].second;
		d2 = b[i + 1].second;
	}

	cout << n << endl;

	for (int k = 2; k <= n; k++) {
		modint ans = 0;

		//d1とd2を両方選ぶ:Combination(n-1,k-2)
		if (n - 1 - (k - 2) >= 0)ans += C.get_combi(n-1-(k-2),k-2);

		//d1を選ぶがd2を選ばない:Combination(n-1,k-1)
		if (n - 1 - (k - 1) >= 0)ans += C.get_combi(n - 1 - (k - 1), k - 1);

		//d2を選ぶがd1を選ばない:Combination(n-1,k-1)
		if (n - 1 - (k - 1) >= 0)ans += C.get_combi(n - 1 - (k - 1), k - 1);

		//d1もd2も選ばない:Combination(n-1,k)
		if(n - 1 - (k) >= 0)ans += C.get_combi(n - 1 - (k), k);

		//包除原理
		int L = d1;
		int R = n - d2;
		if (L + R - (k - 1) >= 0)ans -= C.get_combi(L+R - (k - 1), k - 1);
		cout << ans.get() << endl;
	}

	cout << 1 << endl;



	return 0;
}

