struct Combination_1D {
    vector<ll> nCk;
    ll operator [](const size_t i) { return nCk[i]; }
    void init(const int n) {
        vector<ll> fact(n + 1);
        fact[0] = 1;
        for (int i = 0; i < n; ++i) {
            fact[i + 1] = fact[i] * (i + 1) % MOD;
        }
        vector<ll> ifact(n + 1);
        ifact[n] = modulo_pow(fact[n], MOD - 2);
        for (int i = n; i > 0; --i) {
            ifact[i - 1] = ifact[i] * i % MOD;
        }
        nCk.resize(n + 1);
        for (int i = 0; i <= n; ++i) {
            nCk[i] = fact[n] * ifact[n - i] % MOD * ifact[i] % MOD;
        }
    }
};

