ll EX_GCD(ll a, ll b, ll& x, ll& y) {
	ll d = a;
	if (b != 0) {
		d = EX_GCD(b, a % b, y, x);
		y -= (a / b) * x;
	}
	else {
		x = 1;
		y = 0;
	}
	return d;
}

ll Inverse(ll a, ll mo = 1e9 + 7) {
	ll x, y;
	if (EX_GCD(a, mo, x, y) != 1) return -1;
	return x >= 0 ? x % mo : x % mo + mo;
}

class mint {
	ll val;
public:
	static const ll mod = 1e9 + 7;
public:
	mint() : val(0) {}
	mint(ll v) : val(v % mod) {}
	operator int() { return (int)val; }
	operator ll() { return val; }
	mint inv() { ll res = Inverse(val, mod); assert(res != -1); return res; }
	mint operator+(mint v) { return val + v.val >= mod ? val + v.val - mod : val + v.val; }
	mint operator-(mint v) { return val < v.val ? val + mod - v.val : val - v.val; }
	mint operator*(mint v) { return val * v.val % mod; }
	mint operator/(mint v) { return val * v.inv().val % mod; }
	mint& operator+=(mint v) { *this = *this + v; return *this; }
	mint& operator-=(mint v) { *this = *this - v; return *this; }
	mint& operator*=(mint v) { *this = *this * v; return *this; }
	mint& operator/=(mint v) { *this = *this / v; return *this; }
};
