const int md = 1e9 + 7;
inline void sub(int &a, int b) {
  a -= b;
  if (a < 0) a += md;
}
inline int mul(int a, int b) {
  return (int)((long long)a * b % md);
}
inline int inv(int a) {
  a %= md;
  if(a < 0) a += md;
  int b = md, u = 0, v = 1;
  while (a) {
    int t = b / a;
    b -= a * t; swap(a, b);
    u -= v * t; swap(u, v);
  }
  assert(b == 1);
  if(u < 0) u += md;
  return u;
}
vector<int> cmb (int n) {
  vector<int> ret(n + 1, 1);
  for (int i = 1; i <= n; i++) {
    ret[i] = mul(ret[i - 1], mul(n - i + 1, inv(i)));
  }
  return ret;
}
