// モジュラ逆数を求める(modが素数と仮定)
void ModInv(int n, vector<ll> &inv, int mod)
{
	inv[0] = 0;
	inv[1] = 1;
	for (int i = 2; i <= n; i++)
	{
		inv[i] = mod - ((mod / i) * inv[mod % i] % mod);
	}
}

// n!をmodで割った余り
void FacInv(int n, vector<ll> &inv, vector<ll> &fac, vector<ll> &facInv, int mod)
{
	fac[0] = facInv[0] = 1;
	for (int i = 1; i <= n; i++)
	{
		fac[i] = (fac[i - 1] * i) % mod;
		facInv[i] = (facInv[i - 1] * (int)inv[i]) % mod;
	}
}

// nCkをmodで割った余りを求める。mod素数限定
// ModInv()とFacInv()が必要
long CombiMod(int n, int k, int mod ,vll &fac, vll &facInv)
{
	if (n == 0 && k == 0) return 1;
	if (n <= 0 || k < 0 || k > n) return 0;
	if (k == 0) return 1;

	return (((fac[n] * facInv[k]) % mod) * facInv[n - k]) % mod;
}

int main() {
	int N;
