			p1 = pos[a[i]];
			p2 = i;
			break;
		}
		used.insert(a[i]);
		pos[a[i]] = i;
	}
	int x = p1;
	int y = p2 - p1 - 1;
	int z = N + 1 - x - y - 2;

	repl(k, 1, N + 2) {
		cout << CombiMod(N + 1, k, MOD, fac, facInv) - CombiMod(x + z, k - 1, MOD, fac, facInv) << endl;
	}

	return 0;
}

