int powmod(int n, int x, int mod){
  if (x == 0){
    return 1;
  } else {
    int tmp = powmod(n, x / 2, mod);
    tmp = (ll) tmp * tmp % mod;
    if (x % 2 == 1){tmp = (ll) tmp * n % mod;}
    return tmp;
  }
}

int invmod(int n, int p){
  assert(0 < n % p);
  return powmod(n, p - 2, p);
}

