long long power(long long a, int x) {
    long long res = a;
    int cnt = 0;
    long long p = 1;
    while ((p << 1) <= x) p <<= 1, ++cnt;
    for(int i = cnt; i > 0; --i) {
        res = (res * res) % oo;
        if (getbit(x, i - 1) == 1) res = (res * a) % oo;
    }
    return res;
}

long long C(int n, int k) {
    if (k > n) return 0;
    long long tmp = (inverse[k] * inverse[n - k]) % oo;
    return (fact[n] * tmp) % oo;
}

