  fac[0] = 1;
  rep(i, maxn - 2) fac[i + 1] = (fac[i] * (i + 1)) % rem;
  rep(i, maxn - 1) rfac[i] = ppow(fac[i], rem - 2);
}

llong c(int n, int k) {
  llong u = fac[n];
  llong v = rfac[k] * rfac[n - k] % rem;
