int64_t quickPow(int64_t a, int64_t b) {
    if(b == 0)
        return 1;

    int64_t ans = quickPow(a, b / 2);
    ans = (ans * ans) % MOD;
    if(b % 2 == 1)
        ans = (ans * a) % MOD;

    return ans;
}

void preCal() {
    fact[0] = 1;
    rfact[0] = quickPow(fact[0], MOD - 2);
    for(int i = 1; i < maxN; i++) {
        fact[i] = (fact[i - 1] * i) % MOD;
        rfact[i] = quickPow(fact[i], MOD - 2);
    }
}

int64_t nCk(int n, int k) {
    if(n < k)
        return 0;
    return (((fact[n] * rfact[k]) % MOD) * rfact[n - k]) % MOD;
}

