using namespace std;
typedef long long ll;

const ll MOD = 1000000007;

ll modt[100001], imodt[100001];

int n, in[100001];
int samel, samer;

ll modpow(ll a, ll b) {
	ll x = 1,times = a;
	while (b > 0) {
		if (b & 1)x *= times;
		times *= times;
		x %= MOD;
		times %= MOD;
		b >>= 1;
	}
	return x;
}

ll comb(ll n, ll r) {
	if (r > n)return 0;
	if (n < 0 || r < 0)return 0;
	//cout << n << " " << r << endl;
	ll ans = modt[n];
	ans = ans * imodt[r] % MOD;
	ans = ans * imodt[n - r] % MOD;
	return ans;
}

