#define DIV 1000000007

long long modpow(long long ori, long long po){
	long long res = 1;
	while(po > 0){
		if(po&1){
			res *= ori;
			res %= DIV;
		}
		ori *= ori;
		ori %= DIV;
		po >>= 1;
	}
	return res;
}

void pre(){
	memo[0] = 1;
	memo[1] = 1;
	for(long long i = 1; i < 100003; i++){
		memo[i+1] = memo[i] * (i+1);
		memo[i+1] %= DIV;
	}
}

map<pair<long long, long long>, long long > mm;
long long comb(long long A, long long B){
	if(A < B){
		return 0;
	}

	if(mm.count(make_pair(A, B)) != 0){
		return mm[make_pair(A, B)];
	}

	long long ans = memo[B] * memo[A-B];
	ans %= DIV;
	ans = memo[A] * modpow(ans, DIV - 2);
	ans %= DIV;
	mm[make_pair(A, B)] = ans;
	return ans;
}

long long cal(long long num){
	long long ans;
	ans = comb(n + 1, num);
	ans %= DIV;

	for(long long i = 0; i < num; i++){
		long long tmp;
		tmp = comb(pos1, i) * comb(n - pos2, num - 1 - i);
		tmp %= DIV;
		ans -= tmp;
		ans += DIV;
		ans %= DIV;
	}

	return ans;
}

