LL fastpow(LL base, LL p, LL mod) {
    LL ans = 1;
    while (p > 0) {
        if (p % 2 == 1) {
            ans = (ans * base) % mod;
        }
        base = (base * base) % mod;
        p /= 2;
    }
    return ans;
}

