ll md = 1e9+7;

ll mexp(ll a, ll e){
	ll res = 1;
	for(; e; e /= 2){
		if(e & 1) res = res * a % md;
		a = a*a%md;
	}
	return res;
}

ll inv(ll a){
	return mexp(a, md-2);
}

