ll combmod(ll all, ll select){
    if(select == 0)     return 1;
    if(all == select)   return 1;
    if(all == 0)        return 0;
    if(all < select)    return 0;

    ll a = powmemo[all];
    ll b = powmemo[select]*powmemo[all-select] % mod;

