typedef long long LL;

static const int MOD = 1000000007;
static const int MAXN = 200000 + 10;

LL factor[MAXN];



LL power(int base, int n) {
    LL ret = 1;
    LL cur = base;
    while (n) {
        if (n & 1) {
            ret *= cur;
            if (ret >= MOD) ret = ret % MOD;
        }
        cur = cur*cur;
        if (cur >= MOD) cur = cur % MOD;
        n = n >> 1;
    }
    return ret;
}

LL combine(int n, int k) {
    if (k < 0 || n < k) return 0;
    if (k== 0) return 1;
    LL ret = factor[n];
    ret = ret * (power(factor[k],MOD-2));
    if (ret >= MOD) ret = ret % MOD;
    ret = ret * (power(factor[n-k], MOD-2));
    if (ret >= MOD) ret = ret % MOD;
    return ret;


}

LL compute(int n, int k, int d) {
    LL ret = combine(n+1, k);
    ret = ret - combine(n+1-2-d, k-1);
    if (ret < 0) ret += MOD;
    return ret;

}



