int n, x, d, dd[N], prod[N];

int pw(int x, int y){
    if (y == 0) return 1;
    int res = pw(x, y / 2);
    if (y & 1)
        return (1LL * ((1LL * res * res) % MOD) * x) % MOD;
    return (1LL * res * res) % MOD;
}

int C(int k, int n){
    if (k > n) return 0;
    int nk = (1LL * prod[k] * prod[n - k]) % MOD;
    return (1LL * prod[n] * pw(nk, MOD - 2)) % MOD;
}

inline int calc(int k){
    return C(k, n + 1) - C(k - 1, n + 1 - d);
}

