pll egcd(ll a, ll b) {
        if (a > b) {
                pll p = egcd(b,a);
                return pll(p.second,p.first);
        }

        ll s0=1,s1=0,s2=a;
        ll t0=0,t1=1,t2=b;
        while (t2 != 0) {
                ll q = s2/t2;
                ll r0=t0,r1=t1,r2=t2;
                t0=s0-q*t0,t1=s1-q*t1,t2=s2-q*t2;
                s0=r0,s1=r1,s2=r2;
        }

        return pll(s0,s1);
}

ll mod_inv(ll a, ll m) {
        pll p = egcd(a%m, m);
        return (p.first%m+m)%m;
}


