ll C(ll n,ll m){//n!/((n-m)i*mi)
	if(m>n)
	return 0;
	if(m==0)
	return 1;
	ll a,b;
	a=jc[n];
	b=jc[n-m]*jc[m];
	b%=md;
	ll ny=qmod(b,md-2);
	ll ans=(a*ny)%md;
	return ans;
}
