int extgcd(int a, int b, int& x, int &y) {
    if (b == 0) { x = 1; y = 0; return a; }
    else {
        int g = extgcd(b, a%b, y, x);
        y -= a / b * x;
        return g;
    }
}

int mod_inv(int a, int m) {
    int x, y;
    extgcd(a, m, x, y);
    return x;
}

