            double_number = i;
        }
    }
    long space_length = 0;
    for(int i = n; i >= 0; i--){
        if(nums[i] == double_number + 1){
            space_length = i;
            break;
        }
    }
    for(int i = 0; i <= n; i++){
        if(nums[i] == double_number + 1){
            space_length -= i;
