    for (int i = 0; i <= n; i++) {
        cin >> arr[i];
        frq[arr[i]]++;

        if (frq[arr[i]] == 2) {
            for (int j = 0; j < i; j++)
                if (arr[j] == arr[i]) {
                    ind1 = j + 1;
                    break;
                }
            ind2 = i + 1;
        }
    }

    for (int i = 1; i <= n + 1; i++) {
        int all = choose(n + 1, i);

        if (i - 1 <= n + 1 - ind2)
            all = sub(all, choose(n + 1 - ind2, i - 1));
        if (i == 2)
            all = sub(all, ind1 - 1);
        else if (i > 2) {
            all = sub(all, (1ll * (ind1 - 1) * choose(n + 1 - ind2, i - 2) % mod));
        }

        cout << all << "\n";
    }

