void inv_table() {
  iv[1] = 1;
  rep(i,2,MAX_N)
  {
    iv[i] = ((MOD - MOD / i) * iv[MOD % i]) % MOD;
  }
}

ll inv(ll x, ll n) {
  ll sum = 1;
  while (n > 0) {
    if ((n & 1L) == 1L) {
      sum = (sum * x) % MOD;
    }
    x = (x * x) % MOD;
    n = n >> 1;
  }
  return sum;
}

void factorial() {
  invn = inv(n, MOD - 2);
  fact[0] = 1;
  REP(k,1,n+1)
  {
    fact[k] = (fact[k - 1] * k) % MOD;
  }
  ifact[0] = 1;
  REP(k,1,n+1)
  {
    ifact[k] = (ifact[k - 1] * iv[k]) % MOD;
  }
}

ll nCr(ll n, ll r) {
  if (n < r || r < 0 || n < 0) {
    return 0;
  }
  if (r > n / 2) {
    r = n - r;
  }
  return (((fact[n] * ifact[n - r]) % MOD) * ifact[r]) % MOD;
}

