long long int power(int base, long long int exp, long long int mod = MOD)
{
	if (exp == 0)
	{
		return 1;
	}
	else
	{
		long long int ans;

		if (exp % 2)
		{
			ans = base*power(base, exp - 1, mod);
		}
		else
		{
			ans = power(base, exp/2, mod);
			ans *= ans;
		}

		if (ans >= mod)
		{
			ans %= mod;
		}

		return ans;
	}
}

