//modあり
ll pow_mod(ll x, ll n) {
	ll ret;
	if (!n) ret = 1;
	else if (!(n % 2)) ret = pow_mod(x * x % MOD, n / 2);
	else if (n & 1) ret = pow_mod(x * x % MOD, n / 2) * x % MOD;
	return ret;
}

ll factorial_mod(ll n) {
	ll ret = 1;
	while (n > 0) {
		ret *= n;
		ret %= MOD;
		n--;
	}
	return ret;
}

ll inverse_mod(ll x, ll p) {
	return pow_mod(x, p - 2) % MOD;
}

// nCr すなわち n! / ((n-r)! * r!)
ll C(ll n, ll r) {
	return factorial_mod(n) * inverse_mod(factorial_mod(n - r), MOD) % MOD * inverse_mod(factorial_mod(r), MOD) % MOD;
}

