using namespace std;
typedef pair<int,int> P;
ll mod(ll x){
	if(x>=modn) x-=(x/modn)*modn;
	if(x<0) x-=(x/modn)*modn, x+=modn;
	return x;
}
ll ext_gcd(ll x){
	ll ul=1, ur=0, ua=x, dl=0, dr=1, da=modn, mul;
	while(ua&&da){
		if(ua>da){
			mul = ua/da;
			ul-=dl*mul, ur-=dr*mul, ua-=da*mul;
		} else {
			mul = da/ua;
			dl-=ul*mul, dr-=ur*mul, da-=ua*mul;
		}
	}
	ll res = ua?ul:dl;
	return mod(res);
}
ll n,r;
