		if(apr[arr[i]]){
			r = n-i;
		}
		apr[arr[i]] = true;
	}
	ans.PB(n);
	ll tta = n+1, ttb = 1;
	for(ll i=1;i<=n;++i){
		tta = mod(mod( tta * (n+1-i) ) * ext_gcd(i+1) );
		ttb = mod(mod( ttb * (r-i+1) ) * ext_gcd(i) );
		ans.PB( mod(tta + (modn-ttb) ) );
	}
	for(auto it:ans) printf("%lld\n",it);
}

