template <i64 mod> struct m32 {
    i64 raw;
    m32() : raw(0) {}
    m32(unsigned x) : raw(x % mod) {}
    m32(signed x) { i32 t = x % mod; if (t < 0) t += mod; raw = t; }
    m32(signed long long x) { i32 t = x % mod; if (t < 0) t += mod; raw = t; }
    i32 value() const { return (i32)raw; }
    m32 &operator+=(m32 that) { if ((raw += that.raw) >= mod) raw -= mod; return *this; }
    m32 &operator-=(m32 that) { if ((raw += mod - that.raw) >= mod) raw -= mod; return *this; }
    m32 &operator*=(m32 that) { raw = (u64)raw * that.raw % mod; return *this; }
    m32 operator+(m32 that) const { return m32(*this) += that; }
    m32 operator-(m32 that) const { return m32(*this) -= that; }
    m32 operator*(m32 that) const { return m32(*this) *= that; }
};

vec<i64> facts;
template <typename T> void initfacts(T n, T m) {
    facts = vec<i64>(n+1); facts[0] = 0; facts[1] = 1;
    upto(2, n, i) { facts[i] = (facts[i-1] * i) % m; }
}

template <typename T> tuple<T, T, T> gcdext(T a, T b) {
    T s0 = 1, s1 = 0;
    T t0 = 0, t1 = 1;
    T q = 1;
    while (b != 0) {
        q = a / b;
        swap(a, b); b = b % a;
        swap(s0, s1); s1 = s1 - q*s0;
        swap(t0, t1); t1 = t1 - q*t0;
    }
    return a < 0 ? make_tuple(-a, -s0, -t0) : make_tuple(a, s0, t0);
}

template <typename T> T invmod(T n, T m) {
    auto gxy = gcdext(n, m);
    T g, x, y; tie(g, x, y) = gxy;
    if (g != 1 || m == 0) throw domain_error(NULL);
    return (x+m)%m;
}

template <typename T> T combmod(T n, T r, T m) {
    if (n<0 || r<0 || n<r) return 0;
    if (r == 0 || n == r) return 1;
    return ((facts[n]*invmod(facts[n-r], m) % m) * invmod(facts[r], m)) % m;
}

i32 c[100001];
