void solve() {
    indef(i32, n);

    initfacts((i64)n+1, MOD);

    i32 x;
    times(n+1, ai) {
        in(a[ai]);
        if (c[a[ai]]>0) x = ai;
        c[a[ai]]++;
    }
    i32 y;
    times(n+1, ai) {
        if (a[x] == a[ai]) {
            y = ai;
            break;
        }
    }
    upto(1, n+1, k) {
        m32<MOD> ans = combmod((i64)n+1, (i64)k, MOD);
        ans -= combmod((i64)n-(x-y), (i64)k-1, MOD);
        out(ans.raw);
    }
}

