struct Combination {
    vector<mint> fac, finv;
    int MAX;
    Combination(int _MAX) : MAX(_MAX), fac(_MAX), finv(_MAX) { init(); }
    void init() {
        fac[0] = fac[1] = finv[0] = finv[1] = 1;
        for(int i = 2; i < MAX; i++) {
            fac[i] = fac[i - 1] * mint(i);
            finv[i] = finv[i - 1] * mint(i).inverse();
        }
    }
    mint COM(int n, int k) {
        if(n < k || n < 0 || k < 0) {
            return 0;
        }
        return fac[n] * finv[k] * finv[n - k];
    }
};

