T pow_mod(T a, T n, T m){
	T r = 1;
	while(n){
		if(n & 1) (r *= a) %= m;
		(a *= a) %= m;
		n >>= 1;
	}
	return r;
}

template <typename T>
T nCr_mod(T n, T r, T m){
	if(n < r) return T(0);
	T ret = 1;
	for(T i = 2; i <= n; i++) (ret *= i) %= m;
	for(T i = 2; i <= r; i++) (ret *= pow_mod(i, m - 2, m)) %= m;
	for(T i = 2; i <= n - r; i++) (ret *= pow_mod(i, m - 2, m)) %= m;
	return ret;
}

