        inv[i] = -MOD / i * inv[MOD % i] % MOD + MOD;
        pinv[i] = pinv[i - 1] * inv[i] % MOD;
    }
}

ll C(int n, int m) {
    return n <= m ? (perm[m] * pinv[n] % MOD) * pinv[m - n] % MOD : 0;
}

