      ans=(ans+MOD)%MOD;
      cout << ans << endl;
    }
  }else{
    for(int k=2;k<=n;k++){
      ans=factorial[n]*gyaku[n-k]%MOD*gyaku[k]%MOD;
      ans=(ans+factorial[n-1]*gyaku[n-k+1]%MOD*gyaku[k-2]%MOD)%MOD;
