	void Init(int p,int L,int R){
		l[p]=L;
		r[p]=R;
		if(L!=R){
			int m=(L+R)>>1;
			Init((p<<1),L,m);
			Init(((p<<1)|1),m+1,R);
			arr[p]=arr[(p<<1)]*arr[((p<<1)|1)];
			arr[p]%=MOD;
		}
		else arr[p]=(LL)L;
