		}
		int m=(l[p]+r[p])>>1;
		LL ret=1;
		if(L<=m) ret=getv((p<<1),L,R);
		if(R>m) ret*=getv(((p<<1)|1),L,R);
		ret%=MOD;
		return ret;
	}
}segt;
LL multiply(LL val,int times){
	LL res=1;
	while(times){
		if(times&1) {
			res*=val;
			res%=MOD;
		}
		val*=val;
		val%=MOD;
		times>>=1;
	}
	return res;
}
LL GC(int N,int M){
	if(N<M) return 0;
	LL s1,s2,s3;
	s1=multiply(segt.getv(1,1,MIN(M,N-M)),(int)MOD-2);
	s2=multiply(segt.getv(1,MIN(M,N-M)+1,MAX(M,N-M)),(int)MOD-1);
	s3=multiply(segt.getv(1,MAX(M,N-M)+1,N),(int)MOD);
	s1*=s2;
	s1%=MOD;
	s1*=s3;
	s1%=MOD;
	return s1;
}
