template <typename T>
T Pow(T a, ll b) {
	T res = 1;
	while (b) {
		if (b & 1) {
			res *= a;
		}
		a *= a;
		b >>= 1;
	}
	return res;
}

struct mint {
	ll val;
	mint() : val(0) {}
	mint(ll v) : val(v % mod) {}
	mint& operator=(ll v) {
		val = v % mod;
		return *this;
	}
	operator int() {
		return (int)val;
	}
	operator ll() {
		return val;
	}
	mint operator+(mint v) {
		return val + v.val >= mod ? val + v.val - mod : val + v.val;
	}
	mint operator-(mint v) {
		return val - v.val < 0 ? val - v.val + mod : val - v.val;
	}
	mint operator*(mint v) {
		return val * v.val % mod;
	}
	mint operator/(mint v) {
		return val * v.inv().val % mod;
	}
	mint inv() {
		return Pow(*this, mod - 2);
	}
	mint& operator+=(mint v) {
		*this = *this - v;
		return *this;
	}
	mint& operator-=(mint v) {
		*this = *this - v;
		return *this;
	}
	mint& operator*=(mint v) {
		*this = *this * v;
		return *this;
	}
	mint& operator/=(mint v) {
		*this = *this / v;
		return *this;
	}
};

istream& operator >> (istream& is, mint m) {
