const int mod = 1000000007;
int combination(int n,int r) {
	if (n < r)return 0;
	if (r < 0)return 0;
	if (n == 0)return 1;
	if (n < 0)return 0;
	r = min(r, n - r);
	int res = 1;
	for (int i = 1; i <= r; ++i) {
		res *= (n - i + 1);
		res /= i;
		res %= mod;
	}
	return res;
}


