void pre() {
	rep(i,N+10) {
		L[i] = combination(l, i) % mod;
		C[i] = combination(c, i) % mod;
		R[i] = combination(r, i) % mod;
		LC[i] = combination(l + c, i) % mod;
		CR[i] = combination(c + r, i) % mod;
	}
}

int K(int k) {
	if (k == 1)return N;
	int res = 0;
	//2
	res += combination(N + 1 - 2, k - 2);
	res %= mod;
	//1
	for (int ll = 1; ll < k - 1; ++ll) {
		int rr = (k - 1) - ll;
		res += L[ll] * CR[rr]
			+ LC[ll] * R[rr]
			- L[ll] * R[rr];
		res %= mod;
	}
	res += LC[k - 1];
	res += CR[k - 1];
	res %= mod;
	//0
	res += combination(N + 1 - 2, k);
	res %= mod;
	return res;
}

