    for(int i = 0; i < N; i++){
        int a;
        cin >> a;
        if(pos[a] == -1)pos[a] = i;
        else{
            l = pos[a];
            r = i;
        }
    }
    int len = l + N - r - 1;
    for(int i = 1; i <= N; i++){
        ll ans = cmb.nCk(N, i);
        if(len >= i - 1){
            ll tmp  = cmb.nCk(len, i - 1);
            ans -= tmp;
            if(ans < 0)ans += MOD;
            ans %= MOD;
        }
        cout << ans << endl;
    }

    return 0;
}

