long long mod_pow(long long x, long long n, int p) {
	if (n == 0)return 1;
	if (n == 1)return x%p;

	long long y = mod_pow(x,n/2,p);

	if (n % 2 == 0)return (y*y) % p;
	else return (x*((y*y) % p))%p;
}

vector<long long>factor;
vector<long long>rfactor;
void Factorial(vector<long long>&vec, int n, int p) {
	vec.assign(n+1,0);
	vec[0] = 1;
	for (int i = 1; i <= n; i++) {
		vec[i] = vec[i - 1] * i;
		vec[i] %= p;
	}
}
void rFactorial(vector<long long>&vec, int n, int p, int n_fac) {
	vec.assign(n + 1, 0);
	vec[n] = mod_pow(n_fac,p-2,p);
	for (int i = 1; i <= n; i++) {
		vec[n-i] = vec[n-i+1]*(n-i+1);
		vec[n-i] %= p;
	}
}

void nCr_ready(int n, int p) {
	Factorial(factor, n, p);
	long long n_fac = factor[n];
	rFactorial(rfactor, n, p, n_fac);
}

long long nCr(int n, int r, int p) {
	if (n < r)return 0;
	long long n_fac = factor[n];
	long long r_fac = rfactor[r];
	long long n_r_fac = rfactor[n - r];

	long long ans = 1;
	ans *= n_fac;
	ans %= p;
	ans *= r_fac;
	ans %= p;
	ans *= n_r_fac;
	ans %= p;

	return ans;
}

