int main()
{
	cin.tie( 0 );
	ios::sync_with_stdio( false );
	cout << setprecision( 12 ) << fixed;

	IN( int, N );
	VI A( N + 1 );
	cin >> A;

	int L, R, D;
	{
		VI counts( N + 1 );
		for_each( ALL( A ), [&]( const int a ){ ++counts[a]; } );
		const int doubled = find( ALL( counts ), 2 ) - begin( counts );
		const auto it1 = find( ALL( A ), doubled );
		const auto it2 = find( A.rbegin(), A.rend(), doubled ).base() - 1;

		L = it1 - begin( A );
		R = it2 - begin( A );
		D = R - L - 1;
	}

	REP( i, 1, N + 2 )
	{
		int res = 0;

		// 0 doubled
		( res += nCr( N - 1, i ) ) %= MOD;

		// 2 doubled
		if ( 2 <= i )
		{
			( res += nCr( N - 1, i - 2 ) ) %= MOD;
		}

		// 1 douled
		if ( i == 1 )
		{
			( ++res ) %= MOD;
		}
		else
		{
			( res += nCr( N - 1, i - 1 ) * 2 ) %= MOD;
			// minus equlvalent subseqs
			if ( i - 1 <= N - 1 - D )
			{
				// outsider only
				( res -= nCr( N - 1 - D, i - 1 ) ) %= MOD;
				( res += MOD ) %= MOD;
				// minus equlvalent subseqs
			}
		}

		cout << res << endl;
	}

	return 0;
}

