ll C_n[MAXN];
ll C_n_f_s[MAXN];

void gener(ll n, ll f, ll s)
{
	C_n[0] = 1;
	C_n[1] = n + 1;

	FOR(i, 1, n + 1)
	{
		C_n[i+1] = C_n[i] * (n + 1 - i) % mod;
		C_n[i+1] *= power(i + 1, mod - 2);
		C_n[i+1] %= mod;
	}

	C_n_f_s[0] = 1;
	C_n_f_s[1] = n + f - s;

	FOR(i, 1, n + f - s + 1)
	{
		C_n_f_s[i+1] = C_n_f_s[i] * (n + f - s - i) % mod;
		C_n_f_s[i+1] *= power(i + 1, mod - 2);
		C_n_f_s[i+1] %= mod;
	}
}


