ll n, a[100010], l, r, fact[100010], invfact[100010], mod = 1e9+7, ans;

ll modinv(ll a, ll m){
	ll b = m, u = 1, v = 0;
	while(b){
		ll t = a / b;
		a -= t * b; swap(a, b);
		u -= t * v; swap(u, v);
	}
	u %= m;
	if(u < 0) u += m;
	return u;
}

ll comb(ll n, ll r){
	if(n == 0 && r == 0) return 1;
	if(n == 0 || n < r) return 0;
//	cout << n << " " << r << "\n";
	ll res = fact[n];
	res *= invfact[r];
	res %= mod;
	res *= invfact[n-r];
	res %= mod;
	return res;
}

