				ll = i;
			else
				rr = i;
		}
	}
	printf("%d\n", n);
	for(i=2; i<=n; i++){
		res = 0;
		res += calcC(n-1, i);
		res += calcC(n-1, i-1);
		res %= D;
		res += calcC(n-1, i-1);
		res %= D;
		res += D;
		res -= calcC(n+1-(rr-ll+1), i-1);
		res %= D;
		res += calcC(n-1, i-2);
		res %= D;
		printf("%lld\n", res);
	}
	printf("%d\n", 1);
}

