int mul(int a, int b)
{
	return (1LL * a * b) % MOD;
}

int pow(int x, int n)
{
	if (n == 0) {
		return 1;
	}
	else if (n % 2 == 0) {
		int t = pow(x, n / 2);
		return mul(t, t);
	}
	else {
		return mul(x, pow(x, n - 1));
	}
}

vector<int> make_f(int n)
{
	vector<int> f(n + 1);
	f[0] = 1;
	for (int i = 1; i <= n; ++i) {
		f[i] = mul(f[i - 1], i);
	}
	return f;
}

vector<int> make_inv(const vector<int> &v)
{
	vector<int> a;
	for (auto x : v) {
		a.push_back(pow(x, MOD - 2));
	}
	return a;
}

