long modPow(long a, long x, long p) {
	long res = 1;
	while(x > 0) {
		if (x % 2 != 0) {
			res = (res * a) % p;
		}
		a = (a * a) % p;
		x /= 2;
	}
	return res;
}

long ncr(long n, long r) {
	if (r * 2 > n) {
		return ncr(n, n - r);
	}
	long p = 1;
	for (long i = n - r + 1; i <= n; i++) {
		p = (p * i) % MOD;
	}
	return (p * frid[r]) % MOD;
}

