  // determine the number X that appears twice and the number of elements
  // between them
  long indices[MAX_N + 1], c;
  for (long i = 0; i <= N; i++) {
    indices[i] = -1;
  }
  for (long i = 0; i < N + 1; i++) {
    const long a = as[i];
    if (indices[a] < 0) {
      indices[a] = i;
    } else {
      c = i - indices[a] - 1;
    }
  }

  // solve
  combination_init();
  for (int k = 1; k <= N + 1; k++) {
    long ans = 0;
    // include X twice
    if (k < 2) {
      ans = (ans + 0) % NUM_MOD;
    } else {
      ans = (ans + combination(N - 1, k - 2)) % NUM_MOD;
    }
    // include X once
    if (k < N + 1) {
      ans = (ans + 2 * combination(N - 1, k - 1) -
             combination(N - 1 - c, k - 1)) %
            NUM_MOD;
    } else {
      ans = (ans + 0) % NUM_MOD;
    }
    // don't include X
    if (k < N) {
      ans = (ans + combination(N - 1, k)) % NUM_MOD;
    } else {
      ans = (ans + 0) % NUM_MOD;
    }
    printf("%ld\n", ans);
  }

  return 0;
}

