long long power(long long a, long long p) {
    if (p == 0)
        return 1;
    if (p == 1)
        return a;

    long long half = power(a, p / 2) % MOD;
    if (p % 2 == 0) {
        return (half * half) % MOD;
    } else {
        return ((half * half) % MOD * a) % MOD;
    }
}

long long inv(long long x) {
    static long long memo[100001] = {0};
    if (memo[x] != 0)
        return memo[x];
    return memo[x] = power(x, MOD - 2);
}

long long comb(long long n, long long r) {
    if (r == 0)
        return 1;
    long long res = 1;
    rep(i, 0, r) {
        res = (res * (n - i)) % MOD;
    }
    irep(i, 1, r) {
        res = (res * inv(i)) % MOD;
    }
    return res;
}

