pair<int64_t, int64_t>
xgcd(const int64_t x0, const int64_t y0,
     const int64_t x1, const int64_t y1,
     const int64_t r0, const int64_t r1)
{
    const int64_t q  = r0 / r1;
    const int64_t r2 = r0 % r1;
    if(!(r1 % r2)) return {x0 - q * x1, y0 - q * y1};
    return xgcd(x1, y1, x0 - q * x1, y0 - q * y1, r1, r2);
}

inline pair<int64_t, int64_t>
xgcd(const int64_t a, const int64_t b) {
    return (a % b) ? xgcd(1, 0, 0, 1, a, b) : pair<int64_t, int64_t>(0, 1);
}

inline int64_t /* `a` should be prime w.r.t `mod` */
modinv(const int64_t a, const int64_t mod)
{
    static vector<int64_t> cache(1000000);

    if(a < (int64_t) cache.size())
    {
        if(!cache[a]) cache[a] = (mod + xgcd(a, mod).first % mod) % mod;
        return cache[a];
    }

    return (mod + xgcd(a, mod).first % mod) % mod;
}

