long long fact2(long long a, long n){
	if(n == 0){
		return 1;
	}else if(n%2 == 1){
		return (fact2(a,n-1)*a)%1000000007;
	}else{
		long long b = fact2(a,n/2);
		return (b*b)%1000000007;
	}
}

