int fast_pow(int x, int n) {
  if (n == 0) {
    return 1;
  }
  if (n % 2 == 0) {
    int y = fast_pow(x, n / 2);
    return y * 1LL * y % mod;
  }
  return fast_pow(x, n - 1) * 1LL * x % mod;
}

