LL find(LL x)  
{  
    LL k=Mod-2,ans=1;  
    while(k)  
    {  
        if (k&1) 
            ans=ans*x%Mod;  
        x=x*x%Mod;  
        k>>=1;  
    }  
    return ans;  
} 
LL factorial[Maxn];  
void init(LL p)  
{  
    factorial[0] = 1;  
    for(int i = 1;i <= p;i++)  
        factorial[i] = factorial[i-1]*i%Mod;  
}  
LL Lucas(LL a,LL k,LL p) //求C(n,m)%p p最大为10^5。a,b可以很大！  
{  
    LL re = 1; 
    if(a==0&&k==0)
    	return 1;
    else if(a==0)
    	return 0; 
    while(a && k)  
    {  
        LL aa = a%p;
        LL bb = k%p;  
        if(aa < bb) return 0; //这个是最后的改动！  
        re = re*factorial[aa]*find(factorial[bb]*factorial[aa-bb]%p)%p;//这儿的求逆不可先处理  
        a /= p;  
        k /= p;  
    }  
    return re;  
}  
