		res %= D;
		res += calcC(n-1, i-1);
		res %= D;
		res += D;
		res -= calcC(n+1-(rr-ll+1), i-1);
		res %= D;
		res += calcC(n-1, i-2);
		res %= D;
		printf("%lld\n", res);
	}
	printf("%d\n", 1);
}

