	fac[0]=1;
	for(int i=1;i<=n;++i)
		fac[i]=(long long)fac[i-1]*i%P;
	fac_inv[n]=1;
	for(int i=P-2,tmp=fac[n];i;i>>=1,tmp=(long long)tmp*tmp%P){
		if(i&1) fac_inv[n]=(long long)fac_inv[n]*tmp%P;
	}
