//高速に累乗を計算
long long fastpow(long long base, long long e){
    long long ans = 1;
    for(long long p = base; e; e >>= 1, p = (p * p) % 1000000007){
        if(e & 1) ans = (ans * p) % 1000000007;
    }
    return ans;
}
//Cの計算
long long binom(long long a, long long b){
    long long ans = 1;
    for(int i = 0; i < b; ++i){
        ans *= (a-i);
        ans %= 1000000007;
        ans *= fastpow(b-i, 1000000005);
        ans %= 1000000007;
    }
    return ans;
}
int main(){
