  FOR(k,1,n+2){
    ll ret = binom(n+1, k);
    if(k == 1) ret -= 1;
    if(right >= k - 1 && k - 1 > 0) ret -= binom(right, k - 1);
    if(right >= k - 2 && k - 2 > 0) ret -= binom(right, k - 2);
