typedef long long ll;
ll mod=1000000007;
ll gyaku(ll n){
  ll i=mod-2;
  ll ret=1;
  ll now=n;
  while(i>0){
    if(i%2==1){
      ret*=now;
      ret%=mod;
    }
    now=now*now;
    now%=mod;
    i/=2;
  }
  return ret;
}
ll nck(ll n,ll k){
  if(k>n)return 0;
  if(2*k>n)k=n-k;
  ll ret=1;
  for(ll i=0;i<k;i++){
    ret*=n-i;
    ret%=mod;
    ret*=gyaku(i+1);
    ret%=mod;
  }
  return ret;
}
