            incr *= perm_invs[k-2]; incr %= MOD;
            incr *= perm_invs[n-1-(k-2)]; incr %= MOD;
            ans += incr; ans %= MOD;
            debug_printf("dup2 incr=%lld\n", incr);
        }

        // dup 1 (dupcount)
        if (len1+len3 >= k-1) {
            incr = 1LL;
            incr *= perms[len1+len3]; incr %= MOD;
            incr *= perm_invs[k-1]; incr %= MOD;
            incr *= perm_invs[len1+len3-(k-1)]; incr %= MOD;
            ans += incr; ans %= MOD;
            debug_printf("dup1-dup incr=%lld\n", incr);
        }

        // dup 1 (not dupcount)
        if (n-1 >= k-1) {
            incr = 1LL;
            incr *= perms[n-1]; incr %= MOD;
            incr *= perm_invs[k-1]; incr %= MOD;
            incr *= perm_invs[n-1-(k-1)]; incr %= MOD;

