typedef long long ll;
const int N = 100000 + 5;
const int MOD = (int)1e9 + 7;
ll F[N], Finv[N], inv[N];//F是阶乘，Finv是逆元的阶乘

void init() {
	inv[1] = 1;
	for(int i = 2; i < N; i ++) {
		inv[i] = (MOD - MOD / i) * 1ll * inv[MOD % i] % MOD;
	}
	F[0] = Finv[0] = 1;
	for(int i = 1; i < N; i ++) {
		F[i] = F[i-1] * 1ll * i % MOD;
		Finv[i] = Finv[i-1] * 1ll * inv[i] % MOD;
	}
}

ll C(ll n, ll m) {
	if(m < 0 || m > n) return 0;
	return F[n] * 1ll * Finv[n - m] % MOD * Finv[m] % MOD;
}

int num[N], vis[N];

int main(){
	init();
	int n;
	memset(vis, 0, sizeof(vis));
	while(~scanf("%d", &n)) {
		int res, suf;
		for(int i=1; i<=n+1; ++i) {
			scanf("%d", num + i);
			if(vis[num[i]]) suf = i;
			else vis[num[i]] = 1;
		}
		for(int i=1; i<=n+1; ++i) {
			if(num[i] == num[suf]){
