ll gcd(ll a,ll b,ll &x,ll &y)
{
    if(b==0)
    {
        x=1;y=0;
        return a;
    }
    else
    {
        ll g=gcd(b,a%b,x,y);
        ll x1=x,y1=y;
        x=y1;
        y=x1-(a/b)*y1;
        return g;
    }
}
ll inv(ll a,ll b)
{
    ll x,y;
    ll g=gcd(a,b,x,y);
    assert(g==1);
    return (x%b+b)%b;
}
