#define mod 1000000007

long long int fact[100001];
long long int revfact[100001];

int n;

void getfact()
{
	fact[0] = 1;
	fact[1] = 1;
	for(int i = 2; i <= n + 1; i++){
		fact[i] = (i * fact[i - 1]) % mod;
	}
	return;
}

void getrevfact()
{
	for(int i = 0; i <= n + 1; i++){
		long long int tmp[31];
		tmp[0] = fact[i];
		for(int j = 1; j < 31; j++){
			tmp[j] = (tmp[j - 1] * tmp[j - 1]) % mod;
		}
		int now = mod - 2;
		revfact[i] = 1;
		for(int j = 30; j >= 0; j--){
			int t = (int)pow(2, j);
			if(now >= t){
				now -= t;
				revfact[i] = (revfact[i] * tmp[j]) % mod;
			}
		}
	}
	return;
}

long long int getcomb(int n, int r)
{
	if(r > n) return 1;
	// cout << n << " " << r << " " << (fact[n] * ((revfact[r] * revfact[n - r]) % mod)) % mod << endl;
	return (fact[n] * ((revfact[r] * revfact[n - r]) % mod)) % mod;
}

