void init()
{
    fac[0] = fac[1] = inv[0] = inv[1] = facinv[0] = facinv[1] = 1;
    for(int i = 2; i <= 100005; ++i)
    {
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = inv[MOD % i] * (MOD - MOD / i) % MOD;
        facinv[i] = facinv[i - 1] * inv[i] % MOD;
    }
}

LL C(LL n, LL m)
{
    if(n < 0 || m < 0 || m > n) return 0;
    return fac[n] * facinv[m] % MOD * facinv[n-m] % MOD;
}

