ll modpow(ll a, ll b) {
	ll x = 1,times = a;
	while (b > 0) {
		if (b & 1)x *= times;
		times *= times;
		x %= MOD;
		times %= MOD;
		b >>= 1;
	}
	return x;
}

ll comb(ll n, ll r) {
	if (r > n)return 0;
	//cout << n << " " << r << endl;
	ll ans = modt[n];
	ans = (ans * imodt[r]) % MOD;
	ans = (ans * imodt[n - r]) % MOD;
	return ans;
}

