using namespace std;

long long comb(long long n, long long k){
  long long res = 1;
  long long denom = 1;
  if (n<k||k<0) {
    return(0);
  }
  if (n==k||k==0) {
    return(1);
  }
  for (int i=0;i<k;i++) {
    res *= n - i;
  }
  for (int i=1;i<=k;i++) {
    denom *= i;
  }

  return(res/denom);
}

long long all_comb(long long n){
  long long sum = 0;
  long long res = n;
  long long denom = 1;
  for (int i=1;i<=n;i++) {
    sum += res/denom;
    res *= n-i;
    denom *= i+1;
  }
  return(sum);
}

long long comb_update(long long x, int n, int i) {
  if (n<i||i<0)
    return(0);
  if (n==i||i==0)
    return(1);
  if (x > 0) {
    return(x * (n-i+1) / (i));
  } else {
    return((n-i+1) / (i));
  }
}

