/*
 * power function
 * @return a^b % mod
 * more details in https://telegram.me/dore_com/174
 */
int power(ll a, int b, ll mod = m)
{
	if (b == 0)
		return 1%mod;
	ll p = power(a%mod, b>>1);
	p *= p;
	p %= mod;
	if (b & 1) {
		p *= a;
		p %= mod;
	}
	return p;
}

