ll fexp(ll b, ll e) {
	if (e == 0) return 1;
	if (e == 1) return b;
	ll tmp = fexp(b, e / 2);
	return tmp * tmp % MOD * fexp(b, e % 2) % MOD;
}

vector<ll> cal_comb(ll n, ll k) {
	vector<ll> ret;
	ret.push_back(1);
	ll init = 1;
	ll deno = 1;
	for (ll i = 1; i <= k; ++i) {
		init = init * (n - i + 1) % MOD;
		deno = deno * i % MOD;
		ret.push_back(init*fexp(deno, MOD - 2) % MOD);
	}
	return ret;
}


