ll pw(ll v1, ll v2, ll mod = 1000000007) {
	ll v3 = 1;
	for (; v2 != 0; v1 = (v1 * v1) % mod, v2 = (v2 >> 1))
		if (v2 & 1)v3 = (v3 * v1) % mod;
	return v3;
}

