ll cmb(ll v1, ll v2) { if (v1 < v2)return 0; ll v3 = (fc[v1] * rv[v2]) % MOD; v3 = (v3 * rv[v1 - v2]) % MOD; return v3; }

int main() {
	fc[0] = rv[0] = 1;
	for (int i = 1; i < N; i++) { fc[i] = (fc[i - 1] * i) % MOD; rv[i] = pw(fc[i], MOD - 2); }
