		ll v1 = cmb(n, i), v2 = cmb(n, i - 1), v3 = cmb(t1 + n - t2, i - 1);
		v1 = (v1 + v2) % MOD; v1 = (v1 - v3 + MOD) % MOD;
		cout << v1 << endl;
	}
	cout << 1 << endl;
	return 0;
}

