    }

   // cout << l << " " << r << endl;

    for (ll i = 1; i <= n + 1; i++) {
        ll ans = inst.nCr(n+1,i) - inst.nCr(n-r+l,i-1) + MOD;
        ans %= MOD;
        cout << ans << endl;
    }

