const ll MOD = 1e9+7;

ll pow(ll x, ll exp) {
  if(exp == 0) {
    return 1;
  }
  if(exp % 2 == 1) {
    return pow(x, exp - 1) * x % MOD;
  } else {
    ll y = pow(x, exp / 2);
    return y * y % MOD;
  }
}

struct dat {
  VL fact;
  VL inv_fact;
  dat(int n): fact(n), inv_fact(n) {
    fact[0] = 1;
    inv_fact[0] = 1;
    REP(i,1,n) {
      fact[i] = fact[i-1] * i % MOD;
      inv_fact[i] = pow(fact[i], MOD - 2);
    }
  }
  ll comb(ll x, ll y) {
    if(y > x) return 0;
    return fact[x] * inv_fact[y] % MOD * inv_fact[x-y] % MOD;
  }
};

