void calc_modinv(int n) {
    Inv[1] = 1;
    for(int i=2; i<=n; i++) {
        Inv[i] = 1LL * Inv[MOD%i] * (MOD - (MOD / i)) % MOD;
    }
}

void calc_factinv(int n) {
    fact[0] = factInv[0] = 1;
    for(int i=1; i<=n; i++) {
        fact[i] = 1LL * (fact[i-1] * i) % MOD;
        factInv[i] = 1LL * (factInv[i-1] * Inv[i]) % MOD;
    }
}

long long nCr(int n, int r) { 
    if(n - r >= 0 && r >= 0) return fact[n] * factInv[r] % MOD * factInv[n - r] % MOD;
    else return 0;
}

