    ll res = mod_pow(x * x % mod, n / 2);
    if (n % 2) res = res * x % mod;
    return res;
}

ll nCk(ll n, ll k) {
  if (n < k) return 0;
  return fact[n] * mod_pow(fact[k], mod - 2) % mod * mod_pow(fact[n - k], mod - 2) % mod;
}

