  LL m_num=1;
  for(int i=0;i<m;i++){
	n_num*=n-i;
	m_num*=m-i;
	LL g_num=boost::math::gcd(n_num,m_num);
	n_num/=g_num;
	m_num/=g_num;
  }
  //cout << n_num <<endl;
  return n_num;
}

