int binpow(int n, int k){
  if(k == 0){
    return 1 % inf;
  }
  int z = binpow(n, k / 2);
  z = z * 1ll * z % inf;
  if(k & 1){
    z = z * 1ll * n % inf;
  }
  return z;
}

int n;
int a[N], u[N], p1, p2;
int f[N], rf[N];

int cnk(int n, int k){
  if(n < k){
    return 0;
  }
  return (f[n] * 1ll * rf[k] % inf) * 1ll * rf[n - k] % inf;
}

int main(){
  scanf("%d", &n);
  f[0] = 1;
  rf[0] = 1;
  for(int i = 1; i <= n * 2 + 3; ++i){
    f[i] = f[i - 1] * 1ll * i % inf;
    rf[i] = (binpow(i, inf - 2) * 1LL * rf[i - 1]) % inf; 
  }
  for(int i = 1; i <= n + 1; ++i){
    scanf("%d", a + i);
    if(u[a[i]]){
      p2 = i;
      p1 = u[a[i]];
    }
    u[a[i]] = i;
  }
  printf("%d\n", n);
  // sum cnk(a, x) * cnk(b, len - x)
  for(int len = 2; len <= n + 1; ++len){
    int ans = cnk(n + 1, len);
    int tot = p1 - 1 + (n + 1) - p2;
    ans -= cnk(tot, len - 1);
    if(ans < 0){
      ans += inf;
    }
    printf("%d\n", ans);
  }
  return 0;
}

