#define MOD 1000000007

long long fac[100005];
long long invfac[100005];

long long powmod(long long a,int b)
{
    if (b==1) return a;
    if (b&1) return (powmod((a*a)%MOD,b/2)*a)%MOD;
    return powmod((a*a)%MOD,b/2);
}

long long inv(long long a)
{
    return powmod(a,MOD-2);
}

long long choose(long long a,long long b)
{
    if (b<0 || b>a) return 0;
    return (((fac[a]*invfac[b])%MOD)*invfac[a-b])%MOD;
}

int t1,t2;
