long long conb(const long long n, long long r) {
	if (2 * r > n)
		r = n - r;
	if (memo[n][r] != 0)
		return memo[n][r];
	if (n == r || r == 0)
		return memo[n][r] = 1;
	else if (r == 1)
		return memo[n][r] = n;
	else
		return memo[n][r] = conb(n - 1, r - 1) + conb(n - 1, r);
}

