int ipow(int x, int y)
{
    if(y == 0)
        return 1;
    if(y % 2)
        return 1LL * ipow(x, y - 1) * x % mod;
    int t = ipow(x, y / 2);
    return 1LL * t * t % mod;
}

int inv(int x)
{
    return ipow(x, mod - 2);
}

