#include <bits/stdc++.h>
using namespace std;
map<int,int> ps;
int nn, x, z;
int c[100005];
int d[100005];
int e[100005];
typedef long long LL;

LL n,m;

LL p = 1000000007;
LL quick_mod(LL a, LL b)
{
    LL ans = 1;
    a %= p;
    while(b)
    {
        if(b & 1)
        {
            ans = ans * a % p;
            b--;
        }
        b >>= 1;
        a = a * a % p;
    }
    return ans;
}

LL C(LL n, LL m)
{
    if(m > n) return 0;
    LL ans = 1;
    for(int i=1; i<=m; i++)
    {
        LL a = (n + i - m) % p;
        LL b = i % p;
        ans = ans * (a * quick_mod(b, p-2) % p) % p;
    }
    return ans;
}

LL Lucas(LL n, LL m)
{
    if(m == 0) return 1;
    if (m > n) return 0;
    return C(n % p, m % p) * Lucas(n / p, m / p) % p;
}


int main() {
    ios::sync_with_stdio(false);
    cin >> nn;
    nn++;
    for (int i = 0; i < nn; i++) {
        int temp;
        cin >> temp;
        if (ps[temp]) {
            x = ps[temp] - 1;
            z = nn - i - 1;
            break;
        } else {
            ps[temp] = i + 1;
        }
    }
    for (int i = 0; i <= nn; i++) {
        c[i] = Lucas(nn, i);
        d[i] = Lucas(x, i);
        e[i] = Lucas(z, i);
    }
    cout << nn - 1<< "\n";
    for (int i = 2; i < nn; i++) {
        LL ans = c[i];
        for (int j = 0; j < i; j++) {
            ans = (ans - d[j] * e[i  - 1 - j] % p) % p;
        }
        cout << ans << "\n";
    }
    cout << 1 << "\n";
    return 0;
}

