i64 mod = 1000000007;

i64 pow_mod(i64 x, i32 r) {
    if (x < 0) x += mod;
    x %= mod;

    if (r <= 1) {
        return x;
    }
    auto t = r / 2;
    auto s = pow_mod(x, t);

    auto a = (s * s) % mod;
    if (r % 2 == 0) {
        return a;
    } else {
        return (a * x) % mod;
    }
};


int body(int &argc, char **argv) {
    using namespace debug;
    auto n = read<i32>();
    auto as = read<i32>(n + 1);
    FORE(a, as) { a -= 1; }

    i32 d1 = -1;
    i32 d2 = -1;

    V<i32> num(n, 0);
    REP (i, n + 1) {
        num[as[i]] += 1;
    }
    auto x = distance(num.begin(), max_element(num.begin(), num.end()));

    REP (i, n + 1) {
        if (as[i] == x) {
            if (d1 == -1) {
                d1 = i;
            } else {
                d2 = i;
            }
        }
    }

    auto fact = V<i64>(n + 2); // fact[i] = i!
    auto fact_inv = V<i64>(n + 2); // fact_inv[i] = (i!)^{^1}
    fact[0] = 1;
    FOR(i, 1, n + 2) {
        fact[i] = fact[i-1] * i;
        if (fact[i] < 0) fact[i] += mod;
        fact[i] %= mod;
    }
    fact_inv[n + 1] = pow_mod(fact[n + 1], 1000000005);
    REPR(i, n + 1) {
        fact_inv[i] = fact_inv[i + 1] * (i + 1);
        fact_inv[i] += mod;
        fact_inv[i] %= mod;
    }

    auto comb_mod = [&](i64 n, i64 r) -> i64 {
        if (n < r) {
            return 0;
        }

        auto a = fact[n];
        auto b = fact_inv[r];
        auto c = fact_inv[n - r];
        i64 x = a * b;
        x %= mod;
        x *= c;
        x %= mod;

        return x;
    };

    FOR (k, 1, n + 2) {
        auto max = comb_mod(n + 1, k);
        max -= comb_mod(d1+n-d2, k-1);

        if (max < 0) { max += mod; }
        max %= mod;

        cout << max << endl;
    }

    return 0;
}

