	rep(i, n + 1) {
		scanf("%lld", &a);
		if (m.find(a) == m.end()) {
			m[a] = i;
		}
		else {
			p = m[a] + (n - i);
			break;
		}
	}
	ll b = n + 1, c = 1, d = 1, e = 1;
	rep(i, n + 1) {
		pll((b * c % MOD - d * e % MOD + MOD) % MOD);
		b = b * (n - i) % MOD;
		c = c * inv(i + 2) % MOD;
		if (i <= p) {
			d = d * (p - i) % MOD;
			e = e * inv(i + 1) % MOD;
		}
	}
	return 0;
}

