ll fastpow(ll base, ll p) {
	ll ans = 1;
	while(p > 0) {
		if(p % 2 == 1) {
			ans = (ans * base) % mod;
		}
		base = (base * base) % mod;
		p /= 2;
	}
	return ans;
}

ll ncr(ll n, ll r) {
	if(r > n || n < 0 || r < 0) {
		return 0;
	}
	ll ans = (fact[n] * rfact[r]) % mod;
	ans = (ans * rfact[n - r]) % mod;
	return ans;
}

