ll po(ll x,ll y,ll p = mod) {ll res=1;x%=p;while(y>0){if(y&1)res=(res*x)%p;y=y>>1;x=(x*x)%p;}return res;}

int fac[N] , invfac[N];
void pre(){
    fac[0] = 1;
    for(int i = 1 ; i < N ; ++i)
        fac[i] = (i * fac[i - 1]) % mod;
    invfac[N - 1] = po(fac[N-1] , mod - 2);
    for(int i = N - 2 ; i >= 0 ; --i)
        invfac[i] = (invfac[i + 1] * (i + 1)) % mod ;
}

int ncr(int n , int r){
    if(r > n) return 0;
    ll res = (fac[n] * invfac[r]) % mod ;
    res = (res * invfac[n - r]) % mod ;
    return res;
}

void solve()
{
    int l1 = -1 , l2 = -1;
    int n ;
    cin >> n ;
    pre();
    int vis[n + 1] = {} , a[n + 1];
    for(int i = 1 ; i <= n + 1 ; ++i){
        cin >> a[i];
        if(vis[a[i]]){
            // cout << i << ' ' << vis[a[i]] << ' ' ;
            l1 = vis[a[i]] - 1;
            l2 = (n + 1 - i);
            break;
        }else vis[a[i]] = i;
    }

    ll ans[n + 1] = {}; 
    for(int k = 1 ; k <= n + 1 ; ++k) ans[k] = ncr(n + 1 , k);
    for(int k = 1 ; k <= n + 1 ; ++k){
        ll res = ncr(l1 + l2, k - 1);
        ans[k] = (ans[k] + mod - res) % mod;
        cout << ans[k] << '\n';
    }
}   


