    if(k % 2 == 0){
        long long c = beki(i, k / 2);
        c = c % p;
        c = c * c;
        c = c % p;
        return c;
    } else {
        long long c = beki(i, k / 2);
        c = c % p;
        c = c * c;
        c = c % p;
        c = c * i;
        c = c % p;
        return c;
    }
}


