int fac[maxn], ifac[maxn];

int pow_mod(int x, int n)
{
	int y = 1;
	while(n)
	{
		if(n & 1) y = 1ll * y * x % mod;
		x = 1ll * x * x % mod;
		n >>= 1;
	}
	return y;
}

