ll fac[N];
void init()
{
    ll i;
    fac[0]=1;
    for (ll i = 1; i < N; i++)
    fac[i] = fac[i - 1] * i % mod;
}
ll exgcd(ll a, ll b, ll &x, ll &y) {
    if (!b) {x = 1; y = 0; return a;}
    ll d = exgcd(b, a % b, y, x);
    y -= a / b * x;
    return d;
}

ll inv(ll a, ll n) {
    ll x, y;
    exgcd(a, n, x, y);
    return (x + n) % n;
}

ll C(ll n, ll m) {
    return fac[n] * inv(fac[m] * fac[n - m] % mod, mod) % mod;
}
int main() {
    ios_base::sync_with_stdio(0);
    ll n;
    init();
    ll x, t, id1 = 0, id2 = 0;
