long EXC[50001];

long exc(long a)
{
    if (EXC[a] != 0)
        return EXC[a];

    long x = 1;
    for (long i = 2; i <= a; ++i) {
        x *= i;
        x %= MOD;
    }
    // cerr << "EXC " << a << " " << x << endl;
    EXC[a] = x;
    return x;
}

long pw(long a, long p)
{
    if (p == 1)
        return a;

    if (p % 2 == 0) {
        long b = pw(a, p / 2);
        b *= b;
        b %= MOD;
        return b;
    }

    long b = pw(a, p - 1);
    b *= a;
    b %= MOD;
    return b;
}

long IEXC[50001];

long iexc(long a)
{
    if (IEXC[a] != 0)
        return IEXC[a];

    long v = exc(a);
    long p = MOD - 2;

    v = pw(v, p);

    // cerr << "IEXC" << " " << a << " " << v << endl;
    IEXC[a] = v;
    return v;
}

long comb(long a, long b)
{
    if (b > a)
        return 0;
    if (a - b < b)
        return comb(a, a - b);

    long p = exc(a);
    long q = iexc(a - b);
    long r = iexc(b);

    long v = p;
    v *= q;
    v %= MOD;
    v *= r;
    v %= MOD;
    // cerr << "COMB " << a << " " << b << " " << v << " (" << p << " " << q << " " << r << ")" << endl;
    return v;
}

