int64 comb(int n, int m) {
  if (n < 0 || m < 0) return 0;
  if (m > n) return 0;
  return (int64)F[n] * G[m] % MOD * G[n - m] % MOD;
}

int64 power_mod(int64 a, int n) {
  int64 ret = 1;
  for (; n; n >>= 1) {
    if (n & 1) ret = ret * a % MOD;
    a = a * a % MOD;
  }
  return ret;
}

int64 inv_mod(int64 a) {
  return power_mod(a, MOD - 2);
}

