// a^x を mod で求める
// 反復二乗法
// O( log x )
long long mod_pow( long long a, long long x, long long mod )
{
	a %= mod;

	long long res = 1;
	for ( ; x; x >>= 1, ( a *= a ) %= mod )
	{
		if ( x & 1 )
		{
			( res *= a ) %= mod;
		}
	}
	return res;
}

// p が素数のとき、p を法とする剰余体での逆元を求める
// Fermat の小定理を利用
// a^{ p - 1 } \equiv 1 ( mod p )
// a^{ p - 2 } \equiv a^{-1} ( mod p )
// incluide : mod_pow
int mod_inverse( long long a, long long p )
{
	return mod_pow( a, p - 2, p );
}

// 素数を法とする剰余体での n! を求める
class modFact
{
private:
	const int MAX_N, MOD;
	vector<int> fact;

public:
	modFact( const int n, const int mod ) : MAX_N( n ), MOD( mod ), fact( min( MAX_N + 1, MOD ) )
	{
		fact[0] = 1;
		for ( int i = 1; i < (int)fact.size(); ++i )
		{
			fact[i] = 1LL * fact[ i - 1 ] * i % MOD;
		}
		return;
	}

	int operator()( const int n )
	{
		int e;
		return operator()( n, e );
	}

	int operator()( const int n, int &e )
	{
		e = 0;
		if ( n == 0 )
		{
			return 1;
		}

		const long long res = operator()( n / MOD, e );
		e += n / MOD;

		if ( n / MOD % 2 != 0 )
		{
			return res * ( MOD - fact[ n % MOD ] ) % MOD;
		}
		return res * fact[ n % MOD ] % MOD;
	}
};
