LL fastpow(LL base, LL p, int mod) {
    LL ans = 1;
    while (p > 0) {
        if (p % 2 == 1) {
            ans = (ans * base) % mod;
        }
        base = (base * base) % mod;
        p /= 2;
    }
    return ans;
}

LL ncr(LL n, LL r, int mod) {
    if (r > n || n < 0 || r < 0) {
        return 0;
    }
    LL ans = (fact[n] * rfact[r]) % mod;
    ans = (ans * rfact[n - r]) % mod;
    return ans;
}


