template<int SIZE>
struct Factorial {
    int fact[SIZE];

    constexpr Factorial() : fact() {
        fact[0] = 1;
        for (int i = 1; i < SIZE; ++i) {
            fact[i] = fact[i - 1] * i % mod;
        }
    }
};

template<int SIZE>
struct Inverse_factorial {
    int inv[SIZE];

    constexpr Inverse_factorial() : inv() {
        inv[0] = 1;
        for (int i = 1; i < SIZE; ++i) {
            inv[i] = inv[i - 1] * mod_pow(i, mod - 2) % mod;
        }
    }
};

