  int left = st[0], right = N - st[1] - 1;
  int sub[100000] = {};
  for(int i = 2; i <= N; i++) {
    sub[i - 1] += modCombination(right + left, i - 1);
  }
  sub[0]++;
  for(int i = 1; i <= N; i++) {
    cout << (modCombination(N, i) + mod - sub[i - 1]) % mod << endl;
  }
}

