using namespace std;

typedef long long int lld;

const lld mod = 1e9+7;
const lld INF = 1e9;
const lld MAXN = 1e5;

vector<lld> fact,inv;


lld f(lld a,lld b, lld p)  // a^b mod pを求める
{
	if (b == 0)
	{
		return 1;
	}else if (b % 2 == 0)
	{
		lld d = f(a,b/2,p);  //a^b = a^(2k) = (a^k)^2  k = b / 2
		return d * d % mod;
	}else
	{
		return a * f(a,b-1,p) % mod;
	}
}

void init(lld n)
{
	fact.resize(n+1,1);
	inv.resize(n+1,1);

	for(int i = 2; i <= n; i++)  //　nまでの階乗を求める
	{
		fact[i] = fact[i-1] * i % mod;
	}
	for(int i = 2; i <= n; i++)  //a^(-1) mod p = a^(p-2) mod p  ここをもう少し早くできるぽい
	{
		inv[i] = f(fact[i],mod-2,mod) % mod;
	}
}

lld comb(lld n,lld k)  //n_C_k
{
	if (n < k)
	{
		return 0;
	}
	return (fact[n] * inv[k] % mod) * inv[n-k] % mod;
}


int main()
{
	lld n;
	lld a[MAXN+1] = {0};

	cin >> n;

	for(int i = 0; i <= n; i++)
	{
		cin >> a[i];
	}

	if (n == 1)
	{
		cout << 1 << endl;
		cout << 1 << endl;
		return 0;
	}

	lld same,sum;

	for(int i = 0; i <= n; i++)
	{
		sum += a[i];
	}

	same = sum - (n * (n+1)) / 2;

	//cout << "same = " <<  same << endl;

	lld left,right;
	bool ch = false;

	for(lld i = 0; i <= n; i++)
	{
		if (a[i] == same)
		{
			if (!ch)
			{
				left = i+1;
				ch = true;
			}else
			{
				right = i+1;
				break;
			}
		}
	}
	//cout << "left = " << left << " right = " << right << endl;

	lld del = left + n - right;

	//cout << "del = " << del << endl;

	init(n+1);

