  REP(i,n){
    cin>>a[i];
    //mp[a[i]]++;
    cnt[a[i]]++;
    if(cnt[a[i]]==2){
      si=i;
    }
  }
  REP(i,n){
    if(a[i]==a[si]){
      fi=i;
      break;
    }
  }
  long long ans;
  long long sur=0;
  REPP(k,n+1){
    ans = comb(n+1,k);
    REP(i,k){
      if(i<=fi && k-1-i<=n-1-si){
        sur = mod(sur + mod(comb(fi,i)*comb(n-1-si,k-1-i)));
      }
    }
    ans = mod(ans - sur);
    cout<<ans<<endl;
    sur = 0;
  }
  return 0;
}

