ll modpow(ll a, ll b) {
	ll ret = 1;
	while (b) {
		if (b & 1)	ret = (ret*a) % mod;
		a = (a*a) % mod;
		b >>= 1;
	}
	return ret;
}

ll modinv(ll a) {
	return modpow(a, mod - 2);
}

ll nCm(int n, int m) {
	if (n < m)	return 0;
	return fac[n] * (ifac[m] * ifac[n - m] % mod) % mod;
}

