LL mod_pow(LL x, LL a) {
    if (a == 0) return 1;
    if (a % 2 == 0) {
        LL ret = mod_pow(x, a / 2);
        return (ret*ret) % MOD;
    }
    else {
        return (x*mod_pow(x, a - 1)) % MOD;
    }
}
LL comb(LL n, LL k) {
    if (n < k) return 0;
    LL ans = (fact[n] * inv_fact[k]) % MOD;
    ans = (ans*inv_fact[n - k]) % MOD;
