void comb_init(int max_n)
{
    fact.resize(max_n + 1), fact_inv.resize(max_n + 1);
    fact[0] = fact_inv[0] = 1;
    for (int i=1; i <= max_n; i++) {
        fact[i] = fact[i-1] * i % MOD;
