void list_mod_inverse(ll n, ll m)
{
    inv_mod.resize(n + 1);
    inv_mod[1] = 1;
    for (int i=2; i<=n; i++) {
        inv_mod[i] = inv_mod[m % i] * (m - m / i) % m;
