const ll mod = 1e9+7;
ll powmod(ll a, ll p){
  ll ans = 1;
  ll mul = a;
  for(; p > 0; p >>= 1, mul = (mul*mul) % mod){ //初期条件なし、pを2で割り続け、mulの値を更新
    if((p & 1) == 1) ans = ( ans * mul) % mod;//最下位Bitが1なら ansの値を更新
  }
  return ans;
}

const ll MAX_N = 2000001;

ll fact[MAX_N];
ll revfact[MAX_N];

void setFact(ll N){
  fact[0] = 1;
  for(int i = 1; i < min(MAX_N,N); ++i){
    fact[i] = fact[i-1]*i;
    fact[i] %= mod;
  }
  revfact[N-1] = powmod(fact[N-1],mod-2);//逆元を求める
  for(int i = N-2;i >= 0;--i){
    revfact[i] = revfact[i+1] * (i+1);
    revfact[i] %= mod;//互いに素
  }
}

ll getC(ll a, ll b){
  return (fact[a] * revfact[b] % mod) * revfact[a-b] % mod;
}
