    invfac[N + 1] = fpow(fac[N + 1],MOD - 2);
    for(int i = N ; i >= 0 ; --i) {
	invfac[i] = mul(invfac[i + 1],i + 1);
    }
    for(int i = 1 ; i <= N + 1 ; ++i) {
	int res = C(N + 1,i);
	res = inc(res,MOD - C(N + 1 - p,i - 1));
	out(res);enter;
    }
}
