        if(check[a[i]] == 0){
            check[a[i]] = 1;
        }
        else{
            duplicate = a[i];
        }
    }

    int f = -1, s = -1;
    for(int i = 0; i < n; i++){
        if(a[i] == duplicate && f == -1){
            f = i;
        }
        else if(a[i] == duplicate){
            s = n-i;
        }
    }

    make_fact(n+10);
    make_invfact(n+10);
    int k_max = max(f, s) + 2;
    int nn = 1;
    while(nn < k_max){
        nn *= 2;
    }

    for(int i = 0; i <= nn; i++){
        perm_left[i] = P(0.0, 0.0);
        perm_right[i] = P(0.0, 0.0);
    }

    for(int l = 0; l <= f; l++){
        perm_left[l] = P((double)perm(f, l), 0.0);
    }
    for(int l = 0; l <= s; l++){
        perm_right[l] = P((double)perm(s, l), 0.0);
    }

    fft(perm_left, nn, 1);
    fft(perm_right, nn, 1);
    for(int i = 0; i < nn; i++){
        perm_left[i] *= perm_right[i];
    }
    fft(perm_left, nn, -1);

    for(int k = 1; k <= n+1; k++){
        ll whole = perm(n+1, k);
        if(k == 1){
            cout << sub(whole, 1) << endl;
        }
        else {
            cout << sub(whole, (ll) (perm_left[k - 1].real() / (nn) + 0.5)) << endl;
        }
    }
