ll p (ll x, ll a) {
  ll res = 1;
  while(a) {
    if(a & 1) res = res * x % mod;

    x = x * x  % mod;

    a >>= 1;
  }

  return res % mod;
}

ll r_f(ll f) {
  return p(f,mod-2);
}

ll nCr(int n, int r) {
  if(n-r < 0 || r < 0) return 0;
  return foo[n] * (r_f(foo[r]) * r_f(foo[n-r]) % mod) % mod;
}

