ll mypow(ll a,ll b){//繰り返し2乗法
	if(b==0) return 1;
	ll tmp=mypow(a,b/2);
	if(b%2) return (((tmp*tmp)%MOD)*a)%MOD;
	else return (tmp*tmp)%MOD;
}

ll comb(ll n,ll k){//順列組合せ
	if(k < 0 || k > n) return 0;
	ll res=1;
	k=min(n-k,k);
	for(int i=n-k+1;i<=n;i++) res=(res*i)%MOD;
	for(int i=1;i<=k;i++)res=(res*mypow(i,MOD-2))%MOD;
	return res;
}

ll H(ll n,ll k){	//重複組み合わせ
	return comb(n+k-1,k);
}
