const int inf = 1e9 + 7;
const int N = 1e6 + 5;

typedef long long ll;

int n, d, b[N], a[N], f[N];

int binpow(int a, int n)
{
      int res = 1;
      while(n)
      {
            if(n & 1)
                  res = (res * a) % inf;
            a = (a * a) % inf;
            n >>= 1;
      }
      return res;
}


int Cnk(int n, int k)
{
      return f[n] * (binpow(f[k] * f[n - k] % inf, inf - 2) % inf) % inf;
}

