ll fact[maxn];

ll mypow(ll A, ll M)
{
	ll res = 1;
	while(M)
	{
		if(M&1)
			res = (res*A) % mod;
		M /= 2;
		A = (A*A) % mod;
	}
	return res;
}

ll inv[maxn];

void pre()
{
	fact[0] = 1;
	for(int i=1;i<maxn;i++)
		fact[i] = (fact[i-1] * i) % mod;
	for(int i=0;i<maxn;i++)
		inv[i] = mypow(fact[i], mod-2);

}

ll C(ll N, ll R)
{
	if(N < R)
		return 0;
	return (fact[N]*((inv[N-R]*inv[R])%mod)) % mod;
}

