const ll MAX = 200000;
ll inv[MAX], fac[MAX], finv[MAX];

void settable() {
   fac[0] = fac[1] = 1;
   finv[0] = finv[1] = 1;
   inv[1] = 1;
   for (int i = 2; i <=MAX ; i++){
       fac[i] = fac[i - 1] * i % MOD;
       inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
       finv[i] = finv[i - 1] * inv[i] % MOD;
   }
}
ll choose(ll n, ll k){
   if (n < k) return 0;
   if (n <= 0 || k < 0) return 0;
   return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

ll modpow(ll n, ll k){
   ll rtn = 1;
   while(k > 0){
       if(k&1) rtn = rtn * n % MOD;
       n = n * n % MOD;
       k = k >> 1;
   }
   return rtn;
}

