const int mod = 1e9 + 7;

int mul(int a, int b) {
	return static_cast<ll>(a) * b % mod;
}

int bp(int a, int b) {
	if (b == 0) {
		return 1;
	}
	if (b % 2 == 1) {
		return static_cast<ll>(bp(a, b - 1)) * a % mod;
	}
	a = bp(a, b / 2);
	return static_cast<ll>(a) * a % mod;
}

int inv(int a) {
	return bp(a, mod - 2);
}

int divs(int a, int b) {
	return mul(a, inv(b));
}

