int used[100001];

int inv[100001];
int fact[100001];
int invFact[100001];

void Init(int max) {
  inv[1] = 1;
  for (int i = 2; i <= max; i++) {
    inv[i] = inv[(int) (MOD % i)] * (MOD - MOD / i) % MOD;
  }
  fact[0] = invFact[0] = 1;
  for (int i = 1; i <= max; i++) fact[i] = fact[i - 1] * i % MOD;
  for (int i = 1; i <= max; i++) invFact[i] = invFact[i - 1] * inv[i] % MOD;
}


int Combination(int x, int y) {
  if (x < y) {
    return 0;
  }
  return fact[x] * invFact[y] % MOD * invFact[x - y] % MOD;
}


signed main() {
  cin >> n;
  a.resize(n + 1);

  Init(100001);

  int pre_idx = -1;
  int dup_idx = -1;
  for (int i = 0; i < n + 1; i++) {
    cin >> a[i];
    if (used[a[i]] != 0) {
      dup_idx = i;
      pre_idx = used[a[i]] - 1;
    }
    used[a[i]] = i + 1;
  }
  // cerr << "dup_idx: " << dup_idx << endl;
  // cerr << "pre_idx: " << pre_idx << endl;
  if (n == 1) {
    cout << 1 << endl << 1 << endl;
