  for (int i = 1; i <= n + 1; i++) {
    int ans = Combination(n + 1, i);
    if (i == 1) {
      ans--;
    } else {
      int sub = 0;
      if (i <= n - dup_idx) {
        sub = Combination(n - dup_idx + pre_idx, i);        
      } else {
        sub = Combination(n - dup_idx + pre_idx, i - 1);        
      }
      ans -= sub;
      ans %= MOD;
    }
    cout << ans << endl;
  }

  return 0;
}

