int K(int k) {
	if (k == 1)return N;
	int res = 0;
	//2
	res += C(N + 1 - 2, k - 2);
	res %= mod;
	//1
	for (int ll = 1; ll < k - 1; ++ll) {
		int rr = (k - 1) - ll;
		res += C(l, ll) * C(c + r, rr)
			+ C(l + c, ll) * C(r, rr)
			- C(l, ll) * C(r, rr);
		res %= mod;
	}
	res += C(l + c, k - 1);
	res += C(r + c, k - 1);
	res %= mod;
	//0
	res += C(N + 1 - 2, k);
	res %= mod;
	return res;
}

