int fact[SIZE];
int invFact[SIZE];

void Init(int max) {
  inv[1] = 1;
  for (int i = 2; i <= max; i++) {
    inv[i] = inv[(int) (MOD % i)] * (MOD - MOD / i) % MOD;
  }
  fact[0] = invFact[0] = 1;
  for (int i = 1; i <= max; i++) fact[i] = fact[i - 1] * i % MOD;
  for (int i = 1; i <= max; i++) invFact[i] = invFact[i - 1] * inv[i] % MOD;
}


int Combination(int x, int y) {
  if (x < y) {
    return 0;
  }
  return fact[x] * invFact[y] % MOD * invFact[x - y] % MOD;
}


signed main() {
  cin >> n;
