ll extgcd(int a, int b, int&x, int& y) {
	int d = a;
	if (b != 0) {
		d = extgcd(b, a%b, y, x);
		y -= (a / b)*x;
	}
	else {
		x = 1; y = 0;
	}
	return d;
}
ll mod_inverse(ll a, ll m) {
	int x, y;
	extgcd(a, m, x, y);
	return (m + x%m) % m;
}

ll mod_fact(ll n, ll p, ll& e) {
	e = 0;
	if (n == 0)return 1;
	//pの倍数部分
	int res = mod_fact(n / p, p, e);
	e += n / p;
	ll nmodp=1;
	reps(i, 1, n + 1) {
		nmodp *= i;
		nmodp %= 1000000007;
	}
	if (n / p % 2 != 0)return res*(p - nmodp) % p;
	return res*nmodp % p;
}
ll mod_comb(int n, int k, int p) {
	if (n<0 || k<0 || n<k)return 0;
	ll e1, e2, e3;
	ll a1 = mod_fact(n, p, e1), a2 = mod_fact(k, p, e2), a3 = mod_fact(n - k, p, e3);
	if (e1>e2 + e3)return 0;
	return a1*mod_inverse(a2*a3%p, p) % p;
}
