class Comb {
    vi fact;

public:
    Comb(int n) {
        fact.resize(n+1);
        fact[0] = fact[1] = 1;
        REP(i, 2, n+1) {
            ll tmp = (ll)fact[i-1] * i;
            fact[i] = (tmp % MOD);
        }
    }

    // Fermat's little theorem
    int nCr(ll n, ll r) {
        if(n - r < 0)
            return 0;
        ll numer = fact[n];
        ll denom = ((ll)fact[n-r] * fact[r]) % MOD;
        ll d = fpow(denom, MOD-2, MOD);
        return (numer * d) % MOD;
    }
};


bool solve() {
    int n;
