        if(ary[i] == dup_num) {
            if (left == -1)
                left = i;
            else
                right = (n-i);
        }
    }

    rep(i, n+1) {
        ll all = comb.nCr(n+1, i+1);
        ll sub = (ll)comb.nCr(left+right, i);
        int ans = (all - sub + MOD) % MOD;
        cout << ans << endl;
    }
}

