#define MAXN 100010

ll foo[MAXN];

void init() {
    foo[0] = 1;
    for (int i = 1; i < MAXN; ++i) {
        foo[i] = i * foo[i - 1] % mod;
    }
}

ll myPow(ll base, int exp) {
    ll res = 1;
    while (exp) {
        if (exp & 1) res = res * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    return res;
}

ll inv(ll a) {
    return myPow(a, mod - 2);
}

ll C(ll a, ll b) {
    return (foo[a] * inv(foo[b]) % mod) * inv(foo[a - b]) % mod;
}

int main() {
