        cand = cand ^ i ^ a[i];
    }

    bool between = false;
    int cnt = 0;
    for (int i = 0; i <= n; ++i) {
        if (a[i] == cand) {
            if (between) {
                between = false;
            } else {
                between = true;
            }
        } else {
            if (!between) ++cnt;
        }
    }

    for (int i = 1; i <= n + 1; ++i) {
        if (i > 1) cout << endl;
        if (i - 1 <= cnt) {
            cout << (C(n + 1, i) - C(cnt, i - 1) + mod) % mod;
        } else {
            cout << C(n + 1, i);
        }
    }

    return 0;
}

