// 拡張ユークリッド互除法 (入力 : 整数 a, n, 出力 : GCD(a, n) と xa + yb = GCD(a, n) を満たす整数 x, y)
template<typename Ty> void ExEuclid(Ty a, Ty b, Ty& gcd, Ty& x, Ty& y) {

    Ty r1, r2, r3, x1, x2, x3, y1, y2, y3, q;

    r1 = a; x1 = 1; y1 = 0;
    r2 = b; x2 = 0; y2 = 1;

    while (r2 != 0) {

        r3 = r1 % r2;
        q = r1 / r2;

        x3 = x1 - q * x2;
        y3 = y1 - q * y2;

        r1 = r2; r2 = r3;
        x1 = x2; x2 = x3;
        y1 = y2; y2 = y3;

    }

    gcd = r1; x = x1; y = y1;
    if (gcd < 0) { gcd *= -1; x *= -1; y *= -1; };
}

// a と m は互いに素が前提
template<typename Ty> Ty invmod(Ty a, Ty m) {
    Ty gcd, x, q;
    ExEuclid(a, -m, gcd, x, q);
    if (gcd != 1) return -1;

    return x;
}

// nCk mod p
template<typename Ty> Ty nCkModp(Ty n, Ty r, Ty p)
{
    r = min(r, n - r);

    Ty i, ret = 1;
    for (i = 1; i <= r; i++) {
        ret = ret * (n - i + 1) % p;
        ret = ret * invmod(i, p) % p;
    }
    return (ret + p) % p;
}

