		this->temp[N] = N;
		for (int i = N-1; i >= 1; --i) 
			this->temp[i] = ((LL)i*this->temp[i+1])%MOD;
		this->res[0] = 1;
		for (int i = 1; i <= N; ++i)
			this->res[i] = ((LL)powMOD(fact[i], MOD-2)*this->temp[N-i+1])%MOD;
	}

