 namespace Poly{
    struct Complex{
        double r , c;
        Complex( double r = 0 , double c = 0 ) : r( r ) , c( c ){}
        friend Complex operator + ( const Complex & x , const Complex & y ){
            return Complex( x.r + y.r , x.c + y.c );
        }
        friend Complex operator * ( const Complex & x , const Complex & y ){
            return Complex( x.r * y.r - x.c * y.c , x.r * y.c + y.r * x.c );
        }
        friend Complex operator - ( const Complex & x , const Complex & y ){
            return Complex( x.r - y.r , x.c - y.c );
        }
        Complex Conj(){
            return Complex( this->r , -this->c );
        }
    };

    const static int maxn = 1 << 18;
    const double pi = acos( -1 );
    const int mod = 1e9 + 7;

    Complex w1[maxn + 1] , w2[maxn + 1] , fr[maxn] , fw[maxn] , A[maxn] , B[maxn] , C[maxn] , D[maxn];

    void Prepare(){
        for(int i = 1 ; i <= maxn ; ++ i)
            w1[i] = w2[i] = Complex( cos( 2 * pi / i ) , sin( 2 * pi / i ) ),
            w2[i].c = -w2[i].c;
    }

    void ButterflyTrans( Complex * x , int n ){
        for(int i = 1 , j = n >> 1 ; i < n - 1 ; ++ i ){
            if( i < j )
                swap( x[i] , x[j] );
            int k = n >> 1;
            while( j >= k ){
                j -= k;
                k >>= 1;
            }
            if( j < k)
                j += k;
        }
    }

    void DFT( Complex * x , int n , int on ){
        ButterflyTrans( x , n );
        for(int len = 2 ; len <= n ; len <<= 1)
            for(int i = 0 ; i < n ; i += len){
                Complex base( 1 , 0 ) , t = on > 0 ? w1[len] : w2[len];
                for( Complex * l = x + i , * r = x + i + (len >> 1) ; r < x + i + len ; ++ l , ++ r , base = base * t ){
                    Complex u = *l , v = *r * base;
                    *l = u + v;
                    *r = u - v;
                }
            }
    }

    void DFT( Complex * x , int n , Complex * r1 = A , Complex * r2 = B ){
        DFT( x , n , 1 );
        for(int i = 0 ; i < n ; ++ i){
            int j = ( n - i ) & (n - 1);
            r1[i] = ( x[i] + x[j].Conj() ) * Complex( 0.5 , 0 );
            r2[i] = ( x[i] - x[j].Conj() ) * Complex( 0 , -0.5 );
        }
    }

    void Mul( int * x , int * y , int * z , int n ){
        for(int i = 0 ; i < n ; ++ i){
            fr[i] = Complex( x[i] >> 15 , x[i] & 32767 );
            fw[i] = Complex( y[i] >> 15 , y[i] & 32767 );
        }
        DFT( fr , n , A , B );
        DFT( fw , n , C , D );
        for(int i = 0 ; i < n ; ++ i){
            fr[i] = A[i] * C[i];
            fw[i] = A[i] * D[i] + B[i] * C[i];
            A[i] = B[i] * D[i];
        }
        DFT( fr , n , -1 );
        DFT( fw , n , -1 );
        DFT( A , n , -1 );
        for(int i = 0 ; i < n ; ++ i){
            int a = (long long)( fr[i].r / n + 0.5 ) % mod;
            int b = (long long)( fw[i].r / n + 0.5 ) % mod;
            int c = (long long)( A[i].r / n + 0.5 ) % mod;
            z[i] = ( ((long long)a << 30LL) + ((long long)b << 15LL) + c ) % mod;
        }
    }
};

