int combination(int n,int r) {
	if (n < r)return 0;
	if (r < 0)return 0;
	if (n == 0)return 1;
	if (n < 0)return 0;
	r = min(r, n - r);
	int res = 1;
	for (int i = 1; i <= r; ++i) {
