const ll M = 1e9+7;
ll inv(ll x) {
	ll res = 1;
	ll p = M-2;
	while(p) {
		if(p&1) res = (res*x) % M;
		p /= 2;
		x = (x*x)%M;
	}
	return res;
}
ll fmemo[100100];
ll fact(ll n) {
	if(fmemo[n]) return fmemo[n];
	return fmemo[n] = (n * fact(n-1)) % M;
}
ll binom(ll n, ll r) {
	return (fact(n) * inv(fact(r)) % M )* inv(fact(n-r)) % M;
}

