#define MOD 1000000007

long long binpow(long long x, long long pw)
{
	if (pw == 0)
		return 1;
	if (pw % 2 == 0)
	{
		auto xx = binpow(x, pw / 2);
		return (xx * xx) % MOD;
	}
	else
	{
		auto xx = binpow(x, pw - 1);
		return (x * xx) % MOD;
	}
}


