//二分累乗法
//http://chausson.eng.kagawa-u.ac.jp/Comp/Prog/DosC/Sec4/Note483.html
LL mod_pow(LL base, LL exp, LL mod=INF) {
	LL s;
	//初期条件
	if (exp == 0) { return 1; }
	if (exp == 1) { return (base%mod); }
	//漸化式
	s = mod_pow(base, exp / 2) % mod;//再帰呼出
	if (exp % 2 == 0) {//偶数の場合
		return (s*s) % mod;
	}
	else {//奇数の場合
		LL tmp = (s*s) % mod;
		tmp *= base;
		tmp %= mod;
		return tmp;
	}
}


//階乗テーブル計算
//引数：maxX:必要な階乗の剰余の最大値 (x! mod MODのうちxの最大値) 
//返値：first: (index)!(mod MOD), second: (index!)^-1(mod MOD)
pair<vector<LL>, vector<LL>> makeFactorialTable(LL maxX, LL mod = INF) {
	vector<LL> normal(1, 1);
	vector<LL> inverse(1, 1);

	//通常の剰余
	LL base = 1;
	FOR(i, 1, maxX) {
		base *= i;
		base %= mod;
		normal.push_back(base);
		if (base < 0)cout << "Error" << endl;
	}

	//逆元の剰余
	FOR(i, 1, maxX) {
		base = mod_pow(normal[i], mod - 2);// i!(mod MOD)
		inverse.push_back(base);
		//if (base < 0)cout << "Error2:" << normal[i] << " " << mod - 2 << "     " << base << endl;
	}
	return make_pair(normal, inverse);
}


//計算
