using namespace std;
typedef long long LL;
static const int MOD = 1000000007;

LL factor(int n) {
    if (n == 0 || n == 1) return 1;
    LL ret = 1;
    while (n > 1) {
        ret = ret * n;
        ret %= MOD;
        n--;
    }
    return ret;
}
LL power(LL base, int n) {
    LL cur = base;
    LL ret = 1;
    while (n) {
        if (n & 1) {
            ret *= cur;
            ret %= MOD;
        }
        cur *= cur;
        cur %= MOD;
        n = n >> 1;
    }
    return ret;
}

LL combine(int n, int k) {
    LL ret = 1;
    ret *= factor(n);
    ret *= power(factor(k), MOD-2);
    ret %= MOD;
    ret *= power(factor(n-k), MOD-2);
    ret %= MOD;
    return ret;

}

LL compute(int n, int k, int d) {
    if (k == 1) return n;
    if (k == n+1) return 1;
    LL ret = combine(n+1, k);
    if (n-d >= k) ret -= combine(n-1-d, k-1);
    if (ret < 0) ret += MOD;
    return ret;

}



