#include<bits/stdc++.h>
using namespace std;
typedef long long unsigned int ll;

long long unsigned int mod = 1000000007;

// PowMod( base, index, modulo) return base ** index % modulo {{{
// PowMod = base ** index % mod ( natural numbers )
long long unsigned int PowMod( long long unsigned int base, long long unsigned int index, long long unsigned int modulo = mod ){
    if( index == 0 ) return 1;
    // O( log(index) )
    if( index % 2 ){
        return base * PowMod(base, index - 1, modulo) % modulo;
    }else{
        long long unsigned int Phalf = index / 2;
        long long unsigned int half = PowMod(base, Phalf, modulo);
        return half * half % modulo;
    }
}
// }}}

// Comb( n, r, modulo ) return nCr % modulo {{{
// Comb(ination) = nCr % mod ( natural number )
long long unsigned int Comb( long long unsigned int n, long long unsigned int r, long long unsigned int modulo = mod){
    if( n < r ) return Comb(r,n,modulo);
    long long unsigned int Upper = 1;
    long long unsigned int Lower = 1;
    for(long long unsigned int i = 0; i < r; i++){
        Upper = Upper * (n-i) % modulo;
        Lower = Lower * (i+1) % modulo;
    }
    // Return (Upper / Lower)
    long long unsigned int ret = Upper * PowMod(Lower,modulo-2,modulo) % modulo;
    return ret;
}
