ll Combination(int n, int r)
{
    if (n <= 0 || r < 0 || r > n) return 0;
    if (n - r < r) r = n - r;
    if (r == 0) return 1;
    if (r == 1) return n;

    int numerator[r];
    int denominator[r];

    for (int k = 0; k < r; k++)
    {
        numerator[k] = n - r + k + 1;//分子
        denominator[k] = k + 1;//分母
    }

    for (int p = 2; p <= r; p++)
    {
        int pivot = denominator[p - 1];
        if (pivot > 1)
        {
            int offset = (n - r) % p;
            for (int k = p - 1; k < r; k += p)
            {
                numerator[k - offset] /= pivot;
                denominator[k] /= pivot;
            }
        }
    }

    ll result = 1;
    for (int k = 0; k < r; k++)
    {
        if (numerator[k] > 1){
        	result *= numerator[k];
        	result %= MOD;
        }
    }

    return result;
}


