T powm(T x, T p, T mod = 1000000007ll) {
    T y = 1;
    x = x%mod;
    while (0<p) {
        if (p % 2 == 1) {
            y = (y*x) % mod;
        }
        x = (x*x) % mod;
        p /= 2;
