		b >>= 1;
	}
	expMod[a] = (int)res;
	return expMod[a];
}

int fact_mod(int n, int m) {
    if(factMod[n] > 0) return factMod[n];
	long long res = 1;
	for (int i=n; i>0; --i)
		res = (res * i)%m;
	factMod[n] = (int)res;
	return factMod[n];
}

int comb_mod(int n, int r) {
    if(r>n)return 0;
	long long res = 1;
	for (int i=0; i<r; ++i)
		res = (res * (n - i) )%MOD;
	return ( res * exp_mod(fact_mod(r, MOD), MOD-2, MOD) ) % MOD;
}

