ll mod_pow(ll a, ll n, ll base) {
  ll res = 1;
  while (n > 0) {
    if (n % 2 == 1) res = (res * a) % base;
    a = (a * a) % base;
    n >>= 1;
  }
  return res;
}

void build_mod_fact(int n, ll base) {
  FACT[0] = 1;
  for (int i = 1; i <= n; i++) FACT[i] = (FACT[i - 1] * i) % base;
  for (int i = 0; i <= n; i++) IFACT[i] = mod_pow(FACT[i], base - 2, base);

