long ncr(long n, long r) {
	if (r * 2 > n) {
		return ncr(n, n - r);
	}
	long p = 1, q = 1;
	for (long i = n - r + 1; i <= n; i++) {
		p = p * i % MOD;
	}
	for (long i = 1; i <= r; i++) {
		q = q * i % MOD;
	}
	return (p * modPow(q, MOD - 2, MOD)) % MOD;
}

