int n, a[N], fac[N], inv[N], h[N] ;

int mul(int a, int b) {
    int ans = 1, w = a % mo ;
    for ( ; b; b /= 2) {
        if (b & 1) ans = (ll) ans * w % mo ;
        w = (ll) w * w % mo ; 
    }
    return ans ;
}

int calc(int x, int y) {
    if (x < y) return 0 ; 
    return (ll) fac[x] * inv[y] % mo * inv[x - y] % mo ;
}

int main() {
    scanf("%d", &n) ;
    ++ n ;
