    }
    fac[0] = inv[0] = 1 ;
    rep(i, 1, n) {
        fac[i] = (ll) fac[i - 1] * i % mo ; 
    }
    inv[n] = mul(fac[n], mo - 2) ;
    for (int i = n - 1; i; -- i) {
        inv[i] = (ll) inv[i + 1] * (i + 1) % mo ;
    }
