void init()
{
    int i;
    fac[0] =1;
    for(i =1; i <= N-5; i++)
        fac[i] = fac[i-1]*i % MOD;
}

LL pow(LL a, LL b)
{
    LL tmp = a % MOD, ans =1;
    while(b)
    {
        if(b &1)  ans = ans * tmp % MOD;
        tmp = tmp*tmp % MOD;
        b >>=1;
    }
    return  ans;
}

LL C(LL n, LL m)
{
    if(m > n)  return 0;
    return  fac[n]*pow(fac[m]*fac[n-m], MOD-2) % MOD;
}

LL Lucas(LL n, LL m)
{
    if(m ==0)  return 1;
    else return  (C(n%MOD, m%MOD)*Lucas(n/MOD, m/MOD))%MOD;
}

int main() {
