ll mod_mult(ll a, ll n, ll m) { //a*nMODm
	a %= m;
	if (a < 0) a += m;
	ll ans = 0;
	while (n >= 1) {
		if (n % 2 == 1) ans = (a + ans) % m;
		a = a * 2 % m;
		n >>= 1;
	}
	return ans;
}
ll mod_pow(ll a, ll n, ll m) {//a^n MOD m
	ll b = 1;
	while (n >= 1) {
		if (n % 2 == 1) b = mod_mult(a, b, m);
		a = mod_mult(a, a, m);
		n >>= 1;
	}
	return b;
}
