        else if(v[a[i]] == 2) {
            id2 = i;
        }
    }
    ll L = max(id1 - 1LL, 0LL), M = id2 - id1 - 1LL, R = max(n + 1LL - id2, 0LL);
    ll res = 0;
    for(ll i = 1; i <= n + 1; ++i){
        res = nCrModpLucas(n + 1, i * 1LL, MOD);
        res -= nCrModpLucas(L + R, (i - 1) * 1LL, MOD);
