		fact[i] = now;
		inverse[i] = pow(fact[i], mod - 2, mod);
	}
}

long long int comb(long long int n, long long int k) {
	if (n < k) return 0;
	if (n == k) return 1;
	if (k <= 0) return 1;
	return (((((long long)fact[n]) * inverse[k]) % mod) * inverse[n - k]) % mod;
	/*
