typedef long long Int;


	long long int extgcd(long long int a, long long int b, long long int& x, long long int& y) {
		long long int d = a;
		if (b != 0) {
			d = extgcd(b, a%b, y, x);
			y -= (a / b)*x;
		}
		else {
			x = 1; y = 0;
		}
		return d;
	}


	long long int mod_inverse(long long int a, long long int m) {
		long long int x, y;
		extgcd(a, m, x, y);	//ax+my=1
		return (m + x%m) % m;	//return positive integer
	}


