typedef long long int lli;

const lli mod = 1000000007;

lli power(lli n, lli x) {
    if (x == 0) return 1;
    if (x % 2) {
        return (power(n, x - 1) * n) % mod;
    } else {
        lli c = power(n, x / 2);
        return (c * c) % mod;
    }
}

vector<lli> p;

lli nCr(int n, int r) {
    if (n < 0 || r < 0 || n < r) return 0;
    lli res = p[n];
    res = (res * power(p[r], mod - 2)) % mod;
    res = (res * power(p[n - r], mod - 2)) % mod;
    return res;
}

