ll mod(ll a, ll b){
  a %= b;
  return a < 0 ? a + b : a;
}

ll powmod(ll a, ll b){
  if(b == 0) return 1;
  if(b & 1) {
    return mod(a * powmod(a, b - 1), MOD);
  } else {
    ll d = mod(powmod(a, b / 2), MOD);
    return mod(d * d, MOD);
  }
}

ll sub(ll a, ll b){
  a %= MOD, b %= MOD;
  a -= b;
  return a < 0 ? a + MOD : a;
}

ll comb(ll n,ll k){
	ll ans = fact[n];
	ans *= powmod(fact[k],MOD-2);
	ans %= MOD;
	ans *= powmod(fact[n-k],MOD-2);
	ans %= MOD;
	return ans;
}

