llong ppow(llong b, llong m) {
  llong ans = 1;
  for (; m > 0; m >>= 1) {
    if (m & 1) (ans *= b) %= rem;
    (b *= b) %= rem;
  }
  return ans;
}

llong fac[maxn], rfac[maxn];
void genfac() {
  fac[0] = 1;
  rep(i, maxn - 2) fac[i + 1] = (fac[i] * (i + 1)) % rem;
  rep(i, maxn - 1) rfac[i] = ppow(fac[i], rem - 2);
}

llong c(int n, int k) {
  llong u = fac[n];
  llong v = rfac[k] * rfac[n - k] % rem;
  return u * v % rem;
}

