/*
 * power function
 * @return a^b % mod
 * more details in https://telegram.me/dore_com/174
 */
int power(ll a, int b, ll mod = m)
{
	if (b == 0)
		return 1%mod;
	ll p = power(a%mod, b>>1);
	p *= p;
	p %= mod;
	if (b & 1) {
		p *= a;
		p %= mod;
	}
	return p;
}

ll f[N];

int C(ll n, int r)
{
	if(r < 0 || r > n)
		return 0;
	if(r == 0)
		return 1;
	return f[n]*power(f[r]*f[n-r]%m, m-2)%m;
}

