  std::vector<int> pos(n,-1);
  rep(i,0,n+1) {
    int & j = pos.at(a.at(i));
    if (j != -1) {
      edge = j + n - i;
    }
    j = i;
  }
  debug(pos,edge);

  rep(i,1,n+2) {
    mint x = fact.binom(n+1,i);
