static inline T mod_div(T a, T b, T m) {
	T x, y;
	T g = gcd_ext(b, m, &x, &y);
	T d = (g!=1) ? 0 : mod_norm(x, m);
	return (a * d) % m;
}

//n^k
T mod_power(T a, T b, T m) {
	T p = a, r = 1;
	while (b) {
		if (b % 2)
			r = (r * p) % m;
		b /= 2;
		p = p * p % m;
	}
	return r;
}

//n!
T mod_factorial(int n, T m) {
	T ct = 1;
	for (int i=2; i<=n; i++)
		ct = (ct * i) % m;
	return ct;
}


