//P(n,k)
T permutations(int n, int k) {
	if (k > n)
		return 0;
	T ct = 1;
	for (int i=0; i<k; i++)
		ct = mul(ct, n-i);
	return ct;
}


//C(n,k)
T combinations(int n, int k) {
	T ct = div(permutations(n, k), factorial(k));
	return ct;
}

void combinations_matrix(int n, int r, T c[n+1][n+1]) {
	// C(n,r) = C(n-1,r-1) + C(n-1,r)
	// where C(n,0) = C(n,n) = 1
	for(int j=0; j<=r; j++)
		c[0][j] = 0;
	for(int i=0; i<=n; i++)
		c[i][0] = 1;
	for(int i=1; i<=n; i++) {
		for(int j=1; j<=r; j++) {
			if (i == j) {
				// C(n,n) = 1
				c[i][j] = 1;
			}
			else if (j > i) {
				c[i][j] = 0;
			}
			else {
				c[i][j] = add(c[i-1][j-1], c[i-1][j]);
			}
		}
	}
}


