ll power(ll n, ll e, ll q){
	ll ret=1;

	while(e > 0){
		if(e&1) ret = ret*n%q;
		e = e>>1;
		n = n * n % q;
	}

	return ret;
}

ll multi(ll n, ll e, ll q){
	ll ret=0;

	while(e > 0){
		ret = (ret + (e&1)*n) % q;
		e = e>>1;
		n = (n << 1) % q;
	}

	return ret;
}

