//P(n,k)
T permutations(int n, int k) {
	if (k > n)
		return 0;
	T ct = 1;
	for (int i=0; i<k; i++)
		ct = mul(ct, n-i);
	return ct;
}


//C(n,k)
T combinations(int n, int k) {
	T ct = div(permutations(n, k), factorial(k));
	return ct;
}


