#define MOD 1000000007

long long power(long long n, int p) {
  if (p == 0) {
    return 1;
  }
  if (p == 1) {
    return n%MOD;
  }
  long long s;
  s = power(n, p/2);
  if (p % 2 == 0) {
    return s*s % MOD;
  }
  if (p % 2 == 1) {
    return n*power(n, p-1) % MOD;
  } else {
    return 0;
  }
}

