//P(n,k) = n!/(n-k)!
T permutations(int n, int k) {
	if (k > n)
		return 0;
	T ct = 1;
	for (int i=0; i<k; i++)
		ct = mul(ct, n-i);
	return ct;
}


//C(n,k) = n!/(k!*(n-k)!)
T combinations(int n, int k) {
	T ct = div(permutations(n, k), factorial(k));
	return ct;
}

void combinations_matrix(int n, int r, T c[n+1][r+1]) {
	// C(n,r) = C(n-1,r-1) + C(n-1,r)
	// where C(n,0) = C(n,n) = 1
	for(int i=0; i<=r; i++)
		c[0][i] = 0;
	for(int i=0; i<=n; i++)
		c[i][0] = 1;
	for(int i=1; i<=n; i++) {
		for(int j=1; j<=r; j++) {
			if (i == j) {
				// C(n,n) = 1
				c[i][j] = 1;
			}
			else if (j > i) {
				c[i][j] = 0;
			}
			else {
				c[i][j] = add(c[i-1][j-1], c[i-1][j]);
			}
		}
	}
}

void combinations_array(int n, int r, T c[r+1]) {
	T ct = 1, f = 1;
	c[0] = 1;
	for (int i=0; i<r; i++) {
		ct = mul(ct, n-i);
		f = mul(f, i+1);
		c[i+1] = div(ct, f);
	}
}


