       Equ1 true, however, all of them are in below pattern:
            a + k * y / r, b - k * x / r *)
    let extendedGcd x y =
        let a, b, r = extendedGcdInt64 (int64 x) (int64 y)
        int a, int b, int r

    (* Returns r = x % p where 0<=r<p *)
    let inMod p x = let r = x % p in if r < 0L then r + p else r

    (* Returns (i, r) where r is the GCD of p and x, and
            x * i % p = r *)
    let getInverseInt64 p x =
        let a, _, r = extendedGcdInt64 x p
