class PascalTriangle(maxN: Int, mod: Int = 0) {
    private val a = Array(maxN + 1) { LongArray(it + 1) }

    init {
        require(mod >= 0)
        a.forEachIndexed { n, row ->
            row[0] = 1
            if (n > 0) {
                row[n] = 1
                (1 until n).forEach { m ->
                    row[m] = a[n - 1][m] + a[n - 1][m - 1]
                }
            }
            if (mod > 0) {
                row.indices.forEach { row[it] %= mod.toLong() }
            }
        }
    }

    operator fun get(n: Int, m: Int): Long = if (m <= n) a[n][m] else 0
}

