        		num[a[i]] = i;
        	}
        	else{
        		x = n - i + num[a[i]];
        	}
        }

        FermatCombination comb = new FermatCombination(n+1, etc);
        FermatCombination counter = new FermatCombination(x, etc);

        for(int i=1;i<=n+1;i++){
        	if(x+1>=i){
        		System.out.println(comb.combine(n+1, i) - counter.combine(x, i-1));
