        //store factorials
        fact[0] = BigInteger.valueOf(1);
        for (int i=1; i<=n+1; i++) {
            fact[i] = fact[i-1].multiply(BigInteger.valueOf(i));
        }

        BigInteger totalComb, repComb;
        // 0..(count before f=f)..f....s..(count after s=n-s)..n
        //for (int i=2; i<=2; i++) {
        for (int i=1; i<=n+1; i++) {
            totalComb = comb(n+1, i); repComb = BigInteger.valueOf(0);
