      }
    }

    int s = -1, t = -1;
    for(int i = 0; i < n + 1; i++){
      if(a[i] == two){
        if(s == -1){
          s = i;
        }
        else{
          t = i;
        }
      }
    }

    long[] fact = new long[n + 1 + 1];
    fact[0] = 1;
    for(int i = 1; i <= n + 1; i++){
      fact[i] = (fact[i - 1] * (long)i) % MOD;
    }
    long[] factInv = new long[n + 1 + 1];
    for(int i = 0; i <= n + 1; i++){
      factInv[i] = pow(fact[i], MOD - 2);
    }

    long[] ans = new long[n + 1];
    int l = (t - s) - 1;
    for(int k = 1; k <= n + 1; k++){
      long tmp0 = 0, tmp1 = 0;
      tmp0 = (fact[n + 1] * factInv[k]) % MOD;
      tmp0 = (tmp0 * factInv[n + 1 - k]) % MOD;
      if(n + 1 - 2 - l - (k - 1) >= 0){
        tmp1 = (fact[n + 1 - 2 - l] * factInv[k - 1]) % MOD;
        tmp1 = (tmp1 * factInv[n + 1 - 2 - l - (k - 1)]) % MOD;
      }
      ans[k - 1] = (tmp0 - tmp1) % MOD;
    }

    StringBuilder sb = new StringBuilder();
    for(int k = 1; k <= n + 1; k++){
      sb.append(ans[k - 1] + System.lineSeparator());
    }

    System.out.print(sb);
  }

  static long pow(long a, long b){
    long base = a;
    long result = 1;
    for(int i = 0; i < 64; i++){
      if((b & (1L << i)) != 0L){
        result = (result * base) % MOD;
      }
      base = (base * base) % MOD;
    }
    return result;
  }
}

