class CombMod {
    long dp[];
    long dpi[];
    long mod;
    BigInteger bigMod;
    BigInteger bigMod2;

    CombMod(int n, int mod) {
        this.mod = mod;
        bigMod = BigInteger.valueOf(mod);
        bigMod2 = BigInteger.valueOf(mod - 2);
        dp = new long[n + 1];
        dpi = new long[n + 1];
        dp[0] = 1;
        dp[1] = 1;
        dpi[1] = 1;
    }

    long fact(int m) {
        if (dp[m] != 0) {
            return dp[m];
        }
        dp[m] = m * fact(m - 1) % mod;
        return dp[m];
    }

    long facti(int m) {
        if (dpi[m] != 0) {
            return dpi[m];
        }
        dpi[m] = BigInteger.valueOf(m).modPow(bigMod2, bigMod).intValue() * facti(m-1) % mod;
        return dpi[m];
    }

    long comb(int m, int n) {
        return (m == n) ? 1:fact(m) * facti(m-n) % mod * facti(n) % mod;
    }
}

