public class Main {
	public static void main(String[] args) {
		new Main().run();
	}

	final long MODULO = 1_000_000_000 + 7;
	int n;
	int[] a;

	void run() {
		Scanner sc = new Scanner();
		n = sc.nextInt();
		long[] fac = new long[n + 2];
		long[] revfac = new long[n + 2];
		long[] rev = new long[n + 2];
		fac[0] = 1;
		for (int i = 1; i < fac.length; ++i) {
			fac[i] = (fac[i - 1] * i) % MODULO;
		}
		rev[1] = 1;
		for (int i = 2; i < rev.length; ++i) {
			rev[i] = (MODULO - rev[(int) MODULO % i] * (MODULO / i) % MODULO) % MODULO;
		}
		revfac[0] = 1;
		for (int i = 1; i < revfac.length; ++i) {
			revfac[i] = (revfac[i - 1] * rev[i]) % MODULO;
		}

		a = new int[n + 1];
		int m = -1;
		boolean[] f = new boolean[n];
		for (int i = 0; i < n; ++i) {
			a[i] = sc.nextInt() - 1;
			if (f[a[i]]) {
				m = a[i];
			} else {
				f[a[i]] = true;
			}
		}
		int k1 = 0, k2 = 0, k3 = 0;
		int i;
		for (i = 0; i < n; ++i) {
			if (a[i] == m) {
				break;
			}
			++k1;
		}
		for (i = i + 1; i < n; ++i) {
			if (a[i] == m) {
				break;
			}
			++k2;
		}
		StringBuilder sb = new StringBuilder();
		k3 = n - 1 - (k1 + k2);
		for (int len = 1; len <= n + 1; ++len) {
			if (len == 1) {
				sb.append(n + "\n");
				continue;
			}
			long ans = 0;
			ans = comb(n - 1, len, fac, revfac);// m:0個
			ans = (ans + comb(n - 1, len - 2, fac, revfac)) % MODULO;// m:2個
			ans = (ans + 2 * comb(n - 1, len - 1, fac, revfac)) % MODULO;// m:1個
			ans = (ans - comb(k1 + k3, len - 1, fac, revfac) + MODULO) % MODULO;// m:1個
			long tmp = comb(n + 1, len, fac, revfac) - comb(k1 + k3, len - 1, fac, revfac);
			while(tmp<0)tmp+=MODULO;
			tmp%=MODULO;
//			tr(tmp, ans);
			// sb.append(ans + "\n");
			sb.append(tmp + "\n");
		}
		System.out.print(sb);
	}

	long comb(int n, int k, long[] fac, long[] revfac) {
		if (n < k)
			return 0;
		return fac[n] * revfac[k] % MODULO * revfac[n - k] % MODULO;
	}

	long pow(long a, long n) {
		long ret = 1;
		for (; n > 0; n >>= 1, a = (a * a) % MODULO) {
			if (n % 2 == 1)
				ret = (ret * a) % MODULO;
		}
		return ret;
	}

	class Scanner {
		private final InputStream in = System.in;
		private final byte[] buffer = new byte[1024];
		private int ptr = 0;
		private int buflen = 0;

		private boolean hasNextByte() {
			if (ptr < buflen) {
				return true;
			} else {
				ptr = 0;
				try {
					buflen = in.read(buffer);
				} catch (IOException e) {
					e.printStackTrace();
				}
				if (buflen <= 0) {
					return false;
				}
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[ptr++];
			else
				return -1;
		}

		private boolean isPrintableChar(int c) {
			return 33 <= c && c <= 126;
		}

		private void skipUnprintable() {
			while (hasNextByte() && !isPrintableChar(buffer[ptr]))
				ptr++;
		}

		public boolean hasNext() {
			skipUnprintable();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (isPrintableChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			long n = 0;
			boolean minus = false;
			int b = readByte();
			if (b == '-') {
				minus = true;
				b = readByte();
			}
			if (b < '0' || '9' < b) {
				throw new NumberFormatException();
			}
			while (true) {
				if ('0' <= b && b <= '9') {
					n *= 10;
					n += b - '0';
				} else if (b == -1 || !isPrintableChar(b)) {
					return minus ? -n : n;
				} else {
					throw new NumberFormatException();
				}
				b = readByte();
			}
		}

		public int nextInt() {
			return (int) nextLong();
		}
	}

	void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

