    void solve() {
        int n = ni();
        int a[] = na(n + 1);
        int t[] = new int[n + 1];
        int d = 0, l = -1, r = -1;
        for (int i : a) {
            if (++t[i] == 2) {
                d = i;
            }
        }
        for (int i = 0; i < a.length; ++i) {
            if (d == a[i]) {
                if (l == -1) {
                    l = i;
                } else {
                    r = i;
                }
            }
        }
        int p = n - r + l;
        long mod = (long) 10e8 + 7;
        Combination2 c = new Combination2(n + 2, mod);
        for (int i = 1; i <= n + 1; ++i) {
            long v = c.combination(n + 1, i);
            if (p >= i - 1) {
                v -= c.combination(p, i - 1);
            }
            out.println(v);
        }
    }

    public class Combination2 {

        int n;
        long mod, fact[], ifact[];

        public Combination2(int n, long mod) {
            this.n = n;
            this.mod = mod;
            fact = new long[n];
            ifact = new long[n];
            fact[0] = 1;
            ifact[0] = 1;
            for (int i = 1; i < n; ++i) {
                fact[i] = fact[i - 1] * i % mod;
                ifact[i] = mod_pow(fact[i], mod - 2);
            }
        }

        long mod_pow(long x, long k) {
            long res = 1;
            while (k > 0) {
                if ((k & 1) == 1) res = res * x % mod;
                x = x * x % mod;
                k /= 2;
            }
            return res;
        }

        public long combination(int n, int k) {
            if (k < 0 || k > n) return 0;
            return fact[n] * ifact[k] % mod * ifact[n - k] % mod;
        }
    }


