using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Text;
using static System.Math;

class Program
{
    static int n;
    static int[] a;
    static long mod = (long)1e9 + 7;

    static void Main()
    {
        /* 入力を受け取る */
        n = int.Parse(Console.ReadLine());
        a = Console.ReadLine().Split().Select(int.Parse).ToArray();

        /* 重複について
         *   l個 重複左 (n - l - r)個 重複右 r個
         *  なるl,rを調べる */
        bool[] check = new bool[n + 1]; // check[i] : iがすでに登場したか
        int d = 0; // 重複する数を格納
        for (int i = 0; i <= n; i++)
        {
            if (check[a[i]]) // すでに登場していれば重複
            {
                d = a[i];
                break;
            }
            check[a[i]] = true; // 登場済みに
        }
        int l = 0;
        int r = 0;
        for (; l <= n; l++) // lを決定
            if (a[l] == d)
                break;
        for (; r <= n; r++) // rを決定
            if (a[n - r] == d)
                break;

        /* Combination計算の前処理 */
        Comb c = new Comb(n, mod);

        /* 各kについて答えを計算 */
        for (int k = 1; k <= n + 1; k++)
        {
            long ans = 0;
            ans += c.Com(n - 1, k);
            ans += 2 * c.Com(n - 1, k - 1) % mod;
            ans %= mod;
            ans -= c.Com(l + r, k - 1);
            ans += mod;
            ans %= mod;
            ans += c.Com(n - 1, k - 2);
            ans %= mod;
            Console.WriteLine(ans);
        }
    }
}

class Comb // 組み合わせ計算用のクラス
{
    private long size;
    private long[] inv;
    private long[] kai;
    private long[] invkai;
    private long mod;
    public Comb(long size, long mod)
    {
        this.size = size;
        this.mod = mod;
        inv = new long[size + 1];
        kai = new long[size + 1];
        invkai = new long[size + 1];
        inv[1] = 1;
        for (int i = 2; i <= size; i++)
            inv[i] = mod - (mod / i) * inv[mod % i] % mod;
        kai[0] = 1;
        invkai[0] = 1;
        for (int i = 1; i <= size; i++)
        {
            kai[i] = kai[i - 1] * i % mod;
            invkai[i] = invkai[i - 1] * inv[i] % mod;
        }
    }
    public long Com(long a, long b)
    {
        if (a < b || b < 0)
            return 0;
        return (invkai[b] * invkai[a - b]) % mod * kai[a] % mod;
    }
}

using System;
