public class Program
{

    public void Proc()
    {
        int itemCount = int.Parse(Reader.ReadLine()) + 1;
        int[] items = Reader.ReadLine().Split(' ').Select(a => int.Parse(a)).ToArray();
        int[] sameIdx = GetSameIndex(items);

        long[] ans = new long[itemCount + 1];
        for (int i = 1; i <= itemCount; i++) {
            if(i==1){
                ans[i] = itemCount - 1;
            } else {
                ans[i] += GetKumiawase(i, itemCount);
                ans[i] -= GetKumiawase(i - 1, itemCount - (sameIdx[1]-sameIdx[0]+1));
			}
        }


        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= itemCount; i++) {
            sb.AppendLine(ans[i].ToString());
        }
        Console.Write(sb.ToString());
	}

    private int[] GetSameIndex(int[] target) {
        Dictionary<int, int> tmp = new Dictionary<int, int>();
        for (int i = 0; i < target.Length; i++) {
            if(tmp.ContainsKey(target[i])) {
                return new int[] { tmp[target[i]], i };
            }
            tmp[target[i]] = i;
        }
        return null;
    }

    private long Mod = 1000000000 + 7;

    private Dictionary<int, Dictionary<int, long>> dic = new Dictionary<int, Dictionary<int, long>>();
    private long GetKumiawase(int mustSelect, int remain) {
        if(mustSelect==1) {
            return remain;
        }
        if(mustSelect==remain) {
            return 1;
        }
        if(mustSelect<=0) {
            return 1;
        }
        if(mustSelect>remain) {
            return 0;
        }
        if(!dic.ContainsKey(mustSelect)) {
            dic.Add(mustSelect, new Dictionary<int, long>());
        }
        if(dic[mustSelect].ContainsKey(remain)) {
            return dic[mustSelect][remain];
        }
        if(dic.ContainsKey(mustSelect-remain)&&dic[mustSelect-remain].ContainsKey(remain)) {
            dic[mustSelect][remain] = dic[mustSelect - remain][remain];
            return dic[mustSelect][remain];
        }

        long ans = 0;
        for (int i = 1; i <= remain; i++) {
			long ret = GetKumiawase(mustSelect - 1, remain - i);
			if (ret > 0)
			{
                ans += ret;
                ans = ans % Mod;
			}
		}
        dic[mustSelect][remain] = ans;
        return ans;
    }

