            var n = int.Parse(ReadLine());
            var fact = FoldMap(new Range(1, n + 1).Select(_ => new LongWithMod { Value = _ }))(1, (a, b) => a * b).ToArray();
            var factInverse = fact.Select(_ => _ ^ (Mod - 2)).ToArray();
            var Factorial = new Func<int, LongWithMod>(_ => (_ == 0) ? 1 : fact[_ - 1]);
            var FactorialInverse = new Func<int, LongWithMod>(_ => (_ == 0) ? 1 : factInverse[_ - 1]);
            var Combination = new Func<int, int, LongWithMod>((a, b) => (a >= b) ? Factorial(a) * FactorialInverse(a - b) * FactorialInverse(b) : 0);
            var aseries = ReadLine().Trim().Split(' ').Select(_ => int.Parse(_)).ToArray();
            var doubled = aseries.Sum() - (n + 1) * n / 2;
            var doubledIndex = aseries.Select((num, idx) => new Tuple<int, int>(num, idx)).Where(num => num.Item1 == doubled).Select(_ => _.Item2).Aggregate((a, b) => b - a);
            /*
            A[s] == A[t] (s < t)
            => S(A[0..-1], k) == (n+1)Ck - (n-t)C(k-1)
            */
            for (var k = 1; k <= n + 1; ++k) {
                WriteLine(Combination(n + 1, k) - Combination(n - doubledIndex, k - 1));
            }
        }
        static Func<T, Func<T, T, T>, IEnumerable<T>> FoldMap<T>(IEnumerable<T> numerable)
        {
            return new Func<T, Func<T, T, T>, IEnumerable<T>>
            (
                (init, func) => new FoldMapEnumerable<T, T>(init, func, numerable)
            );
        }
        class FoldMapEnumerable<T, F> : IEnumerable<T>
        {
            T init;
            Func<T, F, T> func;
            IEnumerable<F> numerable;
            public FoldMapEnumerable(T i, Func<T, F, T> f, IEnumerable<F> n)
            {
                init = i; func = f; numerable = n;
            }
            public IEnumerator<T> GetEnumerator()
            {
                foreach(var n in numerable) {
                    yield return init = func(init, n);
                }
            }

            IEnumerator IEnumerable.GetEnumerator()
            {
                throw new NotImplementedException();
            }
        }
        class Range : IEnumerable<int>
        {
            int _from, _to;
            public Range(int from, int to)
            {
                _from = from; _to = to;
            }

            public IEnumerator<int> GetEnumerator()
            {
                for (var i = _from; i <= _to; ++i) yield return i;
            }

            IEnumerator IEnumerable.GetEnumerator()
            {
                throw new NotImplementedException();
            }
        }
        struct LongWithMod
        {
            public long Value;
            static public long Mod;
            static public implicit operator long(LongWithMod l)
            {
                return l.Value;
            }
            static public implicit operator LongWithMod(int num)
            {
                return new LongWithMod { Value = num };
            }
            public static LongWithMod operator +(LongWithMod a, LongWithMod b)
            {
                return new LongWithMod { Value = (a.Value + b.Value) % Mod };
            }
            public static LongWithMod operator -(LongWithMod a, LongWithMod b)
            {
                return new LongWithMod { Value = (a.Value - b.Value) % Mod };
            }
            public static LongWithMod operator *(LongWithMod a, LongWithMod b)
            {
                return new LongWithMod { Value = (a.Value * b.Value) % Mod };
            }
            public static LongWithMod operator ^(LongWithMod a, long e){
                if (e == 0) return 1;
                else {
                    var next = a ^ (e / 2);
                    return next * next * ((e % 2 == 1) ? a : 1);
                }
            }
        }
    }
