class Combination

  def initialize(n)
    @mod=10**9+7
    @fact=Array.new(n){0}
    @inv=Array.new(n){0}

    @fact[0]=1
    (1...n).each{|i| @fact[i]=(@fact[i-1]*i)% @mod}
    (0...n).each{|i| @inv[i]=makeinv(@fact[i], @mod)% @mod}
  end

  def mypow(x, n)
    if n==0
      1
    elsif n%2==0
      mypow(x*x% @mod, n/2)% @mod
    else
      x*mypow(x, n-1)% @mod
    end
  end

  def makeinv(x, p)
    mypow(x, p-2)
  end

  def comb(n, r)
    @fact[n]*@inv[n-r]*@inv[r]% @mod
  end
end

