long pow(long n, long k) {
    if(k == 0) {
        return 1;
    }
    long tmp = pow(n, k/2) % p;
    if(k%2 == 0) { 
        return (tmp * tmp) % p;
    } else {
        return (((tmp * tmp) % p) * n) % p;
    }
}

