    for (int i = 0; i < a.length; i++) {
        if (a[i] in d) {
            lo = d[a[i]] + 1;
            hi = i + 1;
            break;
        }
        d[a[i]] = i;
    }

    int span = hi - lo;
    foreach (k; 1..n+2) {
        long ans = nck(n + 1, k) - nck(lo - 1 + (n + 1) - hi, k - 1);
        writeln(ans % MOD);
    }
}

