def mul_mod(a, b):
    return (a % MOD) * (b % MOD) % MOD


def power_mod(a, b):
    if b == 0:
        return 1
    if b % 2 == 0:
        d = power_mod(a, b // 2)
        return d * d % MOD
    return a * power_mod(a, b - 1) % MOD


def fact_mod(N):
    fact = []
    for i in range(N + 1):
        if i == 0:
