        else:
            fact.append(fact[-1] * i % MOD)
    return fact


def comb_mod(n, r, fact):
    res = fact[n]
    a = power_mod(fact[n - r], MOD - 2)
    b = power_mod(fact[r], MOD - 2)
    res = mul_mod(res, a)
    res = mul_mod(res, b)
    return res


