def binary_exp_with_mod(x,n,mod):
  p = x
  ret = 1
  while n > 0:
    if n % 2 == 0:
      p = (p * p) % mod
      n /= 2
    else:
      ret = (ret * p) % mod
      n -= 1
  return ret

