def nCr(n, r):
    global d_comb
    if n < 0 or r < 0 or n < r:
        return 0
    elif n == 0 or r == 0:
        return 1

    if (n - 1, r - 1) in d_comb:
        left = d_comb[(n - 1, r - 1)]
    else:
        left = nCr(n - 1, r - 1)
        d_comb[(n - 1, r - 1)] = left


    if (n - 1, r) in d_comb:
        right = d_comb[(n - 1, r)]
    else:
        right = nCr(n - 1, r)
        d_comb[(n - 1, r)] = right

    return left + right


def solve(n, a):
