struct Comb {
    fac: Vec<u64>,
    finv: Vec<u64>,
    inv: Vec<u64>,
}
#[allow(dead_code)]
impl Comb {
    fn new(n: usize) -> Self {
        let mut fac = vec![0; n];
        let mut finv = vec![0; n];
        let mut inv = vec![0; n];
        fac[0] = 1;
        fac[1] = 1;
        finv[0] = 1;
        finv[1] = 1;
        inv[1] = 1;
        for i in 2..n {
            let iu64 = i as u64;
            fac[i] = fac[i - 1] * iu64 % M;
            inv[i] = M - inv[(M % iu64) as usize] * (M / iu64) % M;
            finv[i] = finv[i - 1] * inv[i] % M;
        }
        Comb {
            fac: fac,
            finv: finv,
            inv: inv,
        }
    }
    fn of(&self, n: usize, k: usize) -> u64 {
        if n < k {
            0
        } else {
            self.fac[n] * (self.finv[k] * self.finv[n - k] % M) % M
        }
    }
    #[doc = " combination with repetition"]
    fn rep(&self, n: usize, k: usize) -> u64 {
        self.of(n + k - 1, k)
    }
}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

