    }
}

mod reader {
    use std::fmt::Debug;
    use std::str::FromStr;
    use std::collections::VecDeque;
    use std::io::{self, Read};

    fn _read_line() -> String {
        let mut buf = String::new();
        let _ = io::stdin().read_to_string(&mut buf);
        buf
    }

    fn _read_vec_deque_string() -> VecDeque<String> {
        _read_line()
            .split_whitespace()
            .map(|s| s.to_string())
            .collect()
    }

    pub struct Reader {
        buf: VecDeque<String>,
    }

    #[allow(dead_code)]
    impl Reader {
        pub fn new() -> Reader {
            Reader { buf: VecDeque::new() }
        }

        fn update_buf(&mut self) {
            if self.buf.is_empty() {
                self.buf = _read_vec_deque_string();
            }
        }

        pub fn next<T>(&mut self) -> T
        where
            T: FromStr,
            T::Err: Debug,
        {
            self.update_buf();
            self.buf.pop_front().unwrap().parse::<T>().unwrap()
        }

        pub fn next_n<T>(&mut self, n: usize) -> Vec<T>
        where
            T: FromStr,
            T::Err: Debug,
        {
            let mut vec: Vec<T> = Vec::with_capacity(n);

            for _ in 0..n {
                vec.push(self.next());
            }
            vec
        }
    }
}

fn mod_pow(mut x: i64, mut p: i64, MOD: i64) -> i64 {
    let mut res = 1;
    while p > 0 {
        if p % 2 == 1 {
            res = res * x % MOD;
        }
        p /= 2;
        x = x * x % MOD;
    }
    res
}

fn comb(n: i64, r: i64, fact: &[i64], MOD: i64) -> i64 {
    if r < 0 || r > n {
        0
    } else {
        fact[n as usize] * mod_pow(fact[r as usize], MOD - 2, MOD) % MOD *
            mod_pow(fact[(n - r) as usize], MOD - 2, MOD) % MOD
    }
}

