pub fn inv_mod(x: i64, modulus: i64) -> i64 {
    let mut r0 = x;
    let mut r1 = modulus;
    let mut x0 = 1;
    let mut x1 = 0;
    while r1 > 0 {
        let q = r0 / r1;
        r0 = r0 % r1;
        std::mem::swap(&mut r0, &mut r1);
        x0 = x0 - q * x1;
        std::mem::swap(&mut x0, &mut x1);
    }
    let res = x0 % modulus;
    if res < 0 { res + modulus } else { res }
}

