        let a = mod_comb(n + 1, k, M, &fact);
        let b = mod_comb(dupe_pos[0], k - 1, M, &fact);
        let c = mod_comb(n - dupe_pos[1], k - 1, M, &fact);

        println!("{}", (a + 2 * M - b - c) % M);
    }
}

