fn solve() {
    input! {
        N: usize,
        A: [usize; N+1],
    }
    let mut count = vec![0; N+1];
    let mut dup_a = 0;
    for a in A.clone() {
        count[a] += 1;
        if count[a] == 2 {
            dup_a = a;
        }
    }
    // dbg!(dup_a);
    let mut dup_i = vec![];
    for i in 0..N+1 {
        if A[i] == dup_a {
            dup_i.push(i+1);
        }
    }
    // dbg!(&dup_i);
    let A = dup_i[0];
    let B = dup_i[1];
    let p: usize = 1_000_000_007;
    let modcomb = ModComb::new(N+1, p);
    for k in 1..N+2 {
        let res = p + modcomb.nCk(N+1, k) - modcomb.nCk((A-1)+(N+1-B), k-1);
        let res = (res+p) % p;
        println!("{}", res);
    }
}
pub fn modpow(x: usize, n: usize, m: usize) -> usize {
    let mut res = 1;
    let mut x = x % m;
    let mut n = n;
    while n > 0 {
        if n & 1 == 1 {
            res = (res * x) % m;
        }
        x = (x * x) % m;
        n >>= 1;
    }
    res
}
struct ModComb {
    po: Vec<usize>,
    inv: Vec<usize>,
    n: usize,
    p: usize,
}
impl ModComb {
    // O(N)
    fn initialize(ft: &mut Self) {
        let n = ft.n as usize;

        ft.po[0] = 1;
        for i in 1..n {
            ft.po[i] = (ft.po[i-1] * i) % ft.p;
        }
        ft.inv[n-1] = modpow(ft.po[n-1], ft.p-2, ft.p);
        for i in (0..n-1).rev() {
            ft.inv[i] = (ft.inv[i+1] * (i+1)) % ft.p;
        }
    }
    fn new(max_n: usize, p: usize) -> ModComb {
        // nHk needs twice the length of the max_n.
        // since it doesn't affect the computational order, we always double the number for convenience.
        let mut ft = ModComb {
            po: vec![0; max_n+1 as usize],
            inv: vec![0; max_n+1 as usize],
            n: max_n+1,
            p: p,
        };
        Self::initialize(&mut ft);
        ft
    }
    fn nCk(&self, n: usize, k: usize) -> usize {
        if n < k { return 0; }
        (self.nPk(n,k) * self.inv[k as usize]) % self.p 
    }
    fn nPk(&self, n: usize, k: usize) -> usize {
        if n < k { return 0; }
        self.po[n as usize] * self.inv[(n-k) as usize] % self.p
    }
    fn nHk(&self, n: usize, k: usize) -> usize {
        if n==0 && k==0 { return 1 }
        self.nCk(n+k-1,k)
    }
}

