        sum += comb.combination(n-2, c);

        // 1: one
        sum += comb.combination(n-2, c-1) * 2;
        sum += MOD - comb.combination(outer, c-1);

        if c >= 2 {
            sum += comb.combination(n-2, c-2);
        }

        println!("{}", sum % MOD);
    }
}

